    /// Record the route's session binding (called from `on_bind`). Last write wins for a
    /// reused channel — the daemon won't reuse a channel without a `route.gone` first, so
    /// this only overwrites a stale entry that somehow survived (defensive).
    fn bind_route(&self, channel: u16, binding: SessionBinding) {
        DISPATCH_HEALTH.route_open(channel);
        self.threshold_logged_routes
            .lock()
            .expect("threshold log mutex")
            .remove(&channel);
        self.transform_route_channels
            .lock()
            .expect("transform route channels mutex")
            .remove(&channel);
        let replacement = {
            let mut bindings = self.bindings.lock().expect("bindings mutex");
            let previous = bindings.insert(channel, binding);
            previous.and_then(|previous| {
                let still_bound = bindings
                    .values()
                    .any(|candidate| candidate.session == previous.session);
                (!still_bound).then_some(previous)
            })
        };
        if let Some(previous) = replacement.as_ref() {
            self.clear_note_evaluation_capability_if_unbound(&previous.project_root);
        }
        let replacement_session = replacement.map(|previous| previous.session);
        if let Some(session_id) = replacement_session {
            self.state_sync_seeds
                .lock()
                .expect("state sync seed mutex")
                .evict(&session_id);
            self.discard_transform_pages_for_route(&session_id, "route_replaced");
            self.state_imports
                .lock()
                .expect("state import mutex")
                .discard(&session_id);
            self.transform_snapshots
                .lock()
                .expect("transform snapshots mutex")
                .remove(&session_id);
            self.serialized_outputs
                .lock()
                .expect("serialized output cache mutex")
                .remove(&session_id);
            self.native_attachments
                .lock()
                .expect("native attachment cache mutex")
                .remove(&session_id);
            self.boundary_tokens
                .lock()
                .expect("boundary token cache mutex")
                .remove(&session_id);
            self.prompt_surface_epochs
                .lock()
                .expect("prompt surface epoch mutex")
                .remove(&session_id);
        }
    }

    fn note_evaluation_capability_key(project_root: &Path) -> String {
        canonical_root(project_root).to_string_lossy().into_owned()
    }

    fn set_note_evaluation_capability(&self, project_root: &Path, available: bool) {
        self.note_evaluation_capabilities
            .lock()
            .expect("note evaluation capability mutex")
            .insert(
                Self::note_evaluation_capability_key(project_root),
                available,
            );
    }

    fn note_evaluation_capability(&self, project_root: &Path) -> bool {
        self.note_evaluation_capabilities
            .lock()
            .expect("note evaluation capability mutex")
            .get(&Self::note_evaluation_capability_key(project_root))
            .copied()
            .unwrap_or(false)
    }

    fn clear_note_evaluation_capability_if_unbound(&self, project_root: &Path) {
        let key = Self::note_evaluation_capability_key(project_root);
        let still_bound = self
            .bindings
            .lock()
            .expect("bindings mutex")
            .values()
            .any(|binding| Self::note_evaluation_capability_key(&binding.project_root) == key);
        if !still_bound {
            self.note_evaluation_capabilities
                .lock()
                .expect("note evaluation capability mutex")
                .remove(&key);
        }
    }

    fn discard_state_sync_seed(&self, session_id: &str) {
        self.state_sync_seeds
            .lock()
            .expect("state sync seed mutex")
            .discard_pending(session_id);
    }

    fn refresh_oldest_queued_at_ms(&self) {
        let oldest = self
            .transform_pages
            .lock()
            .expect("transform page mutex")
            .oldest_queued_at_ms()
            .unwrap_or(0);
        DISPATCH_HEALTH
            .oldest_queued_at_ms
            .store(oldest, Ordering::Relaxed);
    }

    fn log_transform_page_discard(&self, session_id: &str, staged_pages: usize, trigger: &str) {
        let line = format!(
            "transform_page_collection_discarded session={session_id} staged_pages={staged_pages} trigger={trigger}"
        );
        tracing::warn!("mc-module: {line}");
        #[cfg(test)]
        self.transform_page_discard_logs
            .lock()
            .expect("transform page discard logs mutex")
            .push(line);
    }

    fn log_unprobed_todo_bust(
        &self,
        session_id: &str,
        possible_stale_mint: bool,
        decision: &str,
        reason: &str,
    ) {
        let line = format!(
            "mc-todo-verdict session={session_id} unprobed_bust=1 possible_stale_mint={} decision={decision} reason={reason}",
            u8::from(possible_stale_mint)
        );
        tracing::info!("{line}");
        #[cfg(test)]
        self.todo_verdict_diagnostic_logs
            .lock()
            .expect("todo verdict diagnostic logs mutex")
            .push(line);
    }

    fn discard_transform_pages_for_route(&self, session_id: &str, trigger: &str) {
        let staged_pages = self
            .transform_pages
            .lock()
            .expect("transform page mutex")
            .discard(session_id);
        if let Some(staged_pages) = staged_pages {
            self.log_transform_page_discard(session_id, staged_pages, trigger);
        }
        self.refresh_oldest_queued_at_ms();
    }

    fn discard_transform_pages(&self, session_id: &str) {
        self.transform_pages
            .lock()
            .expect("transform page mutex")
            .discard(session_id);
        self.refresh_oldest_queued_at_ms();
    }

    /// Reconstruct a full ingress snapshot from bounded projection/native cores plus a validated
    /// caller tail. Small entries may fall back to their full transform snapshot, but a
    /// giant request does not need to retain provider sidecar trees to keep delta transport alive.
    fn expand_transform_tail_delta(
        &self,
        parsed: &mut TransformRequest,
    ) -> Option<NativeDeltaFrontier> {
        let delta = parsed.tail_delta.as_ref().and_then(Value::as_object)?;
        let after = delta.get("after").and_then(Value::as_str)?.to_string();
        let replace_from = delta
            .get("replace_from")
            .and_then(Value::as_u64)
            .and_then(|value| usize::try_from(value).ok())?;
        let native_replace_from = delta
            .get("native_replace_from")
            .and_then(Value::as_u64)
            .and_then(|value| usize::try_from(value).ok())?;
        parsed.full_array_fingerprint.as_ref()?;

        // A store-side rewrite can advance the epoch without updating this process's request
        // snapshot. Load the persisted epoch first, then inspect the bounded projection and native
        // cores so stale process state cannot select an outdated entry.
        let current_revert_epoch = self
            .store
            .get()?
            .load(&parsed.session_id)
            .ok()?
            .meta
            .revert_epoch;
        let projection_cache = self.lookup_projection_cache(
            parsed,
            current_revert_epoch,
            &after,
            replace_from,
            ProjectionCacheKeyMode::Normal,
        );
        let fallback_request = self
            .transform_snapshots
            .lock()
            .expect("transform snapshots mutex")
            .ready_delta_request(&parsed.session_id)
            .filter(|request| request.full_array_fingerprint.as_deref() == Some(after.as_str()));

        let mut messages = projection_cache
            .as_ref()
            .and_then(|cache| cache.projection.reattach_messages_prefix(replace_from))
            .or_else(|| {
                let request = fallback_request.as_ref()?;
                (replace_from <= request.messages.len())
                    .then(|| request.messages[..replace_from].to_vec())
            })?;
        let mut current_messages = std::mem::take(&mut parsed.messages);
        messages.append(&mut current_messages);

        let (native_prefix, native_prefix_retained_bytes) = if native_replace_from == 0 {
            (Vec::new(), Vec::new())
        } else {
            self.native_attachments
                .lock()
                .expect("native attachment cache mutex")
                .delta_native_prefix(
                    &parsed.session_id,
                    current_revert_epoch,
                    &after,
                    native_replace_from,
                )
                .or_else(|| {
                    let request = fallback_request.as_ref()?;
                    let previous_native = request.native_messages.as_ref()?;
                    (native_replace_from <= previous_native.len()).then(|| {
                        let prefix = previous_native[..native_replace_from]
                            .iter()
                            .cloned()
                            .map(Arc::new)
                            .collect::<Vec<_>>();
                        let retained_bytes = previous_native[..native_replace_from]
                            .iter()
                            .map(native_value_retained_bytes)
                            .collect();
                        (prefix, retained_bytes)
                    })
                })?
        };
        let mut native_messages = native_prefix
            .iter()
            .map(|message| message.as_ref().clone())
            .collect::<Vec<_>>();
        let mut current_native = parsed.native_messages.take()?;
        native_messages.append(&mut current_native);

        parsed.messages = messages;
        parsed.native_messages = Some(native_messages);
        parsed.tail_delta = None;
        Some(NativeDeltaFrontier {
            after,
            native_replace_from,
            native_prefix,
            native_prefix_retained_bytes,
            projection_cache,
        })
    }

    fn lookup_projection_cache(
        &self,
        request: &TransformRequest,
        revert_epoch: u64,
        after: &str,
        replace_from: usize,
        mode: ProjectionCacheKeyMode,
    ) -> Option<ProjectionCacheInput> {
        self.projections
            .lock()
            .expect("projection cache mutex")
            .snapshot(&request.session_id, revert_epoch)
            .and_then(|snapshot| {
                validated_projection_cache_input(request, &snapshot, after, replace_from, mode)
            })
    }

    fn lookup_full_projection_cache(
        &self,
        request: &TransformRequest,
    ) -> Option<ProjectionCacheInput> {
        let after = request.full_array_fingerprint.as_deref()?;
        let revert_epoch = self
            .store
            .get()?
            .load(&request.session_id)
            .ok()?
            .meta
            .revert_epoch;
        self.lookup_projection_cache(
            request,
            revert_epoch,
            after,
            request.messages.len(),
            ProjectionCacheKeyMode::Normal,
        )
    }

    /// The most recent full transform request retains raw CK parts until its bounded
    /// snapshot is evicted. ctx_expand uses it only for a same-session recovery view;
    /// persisted historian transcripts remain the durable fallback for the default view.
    fn cached_expand_messages(&self, session_id: &str) -> Option<Vec<ck_wire::CkIngressMessage>> {
        self.transform_snapshots
            .lock()
            .expect("transform snapshots mutex")
            .ready_delta_request(session_id)
            .map(|request| request.messages.clone())
    }

    fn store_projection_cache(
        &self,
        request: &TransformRequest,
        revert_epoch: u64,
        projection: Arc<crate::ck_wire::FlatProjection>,
        prior: Option<&ProjectionCacheInput>,
    ) -> usize {
        let reusable_prefix = prior
            .filter(|cache| {
                cache.replace_from <= request.messages.len()
                    && cache.replace_from <= cache.message_retained_bytes.len()
            })
            .map_or(0, |cache| cache.replace_from);
        let mut message_retained_bytes = prior
            .filter(|_| reusable_prefix > 0)
            .map(|cache| cache.message_retained_bytes[..reusable_prefix].to_vec())
            .unwrap_or_default();
        message_retained_bytes.reserve(request.messages.len().saturating_sub(reusable_prefix));
        message_retained_bytes.extend(request.messages[reusable_prefix..].iter().map(|message| {
            message.mid.capacity().saturating_add(
                crate::retained_size::ck_wire_message_retained_bytes(&message.ck)
                    .saturating_sub(std::mem::size_of::<ck_wire::CkWireMessage>()),
            )
        }));
        let request_message_charge = request
            .messages
            .capacity()
            .saturating_mul(std::mem::size_of::<ck_wire::CkIngressMessage>())
            .saturating_add(message_retained_bytes.iter().copied().sum::<usize>());
        self.projections
            .lock()
            .expect("projection cache mutex")
            .replace(
                &request.session_id,
                revert_epoch,
                ProjectionCacheSnapshot {
                    context: projection_cache_context(request),
                    full_array_fingerprint: request.full_array_fingerprint.clone(),
                    projection,
                    message_retained_bytes: Arc::new(message_retained_bytes),
                },
            );
        request_message_charge
    }

    fn transform_page_in_progress(&self, session_id: &str) -> bool {
        self.transform_pages
            .lock()
            .expect("transform page mutex")
            .sessions
            .get(session_id)
            .is_some_and(|state| TransformPageCoordinator::is_pending(&state.phase))
    }

    /// Remove a route and evict process-local session state after its final binding closes.
    fn unbind_route(&self, channel: u16) {
        self.threshold_logged_routes
            .lock()
            .expect("threshold log mutex")
            .remove(&channel);
        DISPATCH_HEALTH.route_gone(channel);
        self.transform_route_channels
            .lock()
            .expect("transform route channels mutex")
            .remove(&channel);
        let (removed_root, last_session_route) = {
            let mut bindings = self.bindings.lock().expect("bindings mutex");
            let removed = bindings.remove(&channel);
            let last_session_route = removed.as_ref().and_then(|binding| {
                let still_bound = bindings
                    .values()
                    .any(|candidate| candidate.session == binding.session);
                (!still_bound).then_some(binding.session.clone())
            });
            (
                removed.map(|binding| binding.project_root),
                last_session_route,
            )
        };
        if let Some(root) = removed_root {
            self.clear_note_evaluation_capability_if_unbound(&root);
        }
        if let Some(session) = last_session_route {
            if session.starts_with("mc-dreamer:") {
                self.unregister_dreamer_run(&session);
            }
            self.scheduler_observations
                .lock()
                .expect("scheduler observations mutex")
                .remove(&session);
            self.runtime_store_errors
                .lock()
                .expect("runtime store errors mutex")
                .remove(&session);
            self.state_sync_seeds
                .lock()
                .expect("state sync seed mutex")
                .evict(&session);
            self.discard_transform_pages_for_route(&session, "route_teardown");
            self.state_imports
                .lock()
                .expect("state import mutex")
                .discard(&session);
            self.transform_snapshots
                .lock()
                .expect("transform snapshots mutex")
                .remove(&session);
            self.serialized_outputs
                .lock()
                .expect("serialized output cache mutex")
                .remove(&session);
            self.native_attachments
                .lock()
                .expect("native attachment cache mutex")
                .remove(&session);
            self.projections
                .lock()
                .expect("projection cache mutex")
                .remove(&session);
            self.boundary_tokens
                .lock()
                .expect("boundary token cache mutex")
                .remove(&session);
            self.prompt_surface_epochs
                .lock()
                .expect("prompt surface epoch mutex")
                .remove(&session);
            self.evict_session_lineage_caches(&session);
        }
    }

    /// Retention bound for the per-session lineage caches `transform_session_roots` and
    /// `guidance_dates`: an entry lives only while the session has a bound route, and is
    /// evicted when its last route closes (`unbind_route`). `session.delete` also evicts the
    /// guidance date, and the root entry when no route is still bound. Without this both
    /// maps grow with every session the process has ever served.
    ///
    /// Evicting cannot change served bytes for a returning session, because each map is a
    /// process-local copy of something the store already holds, and the rebuild is the same
    /// one a module restart performs:
    /// - `transform_session_roots` caches the durable `mc_transform_session_roots` proof.
    ///   `module_knows_transform_session` re-reads that row (plus the cache-state row) on a
    ///   miss and re-caches it, and a new transform on the session re-inserts its root.
    /// - `guidance_dates` holds a date line only until it is persisted in the session's
    ///   `ModuleMeta::guidance_date` (or the first committed transform). A persisted date is
    ///   always read from the store first, so only a session with no durable row loses its
    ///   in-memory line, exactly as it would across a restart.
    fn evict_session_lineage_caches(&self, session_id: &str) {
        self.transform_session_roots
            .lock()
            .expect("transform session roots mutex")
            .remove(session_id);
        self.guidance_dates
            .lock()
            .expect("guidance date mutex")
            .remove(session_id);
    }

    /// Resolve the binding for a transform request on `channel`, FAIL-LOUD: the channel
    /// must be bound AND its bound session must match the request's `session_id`. Returns
    /// the full binding (project_root + frozen budget) the caller keys its store reads off,
    /// never a default. The resolve-or-reject is enforced from the start, and it changes no
    /// transform output — a correctly-bound request resolves and proceeds identically.
    fn resolve_binding(
        &self,
        channel: u16,
        request_session: &str,
    ) -> Result<SessionBinding, BindingError> {
        let map = self.bindings.lock().expect("bindings mutex");
        let binding = map.get(&channel).ok_or(BindingError::Unbound)?;
        if binding.session != request_session {
            return Err(BindingError::SessionMismatch);
        }
        Ok(binding.clone())
    }

    fn state_sync_binding(
        &self,
        channel: u16,
        request_session: Option<&str>,
    ) -> Result<SessionBinding, HandlerOutcome> {
        let binding = self
            .bindings
            .lock()
            .expect("bindings mutex")
            .get(&channel)
            .cloned()
            .ok_or_else(|| HandlerOutcome::Error {
                code: "route_unbound".to_string(),
                message: "state sync on a channel with no session binding".to_string(),
            })?;
        if let Some(request_session) = request_session {
            if binding.session != request_session {
                return Err(HandlerOutcome::Error {
                    code: "session_mismatch".to_string(),
                    message: "request session_id does not match the channel's bound session"
                        .to_string(),
                });
            }
        }
        Ok(binding)
    }

    /// Return the channel binding without comparing a request session. OpenCode Rust facade
    /// routes bind a real session id, while Claude Code facade routes bind an instance token;
    /// `resolve_facade_scope` applies the corresponding identity mode before touching the store.
    fn facade_binding(&self, channel: u16) -> Result<SessionBinding, BindingError> {
        self.bindings
            .lock()
            .expect("bindings mutex")
            .get(&channel)
            .cloned()
            .ok_or(BindingError::Unbound)
    }

    fn module_knows_transform_session(&self, session_id: &str, project_root: &Path) -> bool {
        let canonical_project_root = canonical_root(project_root);
        let root_observed = self
            .transform_session_roots
            .lock()
            .expect("transform session roots mutex")
            .get(session_id)
            .is_some_and(|roots| {
                roots
                    .iter()
                    .any(|root| canonical_root(root) == canonical_project_root)
            });
        if !root_observed {
            let Some(store) = self.store.get() else {
                return false;
            };
            let durable_root_observed = canonical_project_root.to_str().is_some_and(|root| {
                store
                    .knows_transform_session_root(session_id, root)
                    .unwrap_or(false)
            });
            if !durable_root_observed || !store.has_cache_state(session_id).unwrap_or(false) {
                return false;
            }
            // Cache the durable proof after a process restart. The row pairs the canonical root
            // with the accepted transform commit, so a genuinely different root cannot authorize
            // the same session.
            self.transform_session_roots
                .lock()
                .expect("transform session roots mutex")
                .entry(session_id.to_string())
                .or_default()
                .insert(canonical_project_root.clone());
            return true;
        }
        if self
            .store
            .get()
            .is_some_and(|store| store.has_cache_state(session_id).unwrap_or(false))
        {
            return true;
        }
        self.transform_route_channels
            .lock()
            .expect("transform route channels mutex")
            .values()
            .any(|(session, root)| {
                session == session_id && canonical_root(root) == canonical_project_root
            })
    }

    /// Persist the route's transport-to-identity mapping when a route becomes bound to an
    /// authority-managed project. Unbound administrative calls have no route vocabulary to
    /// record and remain valid.
    fn bind_authority_route(
        &self,
        store: &McStore,
        channel: u16,
        context_store_uuid: &str,
        project: &str,
    ) -> Result<(), McStoreError> {
        let Ok(binding) = self.facade_binding(channel) else {
            return Ok(());
        };
        store.bind_authority_route(
            context_store_uuid,
            project,
            binding.project_root.to_string_lossy().as_ref(),
        )
    }

    fn effective_config(&self, project_root: &Path) -> McModuleConfig {
        #[cfg(test)]
        if let Some(config) = &self.fixed_config {
            return config.clone();
        }
        let config = self
            .config
            .lock()
            .expect("config mutex")
            .effective_for_project(project_root);
        // The publish path runs deep inside the historian, far from any config handle, so
        // the resolved single-store mode is published here where config is already being
        // read. `on` is refused rather than silently downgraded: the writers in this build
        // are shadow/verify only, and a project that asked for real writes must be told.
        match crate::host_store::admit_mode(config.single_store) {
            Ok(mode) => crate::host_store::set_mode(mode),
            Err(error) => {
                crate::host_store::set_mode(crate::host_store::SingleStoreMode::Off);
                crate::host_store::record_mode_refusal(&error);
            }
        }
        config
    }

    fn observe_memory_mirror_frontier(&self, store: &McStore) -> Result<i64, McStoreError> {
        let feed_head = store.changefeed_head("memories")?;
        let live_rows = store.live_memory_row_count()?;
        self.memory_mirror_health
            .observe_frontier(feed_head, live_rows);
        Ok(feed_head)
    }

    fn memory_mirror_status_value(&self, now: u64) -> Value {
        let mirror = self.memory_mirror_health.snapshot(now);
        json!({
            "feed_head": mirror.feed_head,
            "module_live_rows": mirror.module_live_rows,
            "host_cursor": mirror.host_cursor,
            "host_cursor_updated_at_ms": mirror.host_cursor_updated_at_ms,
            "cursor_age_ms": mirror.cursor_age_ms,
            "pending_rows": mirror.pending_rows,
            "stalled": mirror.stalled,
            "code": mirror.stalled.then_some(MEMORY_MIRROR_STALLED_CODE),
        })
    }

    fn augment_memory_mirror_health(&self, mut report: HealthReport, now: u64) -> HealthReport {
        let mirror = self.memory_mirror_health.snapshot(now);
        if let Some(metrics) = report.metrics.as_mut().and_then(Value::as_object_mut) {
            metrics.insert(
                "memory_mirror".to_string(),
                self.memory_mirror_status_value(now),
            );
        }
        if mirror.stalled {
            report.status = HealthStatus::Degraded;
            let mirror_detail = format!(
                "{MEMORY_MIRROR_STALLED_CODE} memory mirror cursor stalled: cursor={} feed_head={} pending_rows={} live_rows={} age_ms={}; send another message to resume it, or run ck doctor drain-authority",
                mirror.host_cursor,
                mirror.feed_head,
                mirror.pending_rows,
                mirror.module_live_rows,
                mirror.cursor_age_ms,
            );
            report.detail = Some(match report.detail {
                Some(detail) => format!("{detail}; {mirror_detail}"),
                None => mirror_detail,
            });
        }
        report
    }

    fn handler_entry_state<'a>(
        store: &McStore,
        session_id: &str,
        snapshot: &'a OnceLock<Option<LoadedState>>,
    ) -> Option<&'a LoadedState> {
        snapshot
            .get_or_init(|| store.load(session_id).ok())
            .as_ref()
    }

    fn historian_active(
        &self,
        store: &McStore,
        session_id: &str,
        entry_snapshot: &OnceLock<Option<LoadedState>>,
    ) -> bool {
        if self
            .live_historian_sessions
            .lock()
            .expect("live historian mutex")
            .contains_key(session_id)
        {
            return true;
        }
        Self::handler_entry_state(store, session_id, entry_snapshot)
            .is_some_and(|state| state.meta.historian.state != HistorianPhase::Idle)
    }

    fn wrapup_active(&self, session_id: &str) -> bool {
        self.wrapup_sessions
            .lock()
            .expect("wrapup sessions mutex")
            .contains_key(session_id)
    }

    fn observed_last_response_at_ms(
        &self,
        store: &McStore,
        session_id: &str,
        entry_snapshot: &OnceLock<Option<LoadedState>>,
    ) -> Option<i64> {
        let mut observations = self
            .scheduler_observations
            .lock()
            .expect("scheduler observations mutex");
        if let Some(observation) = observations.get(session_id) {
            return observation
                .observed_in_process
                .then_some(observation.last_response_at_ms);
        }
        let anchor = Self::handler_entry_state(store, session_id, entry_snapshot)
            .map(|state| state.meta.last_committed_pass_at_ms)
            .unwrap_or(0);
        observations.insert(
            session_id.to_string(),
            SchedulerObservation {
                last_response_at_ms: anchor,
                observed_in_process: false,
            },
        );
        None
    }

    fn record_response_observation(&self, session_id: &str, now: i64) {
        self.scheduler_observations
            .lock()
            .expect("scheduler observations mutex")
            .insert(
                session_id.to_string(),
                SchedulerObservation {
                    last_response_at_ms: now,
                    observed_in_process: true,
                },
            );
    }

    fn guidance_now_ms(&self) -> i64 {
        #[cfg(test)]
        if let Some(now) = *self.guidance_now_ms.lock().expect("guidance clock mutex") {
            return now;
        }
        now_ms()
    }

    fn guidance_date_line(&self) -> String {
        self.guidance_date_line_for_ms(self.guidance_now_ms())
    }

    fn guidance_date_line_for_ms(&self, ms: i64) -> String {
        let date = Local
            .timestamp_millis_opt(ms)
            .single()
            .unwrap_or_else(Local::now)
            .format("%a %b %d %Y");
        format!("Today's date: {date}")
    }

    fn guidance_date_for_transform(&self, session_id: &str, pass_now: i64) -> String {
        self.guidance_dates
            .lock()
            .expect("guidance date mutex")
            .get(session_id)
            .cloned()
            .unwrap_or_else(|| self.guidance_date_line_for_ms(pass_now))
    }

    #[cfg(test)]
    #[allow(dead_code)]
    fn set_guidance_now_ms_for_test(&self, now_ms: i64) {
        *self.guidance_now_ms.lock().expect("guidance clock mutex") = Some(now_ms);
    }

    #[cfg(test)]
    #[allow(dead_code)]
    fn inject_reductions_for_test(&self, session_id: &str, reductions: Vec<ReductionDecision>) {
        self.reduction_injection
            .lock()
            .expect("reduction injection mutex")
            .insert(session_id.to_string(), reductions);
    }

    fn live_historian_completion_wait(
        &self,
        session_id: &str,
    ) -> Option<LiveHistorianCompletionWait> {
        let live = self
            .live_historian_sessions
            .lock()
            .expect("live historian mutex");
        live.get(session_id).map(|entry| {
            Box::pin(entry.completion.clone().notified_owned()) as LiveHistorianCompletionWait
        })
    }

    fn try_claim_live_historian_session(&self, session_id: &str) -> LiveHistorianSessionClaim {
        let mut live = self
            .live_historian_sessions
            .lock()
            .expect("live historian mutex");
        if let Some(entry) = live.get(session_id) {
            return LiveHistorianSessionClaim::Busy(Box::pin(
                entry.completion.clone().notified_owned(),
            ));
        }
        let token = Arc::new(());
        let completion = Arc::new(Notify::new());
        live.insert(
            session_id.to_string(),
            LiveHistorianSession {
                token: Arc::clone(&token),
                completion: Arc::clone(&completion),
            },
        );
        LiveHistorianSessionClaim::Acquired(SessionSetGuard {
            sessions: Arc::clone(&self.live_historian_sessions),
            session_id: session_id.to_string(),
            token,
            completion,
        })
    }

    fn try_claim_recomp_session(&self, session_id: &str) -> Result<StringSetGuard, ()> {
        let mut sessions = self.recomp_sessions.lock().expect("recomp sessions mutex");
        if !sessions.insert(session_id.to_string()) {
            return Err(());
        }
        Ok(StringSetGuard {
            sessions: Arc::clone(&self.recomp_sessions),
            session_id: session_id.to_string(),
        })
    }

    fn try_claim_wrapup_session(&self, session_id: &str) -> Result<WrapupSessionGuard, usize> {
        let mut sessions = self.wrapup_sessions.lock().expect("wrapup sessions mutex");
        if let Some(session) = sessions.get(session_id) {
            return Err(session.rounds);
        }
        let token = Arc::new(());
        sessions.insert(
            session_id.to_string(),
            LiveWrapupSession {
                token: Arc::clone(&token),
                rounds: 0,
            },
        );
        Ok(WrapupSessionGuard {
            sessions: Arc::clone(&self.wrapup_sessions),
            session_id: session_id.to_string(),
            token,
        })
    }

    fn maybe_spawn_reattach(
        &self,
        store: Arc<McStore>,
        parsed: &TransformRequest,
        snapshot_generation: u64,
        binding: &SessionBinding,
        projection: &crate::ck_wire::FlatProjection,
        now: i64,
    ) -> Option<&'static str> {
        let project_path = binding.project_root.to_string_lossy().to_string();
        let harness = binding.harness.clone();
        let config = self.effective_config(&binding.project_root);
        let Ok(loaded) = store.load(&parsed.session_id) else {
            return Some("recovery_load_failed");
        };
        let phase = loaded.meta.historian.state.clone();
        if phase == HistorianPhase::Idle {
            return Some("recovered");
        }
        if self
            .live_historian_sessions
            .lock()
            .expect("live historian mutex")
            .contains_key(&parsed.session_id)
        {
            return None;
        }
        let mut latch = self.reattaching_sessions.lock().expect("reattach mutex");
        if !latch.insert(parsed.session_id.clone()) {
            return Some(match phase {
                HistorianPhase::AwaitingProducer => "reattaching",
                HistorianPhase::Firing
                | HistorianPhase::Reclaiming
                | HistorianPhase::Validating
                | HistorianPhase::Publishing => "recovering",
                HistorianPhase::Idle => "recovered",
            });
        }
        drop(latch);

        let session_id = parsed.session_id.clone();
        let latch = Arc::clone(&self.reattaching_sessions);
        let guard = StringSetGuard {
            sessions: Arc::clone(&latch),
            session_id: session_id.clone(),
        };

        // Restart recovery is where the claim queue's sweep belongs, and it is the
        // only place that calls it: a row is parked by a restart, and a restart is
        // what this function is handling. Without a caller a parked row past its own
        // deadline would sit in the queue forever, because nothing else deletes it
        // and nothing offers it either.
        //
        // The sweep covers the whole queue rather than this session, so a row left
        // behind by a session that has since gone idle is reached by the next
        // recovery on this module rather than waiting for its own session to fire
        // again. It runs before the lookup below so a row that is already past its
        // deadline is dropped here rather than adopted and then released.
        match store.expire_historian_claims(now) {
            Ok(sweep) => {
                for run_id in &sweep.reclaimed {
                    eprintln!(
                        "mc-module: historian run {run_id} put back on offer: its claimant stopped reporting"
                    );
                }
                for run_id in &sweep.dropped {
                    eprintln!(
                        "mc-module: historian run {run_id} dropped from the queue: parked with no report past its deadline"
                    );
                }
            }
            Err(error) => {
                eprintln!("mc-module: historian claim sweep failed: {error}");
            }
        }

        // Only the host lane parks a run in the durable claim queue, so this lookup
        // is skipped on the phases that lane never reaches. A run found here
        // outlived this process: its claimant is either still working or has already
        // left its answer on the row, and releasing the run would throw that away.
        let parked_host_run = match phase {
            HistorianPhase::AwaitingProducer | HistorianPhase::Reclaiming => store
                .load_parked_historian_run(&parsed.session_id)
                .ok()
                .flatten(),
            _ => None,
        };
        if let Some(parked) = parked_host_run {
            // Still out with a claimant and still inside its deadline: the session
            // keeps its single-flight slot, which is exactly what it would be doing
            // if this process had never restarted, and there is no report to
            // validate, so none of the chunk work below is needed.
            //
            // Putting the run back on offer IS needed, and is the whole of what this
            // branch does. A restart can take a row out of the queue while leaving
            // the run itself alive; without this call the shortcut would skip the
            // re-publication and the run would sit parked until its deadline.
            if parked.report.is_none() && parked.deadline_ms > now {
                historian::reoffer_parked_historian_run(&store, &parked.run_id, now);
                drop(guard);
                return Some("reattaching");
            }
            let publication_fence = Arc::new(ReattachSnapshotPublicationFence {
                snapshots: Arc::clone(&self.transform_snapshots),
                session_id: session_id.clone(),
                generation: snapshot_generation,
                #[cfg(test)]
                after_store_publish: Arc::clone(&self.publication_fence_write_hook),
            });
            let live: Vec<_> = projection
                .blocks
                .iter()
                .filter(|b| !b.synthetic)
                .cloned()
                .collect();
            let Some(range) = loaded.meta.historian.chunk_range.clone() else {
                drop(guard);
                return Some("recovering");
            };
            let chunk = historian_chunk::build_historian_chunk(
                parsed.messages.as_slice(),
                &live,
                range.from_ordinal,
                derive_historian_chunk_tokens(config.historian_context_limit_tokens),
                range.to_ordinal.saturating_add(1),
            );
            let prior_compartments = match store.load_compartments(&session_id) {
                Ok(cs) => cs
                    .iter()
                    .map(historian_chunk::stored_range)
                    .collect::<Vec<_>>(),
                Err(_) => Vec::new(),
            };
            let raw_chunk_messages = serde_json::to_string(
                &parsed
                    .messages
                    .iter()
                    .filter(|message| {
                        !message.ck.meta.synthetic
                            && message.ordinal >= chunk.chunk.start_index
                            && message.ordinal <= chunk.chunk.end_index
                    })
                    .collect::<Vec<_>>(),
            )
            .unwrap_or_else(|_| "[]".to_string());
            let boundary_dates = historian_chunk::native_boundary_dates(&parsed.messages);
            let fingerprint_items: Vec<_> =
                chunk.snapshot.iter().map(|item| item.as_item()).collect();
            let observed = historian::compute_chunk_fingerprint(&fingerprint_items);
            let adopt_await_timeout =
                historian::historian_await_timeout(parsed.historian_timeout_ms);
            tokio::spawn(async move {
                let _guard = guard;
                let outcome =
                    historian::adopt_historian_run_on_host(historian::HistorianReattachRequest {
                        store: &store,
                        session_id: &session_id,
                        project_path: &project_path,
                        harness: &harness,
                        observed_chunk_fingerprint: &observed,
                        validation_chunk: &chunk.chunk,
                        chunk_transcript: &chunk.text,
                        raw_chunk_messages: &raw_chunk_messages,
                        boundary_dates: &boundary_dates,
                        prior_compartments: &prior_compartments,
                        validate_options: historian_validate::ValidateOptions {
                            sequence_offset: prior_compartments.len() as u64 + 1,
                            in_emergency: false,
                            memory_enabled: config.memory_enabled,
                            auto_promote: config.auto_promote,
                            user_memory_collection_enabled: config.user_memory_collection_enabled,
                            force_keep_last_compartment: false,
                        },
                        publication_floor_ordinal: range.to_ordinal,
                        await_timeout: adopt_await_timeout,
                        now_ms: now,
                        failure_backoff_at_ms: now + HISTORIAN_FAILURE_BACKOFF_MS,
                        completion_now_ms: now_ms,
                        publication_fence: Some(publication_fence.as_ref()),
                    });
                match outcome {
                    Ok(historian::HostRunAdoption::Published(success)) => eprintln!(
                        "mc-module: historian run {} published from a report a claimant left across a restart",
                        success.producer_run_id
                    ),
                    Ok(historian::HostRunAdoption::Failed { run_id, code }) => eprintln!(
                        "mc-module: historian run {run_id} released for {session_id}: claimant reported {code}"
                    ),
                    Ok(historian::HostRunAdoption::Released { run_id }) => eprintln!(
                        "mc-module: historian run {run_id} released for {session_id}: no report before its deadline"
                    ),
                    Ok(
                        historian::HostRunAdoption::NotParked
                        | historian::HostRunAdoption::StillOut { .. },
                    ) => {}
                    Err(e) => eprintln!(
                        "mc-module: historian host-run adoption failed for {session_id}: {e}"
                    ),
                }
            });
            return Some("reattaching");
        }

        match phase {
            HistorianPhase::AwaitingProducer => {
                let publication_fence = Arc::new(ReattachSnapshotPublicationFence {
                    snapshots: Arc::clone(&self.transform_snapshots),
                    session_id: session_id.clone(),
                    generation: snapshot_generation,
                    #[cfg(test)]
                    after_store_publish: Arc::clone(&self.publication_fence_write_hook),
                });
                let factory = Arc::clone(&self.producer_factory);
                let project_root = PathBuf::from(&project_path);
                let live: Vec<_> = projection
                    .blocks
                    .iter()
                    .filter(|b| !b.synthetic)
                    .cloned()
                    .collect();
                let Some(range) = loaded.meta.historian.chunk_range.clone() else {
                    drop(guard);
                    return Some("recovering");
                };
                let chunk = historian_chunk::build_historian_chunk(
                    parsed.messages.as_slice(),
                    &live,
                    range.from_ordinal,
                    derive_historian_chunk_tokens(config.historian_context_limit_tokens),
                    range.to_ordinal.saturating_add(1),
                );
                let prior_compartments = match store.load_compartments(&session_id) {
                    Ok(cs) => cs
                        .iter()
                        .map(historian_chunk::stored_range)
                        .collect::<Vec<_>>(),
                    Err(_) => Vec::new(),
                };
                let raw_chunk_messages = serde_json::to_string(
                    &parsed
                        .messages
                        .iter()
                        .filter(|message| {
                            !message.ck.meta.synthetic
                                && message.ordinal >= chunk.chunk.start_index
                                && message.ordinal <= chunk.chunk.end_index
                        })
                        .collect::<Vec<_>>(),
                )
                .unwrap_or_else(|_| "[]".to_string());
                let boundary_dates = historian_chunk::native_boundary_dates(&parsed.messages);
                let fingerprint_items: Vec<_> =
                    chunk.snapshot.iter().map(|item| item.as_item()).collect();
                let observed = historian::compute_chunk_fingerprint(&fingerprint_items);
                // The same resolution and clamp a fresh attempt applies to the host's
                // per-request timeout.
                let reattach_await_timeout =
                    historian::historian_await_timeout(parsed.historian_timeout_ms);
                tokio::spawn(async move {
                    let _guard = guard;
                    let result = async {
                        let action = historian::handle_restart_load(
                            &store,
                            &session_id,
                            now,
                            now + HISTORIAN_FAILURE_BACKOFF_MS,
                        )?;
                        match action {
                            historian::RestartAction::Done => {
                                return Ok(historian::HistorianReattachOutcome::Done);
                            }
                            historian::RestartAction::AbandonedAndRefireEligible { firing_seq } => {
                                return Ok(historian::HistorianReattachOutcome::RefireEligible {
                                    firing_seq,
                                });
                            }
                            historian::RestartAction::ReattachProducer { .. } => {}
                        }
                        let mut producer = factory.connect(&project_root).await?;
                        reattach_historian_producer(
                            &mut *producer,
                            historian::HistorianReattachRequest {
                                store: &store,
                                session_id: &session_id,
                                project_path: &project_path,
                                harness: &harness,
                                observed_chunk_fingerprint: &observed,
                                validation_chunk: &chunk.chunk,
                                chunk_transcript: &chunk.text,
                                raw_chunk_messages: &raw_chunk_messages,
                                boundary_dates: &boundary_dates,
                                prior_compartments: &prior_compartments,
                                validate_options: historian_validate::ValidateOptions {
                                    sequence_offset: prior_compartments.len() as u64 + 1,
                                    in_emergency: false,
                                    memory_enabled: config.memory_enabled,
                                    auto_promote: config.auto_promote,
                                    user_memory_collection_enabled: config
                                        .user_memory_collection_enabled,
                                    force_keep_last_compartment: false,
                                },
                                publication_floor_ordinal: range.to_ordinal,
                                await_timeout: reattach_await_timeout,
                                now_ms: now,
                                failure_backoff_at_ms: now + HISTORIAN_FAILURE_BACKOFF_MS,
                                completion_now_ms: now_ms,
                                publication_fence: Some(publication_fence.as_ref()),
                            },
                        )
                        .await
                    }
                    .await;
                    if let Err(e) = result {
                        tracing::error!(
                            "mc-module: historian reattach failed for {session_id}: {e}"
                        );
                    }
                });
                Some("reattaching")
            }
            // Reached only when the queue row is gone: a run parked for a claimant
            // that still has its row was handled above. Without a row nothing can
            // ever claim or report the run, so keeping it would hold the session's
            // single-flight slot forever. Releasing it costs one re-assembled chunk
            // on the next trigger and never loses durable output.
            HistorianPhase::Firing
            | HistorianPhase::Reclaiming
            | HistorianPhase::Validating
            | HistorianPhase::Publishing => {
                tokio::spawn(async move {
                    let _guard = guard;
                    if let Err(e) = historian::handle_restart_load(
                        &store,
                        &session_id,
                        now,
                        now + HISTORIAN_FAILURE_BACKOFF_MS,
                    ) {
                        tracing::error!(
                            "mc-module: historian restart recovery failed for {session_id}: {e}"
                        );
                    }
                });
                Some("recovering")
            }
            HistorianPhase::Idle => Some("recovered"),
        }
    }

    fn prepare_historian_fire(
        &self,
        store: Arc<McStore>,
        parsed: &TransformRequest,
        binding: &SessionBinding,
        project_path: &str,
        projection: &crate::ck_wire::FlatProjection,
        prepare: HistorianPrepareContext<'_>,
    ) -> PreparedHistorianAction {
        let HistorianPrepareContext {
            now,
            snapshot_generation,
            tag_snapshot,
            reclaim_ride_available,
            timings,
        } = prepare;
        let trigger_timer = HistorianTriggerTimer {
            started_at: Instant::now(),
            timings,
        };
        let loaded = match store.load(&parsed.session_id) {
            Ok(loaded) => loaded,
            Err(e) => {
                return PreparedHistorianAction::Complete(historian_no_fire_diagnostics(
                    NoFireDiagnosticsInput {
                        no_fire: format!("state_load_failed:{e}"),
                        detail_kind: "state_load_failed",
                        cause: HistorianNoFireCause::StateLoadFailed,
                        extra: None,
                        reason: None,
                        state: "unknown".to_string(),
                        progress: None,
                        last_failure: None,
                    },
                ));
            }
        };
        let state = loaded.meta.historian.state.as_str().to_string();
        let last_failure = loaded.meta.historian.last_failure.clone();
        let (context_limit, input_tokens, usage_percentage) =
            usage_numbers(parsed.usage.as_ref(), parsed.geometry.as_ref());
        let mut decision_context =
            HistorianDecisionContext::from_request(parsed, &loaded, now, usage_percentage);
        if loaded.meta.pending_rewrite.is_some() {
            let diagnostics = historian_no_fire_diagnostics(NoFireDiagnosticsInput {
                no_fire: "pending_rewrite".into(),
                detail_kind: "pending_rewrite",
                cause: HistorianNoFireCause::PendingRewrite,
                extra: None,
                reason: None,
                state,
                progress: None,
                last_failure,
            });
            self.record_no_fire(
                &store,
                &parsed.session_id,
                &loaded,
                &diagnostics,
                &decision_context,
            );
            return PreparedHistorianAction::Complete(diagnostics);
        }
        if let Some(completion) = self.live_historian_completion_wait(&parsed.session_id) {
            let diagnostics = historian_no_fire_diagnostics(NoFireDiagnosticsInput {
                no_fire: "busy".into(),
                detail_kind: "busy",
                cause: HistorianNoFireCause::LiveHistorianClaimBusy,
                extra: None,
                reason: None,
                state,
                progress: None,
                last_failure,
            });
            self.record_no_fire(
                &store,
                &parsed.session_id,
                &loaded,
                &diagnostics,
                &decision_context,
            );
            return PreparedHistorianAction::Busy {
                diagnostics,
                completion,
            };
        }
        let cfg = self.effective_config(&binding.project_root);
        if loaded.meta.historian.state != HistorianPhase::Idle {
            let no_fire = self
                .maybe_spawn_reattach(
                    Arc::clone(&store),
                    parsed,
                    snapshot_generation,
                    binding,
                    projection,
                    now,
                )
                .unwrap_or("busy");
            let diagnostics = historian_no_fire_diagnostics(NoFireDiagnosticsInput {
                no_fire: no_fire.to_string(),
                detail_kind: "restart_recovery",
                cause: HistorianNoFireCause::RestartRecoveryInProgress,
                extra: None,
                reason: None,
                state,
                progress: None,
                last_failure,
            });
            self.record_no_fire(
                &store,
                &parsed.session_id,
                &loaded,
                &diagnostics,
                &decision_context,
            );
            return PreparedHistorianAction::Complete(diagnostics);
        }
        let boundary_build_started_at = Instant::now();
        if let Some(tags) = tag_snapshot {
            self.boundary_tokens
                .lock()
                .expect("boundary token cache mutex")
                .prime_from_persisted_tags(&parsed.session_id, tags.as_slice());
        } else if let Ok(tags) = store.load_tags_for_session(&parsed.session_id) {
            // Malformed-lineage and compaction-off paths return before normal tag hydration.
            // Preserve their fail-open tokenization behavior rather than treating absence as empty.
            self.boundary_tokens
                .lock()
                .expect("boundary token cache mutex")
                .prime_from_persisted_tags(&parsed.session_id, &tags);
        }
        let CachedBoundaryMessages {
            messages: boundary_messages,
            token_cache_hits,
            tokenized_blocks,
            mut token_cache_snapshot,
        } = boundary_messages(parsed, projection, &self.boundary_tokens);
        trigger_timer.timings.boundary_build_ms +=
            boundary_build_started_at.elapsed().as_secs_f64() * 1_000.0;
        trigger_timer.timings.token_cache_hits = trigger_timer
            .timings
            .token_cache_hits
            .saturating_add(token_cache_hits);
        trigger_timer.timings.tokenized_blocks = trigger_timer
            .timings
            .tokenized_blocks
            .saturating_add(tokenized_blocks);
        let compartment_end_result = store.max_compartment_end_ordinal(&parsed.session_id);
        let last_compartment_end_ordinal = match compartment_end_result {
            Ok(ordinal) if ordinal > 0 => Some(ordinal as u64),
            Ok(_) | Err(_) if loaded.meta.ordinal_continuation_base.is_some() => {
                let detail = "continued_ordinal_offset_missing";
                tracing::info!(
                    "mc-module: aborting historian trigger for {}: {detail}",
                    parsed.session_id
                );
                let diagnostics = historian_no_fire_diagnostics(NoFireDiagnosticsInput {
                    no_fire: detail.into(),
                    detail_kind: detail,
                    cause: HistorianNoFireCause::ContinuedOrdinalOffsetMissing,
                    extra: None,
                    reason: None,
                    state,
                    progress: None,
                    last_failure,
                });
                self.record_no_fire(
                    &store,
                    &parsed.session_id,
                    &loaded,
                    &diagnostics,
                    &decision_context,
                );
                return PreparedHistorianAction::Complete(diagnostics);
            }
            Ok(_) | Err(_) => None,
        };
        let serializer_profile = SerializerProfile::parse(&parsed.serializer_profile)
            .expect("serializer_profile validated upstream");
        let fold_is_only_reclaim = !tail_reclaim(serializer_profile);
        let pending_drops = store
            .load_pending_agent_drops(&parsed.session_id)
            .unwrap_or_default();
        let projected_post_drop_percentage = projected_post_drop_percentage(
            &boundary_messages,
            &pending_drops,
            &loaded.core.frozen_units,
            input_tokens,
            context_limit,
        );
        let trigger_eval_started_at = Instant::now();
        let trigger = {
            let mut formatted_token_estimator =
                |bytes: &str| token_cache_snapshot.formatted_token_count(bytes);
            boundary::check_compartment_trigger_with_token_estimator(
                &boundary_messages,
                &TriggerContext {
                    boundary: BoundaryContext {
                        calibration: Some(
                            loaded
                                .meta
                                .decision_calibration
                                .as_ref()
                                .and_then(decision_calibration::DecisionCalibration::from_frozen)
                                .unwrap_or_else(decision_calibration::DecisionCalibration::neutral),
                        ),
                        context_limit,
                        // Historian preparation reloads module config independently, but a host-
                        // resolved request threshold is still authoritative for this pass.
                        execute_threshold_percentage: parsed.execute_threshold_or(
                            cfg.resolve_execute_threshold(parsed.model_key.as_deref())
                                .percentage,
                        ),
                        usage_percentage,
                        usage_input_tokens: input_tokens,
                        last_compartment_end_ordinal,
                        prior_boundary_ordinal: last_compartment_end_ordinal.unwrap_or(0),
                        migration_floor_active: last_compartment_end_ordinal.unwrap_or(0) > 0,
                        emergency_tail_scale: None,
                        trigger_budget: None,
                        fold_is_only_reclaim,
                    },
                    projected_post_drop_percentage,
                    reclaim_ride_available,
                    compartment_in_progress: loaded.meta.historian.state != HistorianPhase::Idle,
                    commit_cluster_trigger_enabled: DEFAULT_COMMIT_CLUSTER_TRIGGER_ENABLED,
                    min_commit_clusters: DEFAULT_MIN_COMMIT_CLUSTERS,
                },
                &mut formatted_token_estimator,
            )
        };
        trigger_timer.timings.trigger_eval_ms +=
            trigger_eval_started_at.elapsed().as_secs_f64() * 1_000.0;
        let cache_store_started_at = Instant::now();
        self.boundary_tokens
            .lock()
            .expect("boundary token cache mutex")
            .replace(&parsed.session_id, token_cache_snapshot);
        trigger_timer.timings.cache_store_ms +=
            cache_store_started_at.elapsed().as_secs_f64() * 1_000.0;
        decision_context.chunk_range = trigger.progress.as_ref().and_then(|progress| {
            (progress.protected_start_ordinal > progress.eligible_start_ordinal).then(|| {
                HistorianChunkRange {
                    from_ordinal: progress.eligible_start_ordinal,
                    to_ordinal: progress.protected_start_ordinal - 1,
                }
            })
        });
        let progress = trigger
            .progress
            .as_ref()
            .map(|p| transform::HistorianTriggerProgress {
                eligible_chunk_tokens: p.eligible_chunk_tokens,
                tail_size_bar: p.tail_size_bar,
                protected_tail_n_tokens: p.n_tokens,
                protected_start_ordinal: p.protected_start_ordinal,
            });
        if !trigger.fire {
            let cause = trigger
                .no_fire_cause
                .expect("a false historian trigger carries its concrete cause");
            // Quantized measurements keep the durable change gate effective while the raw and
            // canonical causes make each refusal branch independently diagnosable.
            let extra = trigger.progress.as_ref().map(|p| {
                format!(
                    "eligible~{}k,bar~{}k,protected_n~{}k,ctx_limit={}",
                    (p.eligible_chunk_tokens / 1000.0).round(),
                    (p.tail_size_bar / 1000.0).round(),
                    (p.n_tokens / 1000.0).round(),
                    context_limit,
                )
            });
            let diagnostics = historian_no_fire_diagnostics(NoFireDiagnosticsInput {
                no_fire: "trigger_false".into(),
                detail_kind: "trigger_false",
                cause,
                extra: extra.as_deref(),
                reason: None,
                state,
                progress,
                last_failure,
            });
            self.record_no_fire(
                &store,
                &parsed.session_id,
                &loaded,
                &diagnostics,
                &decision_context,
            );
            return PreparedHistorianAction::Complete(diagnostics);
        }
        let trigger_rule = trigger
            .reason
            .expect("a true historian trigger carries its firing rule");
        let trigger_reason = Some(trigger_rule.as_str().to_string());
        // The host is the only resolver of the historian's model chain and sends it with
        // every transform. A request without one is refused by name rather than filled
        // in from this module's own reading of the config file.
        let Some(model_chain) = parsed.historian_model_chain.as_deref() else {
            tracing::warn!(
                "mc-module: historian for {} not fired: the transform request carried no historian_model_chain",
                parsed.session_id
            );
            let diagnostics = historian_no_fire_diagnostics(NoFireDiagnosticsInput {
                no_fire: "model_chain_missing".into(),
                detail_kind: "model_chain_missing",
                cause: HistorianNoFireCause::ModelChainMissing,
                extra: None,
                reason: trigger_reason,
                state,
                progress,
                last_failure,
            });
            self.record_no_fire(
                &store,
                &parsed.session_id,
                &loaded,
                &diagnostics,
                &decision_context,
            );
            return PreparedHistorianAction::Complete(diagnostics);
        };
        let model_chain_generation = self.historian_runner_refusals.activate_chain(model_chain);
        if model_chain.is_empty() {
            let diagnostics = historian_no_fire_diagnostics(NoFireDiagnosticsInput {
                no_fire: "no_models".into(),
                detail_kind: "no_models",
                cause: HistorianNoFireCause::NoModels,
                extra: None,
                reason: trigger_reason,
                state,
                progress,
                last_failure,
            });
            self.record_no_fire(
                &store,
                &parsed.session_id,
                &loaded,
                &diagnostics,
                &decision_context,
            );
            return PreparedHistorianAction::Complete(diagnostics);
        }
        if self
            .historian_runner_refusals
            .all_models_durably_refused(model_chain_generation, model_chain)
        {
            let failures = self
                .historian_runner_refusals
                .cached_durable_refusals(model_chain_generation, model_chain);
            let detail = historian::runner_refusal_detail(&failures, true);
            let stage = failures
                .last()
                .map(|(_, refusal)| refusal.stage)
                .expect("a fully refused non-empty chain has a refusal");
            let diagnostics = historian_no_fire_diagnostics(NoFireDiagnosticsInput {
                no_fire: "runner_refusal_chain_exhausted".into(),
                detail_kind: "runner_refusal",
                cause: HistorianNoFireCause::from_runner_refusal_stage(stage),
                extra: Some(&detail),
                reason: trigger_reason,
                state,
                progress,
                last_failure,
            });
            self.record_no_fire(
                &store,
                &parsed.session_id,
                &loaded,
                &diagnostics,
                &decision_context,
            );
            return PreparedHistorianAction::Complete(diagnostics);
        }
        let Some(boundary) = trigger.boundary.clone() else {
            let diagnostics = historian_no_fire_diagnostics(NoFireDiagnosticsInput {
                no_fire: "missing_boundary".into(),
                detail_kind: "missing_boundary",
                cause: HistorianNoFireCause::MissingBoundary,
                extra: None,
                reason: None,
                state,
                progress,
                last_failure,
            });
            self.record_no_fire(
                &store,
                &parsed.session_id,
                &loaded,
                &diagnostics,
                &decision_context,
            );
            return PreparedHistorianAction::Complete(diagnostics);
        };
        if loaded
            .meta
            .historian
            .failure_backoff_at_ms
            .is_some_and(|backoff_at_ms| now < backoff_at_ms)
        {
            let failure_detail = last_failure.clone();
            let diagnostics = historian_no_fire_diagnostics(NoFireDiagnosticsInput {
                no_fire: if last_failure
                    .as_deref()
                    .is_some_and(|detail| detail.contains("chain_exhausted"))
                {
                    "chain_exhausted"
                } else {
                    "backoff"
                }
                .into(),
                detail_kind: "backoff",
                cause: if let Some(stage) = last_failure
                    .as_deref()
                    .and_then(historian::runner_refusal_stage_from_detail)
                {
                    HistorianNoFireCause::from_runner_refusal_stage(stage)
                } else if last_failure
                    .as_deref()
                    .is_some_and(|detail| detail.contains("chain_exhausted"))
                {
                    HistorianNoFireCause::ChainExhausted
                } else if last_failure
                    .as_deref()
                    .is_some_and(|detail| detail.starts_with("validate rejected:"))
                {
                    HistorianNoFireCause::ValidationRejected
                } else {
                    HistorianNoFireCause::FailureBackoff
                },
                extra: failure_detail.as_deref(),
                reason: failure_detail.clone().or(trigger_reason),
                state,
                progress,
                last_failure,
            });
            self.record_no_fire(
                &store,
                &parsed.session_id,
                &loaded,
                &diagnostics,
                &decision_context,
            );
            return PreparedHistorianAction::Complete(diagnostics);
        }
        let live: Vec<_> = projection
            .blocks
            .iter()
            .filter(|block| !block.synthetic)
            .cloned()
            .collect();
        let project_slug = project_slug(&binding.project_root);
        if fold_is_only_reclaim {
            // CC sessions are born on this profile; tail reducers never run, so no frozen
            // `red:*` units should exist when the fold is the sole reclaim path.
            debug_assert!(
                !loaded
                    .core
                    .frozen_units
                    .iter()
                    .any(|u| u.key.starts_with("red:")),
                "fold-only profile must not carry frozen tail reductions"
            );
        }
        let assemble = assemble_historian_firing(
            &store,
            &parsed.messages,
            &live,
            &projection.identity_by_mid,
            HistorianAssemblerConfig {
                session_id: parsed.session_id.clone(),
                project_path: project_path.to_string(),
                project_slug: project_slug.clone(),
                model_chain: model_chain.to_vec(),
                token_budget: derive_historian_chunk_tokens(cfg.historian_context_limit_tokens),
                historian_context_limit_tokens: cfg
                    .historian_context_limit_known
                    .then_some(cfg.historian_context_limit_tokens),
                max_output_tokens: historian_producer::HISTORIAN_MAX_OUTPUT_TOKENS,
                boundary,
                memory_enabled: cfg.memory_enabled,
                auto_promote: cfg.auto_promote,
                user_memory_collection_enabled: cfg.user_memory_collection_enabled,
                extraction_free: false,
                in_emergency: parsed.emergency_recovery_armed,
                force_keep_last_compartment: false,
                fold_is_only_reclaim,
                failure_backoff_at_ms: now + HISTORIAN_FAILURE_BACKOFF_MS,
                min_chunk_tokens: DEFAULT_HISTORIAN_MIN_CHUNK_TOKENS,
            },
            now,
        );
        let mut firing = match assemble {
            Ok(AssembleHistorianFiringOutcome::Fire(firing)) => *firing,
            Ok(AssembleHistorianFiringOutcome::NoFire(reason)) => {
                let raw_no_fire = format!("assemble:{reason:?}");
                let raw_detail = format!("detail={reason:?}");
                let diagnostics = historian_no_fire_diagnostics(NoFireDiagnosticsInput {
                    no_fire: raw_no_fire,
                    detail_kind: "assemble",
                    cause: reason.cause(),
                    extra: Some(&raw_detail),
                    reason: trigger_reason,
                    state,
                    progress,
                    last_failure,
                });
                let mut no_fire_context = decision_context.clone();
                if let historian_chunk::HistorianNoFireReason::BelowBudget {
                    token_estimate,
                    minimum,
                } = reason
                {
                    no_fire_context.eligible_tokens = Some(token_estimate as u64);
                    no_fire_context.bar_tokens = Some(minimum as u64);
                }
                self.record_no_fire(
                    &store,
                    &parsed.session_id,
                    &loaded,
                    &diagnostics,
                    &no_fire_context,
                );
                return PreparedHistorianAction::Complete(diagnostics);
            }
            Err(e) => {
                let raw_no_fire = format!("assemble_failed:{e}");
                let raw_detail = format!("error={e}");
                let diagnostics = historian_no_fire_diagnostics(NoFireDiagnosticsInput {
                    no_fire: raw_no_fire,
                    detail_kind: "assemble_failed",
                    cause: HistorianNoFireCause::AssemblyFailed,
                    extra: Some(&raw_detail),
                    reason: trigger_reason,
                    state,
                    progress,
                    last_failure,
                });
                self.record_no_fire(
                    &store,
                    &parsed.session_id,
                    &loaded,
                    &diagnostics,
                    &decision_context,
                );
                return PreparedHistorianAction::Complete(diagnostics);
            }
        };
        let diagnostics = HistorianDiagnostics {
            fired: true,
            reason: trigger_reason,
            no_fire: None,
            no_fire_detail: None,
            canonical_cause: None,
            state: state.clone(),
            progress: progress.clone(),
            last_failure: last_failure.clone(),
        };
        let live_guard = match self.try_claim_live_historian_session(&parsed.session_id) {
            LiveHistorianSessionClaim::Acquired(live_guard) => live_guard,
            LiveHistorianSessionClaim::Busy(completion) => {
                let busy_diagnostics = historian_no_fire_diagnostics(NoFireDiagnosticsInput {
                    no_fire: "busy".into(),
                    detail_kind: "busy",
                    cause: HistorianNoFireCause::LiveHistorianClaimBusy,
                    extra: None,
                    reason: diagnostics.reason,
                    state,
                    progress,
                    last_failure,
                });
                self.record_no_fire(
                    &store,
                    &parsed.session_id,
                    &loaded,
                    &busy_diagnostics,
                    &decision_context,
                );
                return PreparedHistorianAction::Busy {
                    diagnostics: busy_diagnostics,
                    completion,
                };
            }
        };
        decision_context.chunk_range = Some(HistorianChunkRange {
            from_ordinal: firing.from_ordinal,
            to_ordinal: firing.to_ordinal,
        });
        let mut fire_decision = decision_context.recent_decision(
            HistorianDecision::Fired,
            format!("trigger_true:{}", historian_trigger_rule(trigger_rule)),
            diagnostics.progress.as_ref(),
        );
        fire_decision.producer_model = model_chain.first().cloned();
        self.record_fire_decision(&store, &parsed.session_id, &loaded, &fire_decision);
        firing.recent_decision = Some(fire_decision);
        PreparedHistorianAction::FireReady(Box::new(PreparedHistorianFiring {
            diagnostics,
            task: HistorianFiringTask {
                store,
                session_id: parsed.session_id.clone(),
                harness: binding.harness.clone(),
                language: cfg.language.clone(),
                historian_temperature: cfg.historian_temperature,
                historian_await_timeout: historian::historian_await_timeout(
                    parsed.historian_timeout_ms,
                ),
                project_path: project_path.to_string(),
                project_root: binding.project_root.clone(),
                project_slug,
                firing,
                runner: cfg.historian_runner,
                host_runs: Arc::clone(&self.host_runs),
                model_chain_generation,
                runner_refusal_cache: Arc::clone(&self.historian_runner_refusals),
                live_guard,
                connect_failure_commit_hook: Arc::clone(&self.connect_failure_commit_hook),
                // Organic pressure firings assemble and publish in one continuous drive
                // while the live-session guard is held. They do not depend on a cached raw
                // snapshot, so a transform-snapshot generation fence would reject valid work.
                publication_fence: None,
            },
        }))
    }

    fn prepare_wrapup_fire(
        &self,
        store: Arc<McStore>,
        parsed: &TransformRequest,
        binding: &SessionBinding,
        projection: &crate::ck_wire::FlatProjection,
        boundary: &boundary::BoundaryResolution,
        context: WrapupPrepareContext,
    ) -> PreparedWrapupAction {
        let WrapupPrepareContext {
            now,
            project_path,
            allow_unknown_module_retry,
        } = context;
        let loaded = match store.load(&parsed.session_id) {
            Ok(loaded) => loaded,
            Err(error) => {
                return PreparedWrapupAction::Failed(format!("state load failed: {error}"));
            }
        };
        if loaded.meta.pending_rewrite.is_some() {
            return PreparedWrapupAction::Failed("a boundary rewrite is pending".to_string());
        }
        if let Some(completion) = self.live_historian_completion_wait(&parsed.session_id) {
            return PreparedWrapupAction::Busy(completion);
        }
        if loaded.meta.historian.state != HistorianPhase::Idle {
            return PreparedWrapupAction::Failed(format!(
                "historian recovery is required from {}",
                loaded.meta.historian.state.as_str()
            ));
        }
        if !allow_unknown_module_retry {
            if let Some(until) = loaded.meta.historian.failure_backoff_at_ms {
                if until > now {
                    return PreparedWrapupAction::Failed(format!(
                        "historian failure backoff active for {} ms",
                        until.saturating_sub(now)
                    ));
                }
            }
        }

        let cfg = self.effective_config(&binding.project_root);
        // Wrapup runs on the host's chain from the session's last transform, the same
        // chain the autonomous historian uses; the module has no chain of its own.
        let Some(model_chain) = parsed.historian_model_chain.clone() else {
            tracing::warn!(
                "mc-module: wrapup for {} refused: the session's transform carried no historian_model_chain",
                parsed.session_id
            );
            return PreparedWrapupAction::Failed(WRAPUP_MODEL_CHAIN_MISSING.to_string());
        };
        let model_chain_generation = self.historian_runner_refusals.activate_chain(&model_chain);
        if model_chain.is_empty() {
            return PreparedWrapupAction::Failed("no historian models are configured".to_string());
        }
        if self
            .historian_runner_refusals
            .all_models_durably_refused(model_chain_generation, &model_chain)
        {
            let failures = self
                .historian_runner_refusals
                .cached_durable_refusals(model_chain_generation, &model_chain);
            return PreparedWrapupAction::Failed(historian::runner_refusal_detail(&failures, true));
        }
        let live = projection
            .blocks
            .iter()
            .filter(|block| !block.synthetic)
            .cloned()
            .collect::<Vec<_>>();
        let project_slug = project_slug(&binding.project_root);
        let language = cfg.language.clone();
        let assemble = assemble_historian_firing(
            &store,
            &parsed.messages,
            &live,
            &projection.identity_by_mid,
            HistorianAssemblerConfig {
                session_id: parsed.session_id.clone(),
                project_path: project_path.clone(),
                project_slug: project_slug.clone(),
                model_chain,
                token_budget: derive_historian_chunk_tokens(cfg.historian_context_limit_tokens),
                historian_context_limit_tokens: cfg
                    .historian_context_limit_known
                    .then_some(cfg.historian_context_limit_tokens),
                max_output_tokens: historian_producer::HISTORIAN_MAX_OUTPUT_TOKENS,
                boundary: boundary.clone(),
                memory_enabled: cfg.memory_enabled,
                auto_promote: cfg.auto_promote,
                user_memory_collection_enabled: cfg.user_memory_collection_enabled,
                extraction_free: false,
                in_emergency: false,
                force_keep_last_compartment: false,
                // Explicit wrapup is the only reclaim mechanism on this surface, so a
                // small final chunk must not be rejected by the substance floor.
                fold_is_only_reclaim: true,
                failure_backoff_at_ms: now + HISTORIAN_FAILURE_BACKOFF_MS,
                min_chunk_tokens: DEFAULT_HISTORIAN_MIN_CHUNK_TOKENS,
            },
            now,
        );
        let firing = match assemble {
            Ok(AssembleHistorianFiringOutcome::Fire(firing)) => {
                let mut firing = *firing;
                // Only the final wrapup chunk has no lookahead; intermediate chunks still
                // need discard-last healing so the next round can re-read their tail.
                firing.validate_options.force_keep_last_compartment = !firing.chunk.has_more;
                firing
            }
            Ok(AssembleHistorianFiringOutcome::NoFire(
                historian_chunk::HistorianNoFireReason::FilteredNoiseSkipped { .. },
            )) => {
                return PreparedWrapupAction::FilteredNoiseSkipped;
            }
            Ok(AssembleHistorianFiringOutcome::NoFire(reason)) => {
                return PreparedWrapupAction::Nothing(format!("{reason:?}"));
            }
            Err(error) => return PreparedWrapupAction::Failed(format!("assembly failed: {error}")),
        };
        let live_guard = match self.try_claim_live_historian_session(&parsed.session_id) {
            LiveHistorianSessionClaim::Acquired(guard) => guard,
            LiveHistorianSessionClaim::Busy(completion) => {
                return PreparedWrapupAction::Busy(completion);
            }
        };
        PreparedWrapupAction::FireReady(Box::new(HistorianFiringTask {
            store,
            session_id: parsed.session_id.clone(),
            harness: binding.harness.clone(),
            language,
            historian_temperature: binding.config.historian_temperature,
            historian_await_timeout: historian::historian_await_timeout(None),
            project_path,
            project_root: binding.project_root.clone(),
            project_slug,
            firing,
            runner: binding.config.historian_runner,
            host_runs: Arc::clone(&self.host_runs),
            model_chain_generation,
            runner_refusal_cache: Arc::clone(&self.historian_runner_refusals),
            live_guard,
            connect_failure_commit_hook: Arc::clone(&self.connect_failure_commit_hook),
            publication_fence: None,
        }))
    }

    fn refresh_historian_diagnostics(
        &self,
        store: &McStore,
        session_id: &str,
        mut diagnostics: HistorianDiagnostics,
    ) -> HistorianDiagnostics {
        if let Ok(loaded) = store.load(session_id) {
            diagnostics.state = loaded.meta.historian.state.as_str().to_string();
            diagnostics.last_failure = loaded.meta.historian.last_failure.clone();
        }
        diagnostics
    }

    /// Persist a trigger-true decision before handing the firing to an asynchronous worker.
    /// The state transition fills in the producer model without appending the same decision again.
    fn record_fire_decision(
        &self,
        store: &McStore,
        session_id: &str,
        loaded: &LoadedState,
        decision: &HistorianRecentDecision,
    ) {
        let mut meta = loaded.meta.clone();
        meta.historian.record_recent_decision(decision.clone());
        if store
            .commit(session_id, loaded.row_version, &loaded.core, &meta)
            .is_ok()
        {
            DISPATCH_HEALTH.historian_recent_decisions_count.store(
                meta.historian.recent_decisions.len() as u64,
                Ordering::Relaxed,
            );
        }
    }

    /// Persist skip evidence without changing the transform result. Equivalent quantized
    /// no-fire observations leave the row untouched; a CAS loser simply yields to the newer pass.
    fn record_no_fire(
        &self,
        store: &McStore,
        session_id: &str,
        loaded: &mc_store::LoadedState,
        diagnostics: &HistorianDiagnostics,
        context: &HistorianDecisionContext,
    ) {
        let reason = diagnostics
            .no_fire_detail
            .as_deref()
            .expect("no-fire diagnostics carry durable detail");
        let cause = diagnostics
            .canonical_cause
            .clone()
            .expect("no-fire diagnostics carry a canonical cause");
        let mut meta = loaded.meta.clone();
        let decision_changed = meta
            .historian
            .record_recent_decision(context.recent_decision(
                HistorianDecision::NoFire,
                cause,
                diagnostics.progress.as_ref(),
            ));
        if !decision_changed && meta.historian.last_no_fire.as_deref() == Some(reason) {
            return;
        }
        meta.historian.last_no_fire = Some(reason.to_string());
        if store
            .commit(session_id, loaded.row_version, &loaded.core, &meta)
            .is_ok()
        {
            DISPATCH_HEALTH.historian_recent_decisions_count.store(
                meta.historian.recent_decisions.len() as u64,
                Ordering::Relaxed,
            );
        }
    }

    async fn execute_historian_firing_task(
        factory: Arc<dyn HistorianProducerFactory>,
        task: HistorianFiringTask,
    ) -> Result<historian::HistorianDriveOutcome, historian::HistorianDriveError> {
        let HistorianFiringTask {
            store,
            session_id,
            harness,
            language,
            historian_temperature,
            historian_await_timeout,
            project_path,
            project_slug,
            project_root,
            firing,
            runner,
            host_runs,
            model_chain_generation,
            runner_refusal_cache,
            live_guard,
            connect_failure_commit_hook,
            publication_fence,
        } = task;
        let _guard = live_guard;
        tracing::info!(
            "mc-module: historian firing for {session_id}: await_timeout_ms={} attempt_budget_ms={} firing_budget_ms={}",
            historian_await_timeout.as_millis(),
            historian::completion_wait_budget(historian_await_timeout).as_millis(),
            historian::firing_completion_wait_budget(
                historian_await_timeout,
                firing.model_chain.len()
            )
            .as_millis()
        );
        let failure_started_at_ms = firing.now_ms;
        let configured_failure_backoff_at_ms = firing.failure_backoff_at_ms;
        if runner == HistorianRunnerKind::Host {
            // The host lane never opens a Broca route, so there is no connect step
            // to fail: the run is queued and this task waits for a claimant.
            let mut request = firing.as_fire_request(
                &store,
                &session_id,
                &project_path,
                &harness,
                &project_slug,
                language.as_deref(),
            );
            request.temperature = historian_temperature;
            request.publication_fence = publication_fence.as_deref();
            // The claimant walks the same model chain a Broca firing would, each
            // attempt under the host's own per-attempt timeout, so this waits for the
            // whole chain exactly as a Broca firing's joiners do.
            let firing_budget = historian::firing_completion_wait_budget(
                historian_await_timeout,
                firing.model_chain.len(),
            );
            let result =
                historian::run_historian_firing_on_host(&host_runs, request, firing_budget).await;
            if let Ok(loaded) = store.load(&session_id) {
                DISPATCH_HEALTH.record_historian_outcome(
                    historian_status_summary(&loaded.meta.historian),
                    loaded.meta.historian.recent_decisions.len(),
                );
            }
            return result;
        }
        let result = match factory.connect(&project_root).await {
            Ok(mut producer) => {
                let mut request = firing.as_fire_request(
                    &store,
                    &session_id,
                    &project_path,
                    &harness,
                    &project_slug,
                    language.as_deref(),
                );
                request.temperature = historian_temperature;
                request.await_timeout = historian_await_timeout;
                request.publication_fence = publication_fence.as_deref();
                run_historian_firing_with_model_cache(
                    &mut *producer,
                    request,
                    Some(runner_refusal_cache.as_ref()),
                    model_chain_generation,
                )
                .await
            }
            Err(err) => {
                let failure_backoff_at_ms = historian::completion_failure_backoff_at_ms(
                    failure_started_at_ms,
                    configured_failure_backoff_at_ms,
                    now_ms(),
                );
                let backoff_error = record_historian_connect_failure(
                    &store,
                    &session_id,
                    failure_backoff_at_ms,
                    &format!("producer connect: {err}"),
                    &connect_failure_commit_hook,
                )
                .err()
                .map(Box::new);
                Err(historian::HistorianDriveError::ProducerConnect {
                    source: Box::new(err),
                    backoff_error,
                })
            }
        };
        if let Ok(loaded) = store.load(&session_id) {
            DISPATCH_HEALTH.record_historian_outcome(
                historian_status_summary(&loaded.meta.historian),
                loaded.meta.historian.recent_decisions.len(),
            );
        }
        result
    }

    fn transform_historian_followup_budget(&self) -> Duration {
        #[cfg(test)]
        if let Some(budget) = *self
            .transform_historian_followup_budget
            .lock()
            .expect("transform historian follow-up budget mutex")
        {
            return budget;
        }
        TRANSFORM_HISTORIAN_FOLLOWUP_BUDGET
    }

    /// Drive a firing for an emergency pass within the transform's remaining follow-up budget.
    ///
    /// The firing runs as a SPAWNED task and this method awaits its JoinHandle with a
    /// timeout, for two reasons:
    /// - The drive's own wall clock is bounded only per model attempt (producer await +
    ///   recovery re-drain), so a fallback chain could hold the request open for
    ///   attempt-budget × chain-length. Transform consumers need a hard per-request
    ///   ceiling to set their call deadlines against.
    /// - On timeout the spawned firing KEEPS RUNNING (a JoinHandle timeout does not
    ///   cancel the task): the request degrades to its already-computed emergency
    ///   output and a later pass picks up the published fold. Cancelling mid-drive
    ///   would instead strand durable state for crash recovery to repair.
    async fn run_historian_firing_inline(
        &self,
        session_id: &str,
        task: HistorianFiringTask,
        wait_budget: Duration,
    ) -> Result<historian::HistorianDriveOutcome, historian::HistorianDriveError> {
        let factory = Arc::clone(&self.producer_factory);
        let handle = tokio::spawn(Self::execute_historian_firing_task(factory, task));
        let wait_started_at = Instant::now();
        tracing::info!(
            target: "perf",
            "mc-pass-stage session={session_id} stage=historian_inline_wait event=begin budget_ms={}",
            wait_budget.as_millis()
        );
        let waited = tokio::time::timeout(wait_budget, handle).await;
        tracing::info!(
            target: "perf",
            "mc-pass-stage session={session_id} stage=historian_inline_wait event=end outcome={} elapsed_ms={:.1}",
            if waited.is_ok() { "completed" } else { "timed_out" },
            wait_started_at.elapsed().as_secs_f64() * 1_000.0
        );
        match waited {
            Ok(Ok(outcome)) => outcome,
            Ok(Err(join_err)) => Err(historian::HistorianDriveError::Producer(
                HistorianProducerError::RunFailed {
                    run_id: String::new(),
                    detail: format!("inline firing task panicked: {join_err}"),
                    classification: None,
                    class_field_present: false,
                },
            )),
            Err(_elapsed) => Err(historian::HistorianDriveError::Producer(
                HistorianProducerError::TimedOut,
            )),
        }
    }

    async fn await_live_historian_completion(
        &self,
        session_id: &str,
        completion: LiveHistorianCompletionWait,
        wait_budget: Duration,
    ) -> bool {
        let wait_started_at = Instant::now();
        tracing::info!(
            target: "perf",
            "mc-pass-stage session={session_id} stage=historian_busy_wait event=begin budget_ms={}",
            wait_budget.as_millis()
        );
        let completed = tokio::time::timeout(wait_budget, completion).await.is_ok();
        tracing::info!(
            target: "perf",
            "mc-pass-stage session={session_id} stage=historian_busy_wait event=end outcome={} elapsed_ms={:.1}",
            if completed { "completed" } else { "timed_out" },
            wait_started_at.elapsed().as_secs_f64() * 1_000.0
        );
        completed
    }

    fn wrapup_operation_budget(&self) -> Duration {
        #[cfg(test)]
        if let Some(budget) = *self
            .wrapup_operation_budget
            .lock()
            .expect("wrapup operation budget mutex")
        {
            return budget;
        }
        historian::MAX_WRAPUP_REQUEST_BUDGET
            .checked_sub(WRAPUP_REQUEST_MARGIN)
            .unwrap_or(Duration::ZERO)
    }

    fn unknown_module_retry_delay(&self) -> Duration {
        #[cfg(test)]
        if let Some(delay) = *self
            .unknown_module_retry_delay
            .lock()
            .expect("unknown module retry delay mutex")
        {
            return delay;
        }
        Duration::from_secs(30)
    }

    fn remaining_wrapup_budget(deadline: Instant) -> Option<Duration> {
        deadline
            .checked_duration_since(Instant::now())
            .filter(|remaining| !remaining.is_zero())
    }

    async fn run_wrapup_firing(
        &self,
        task: HistorianFiringTask,
        deadline: Instant,
    ) -> Result<historian::HistorianDriveOutcome, WrapupFiringError> {
        let Some(remaining) = Self::remaining_wrapup_budget(deadline) else {
            return Err(WrapupFiringError::Retryable(
                RetryableWrapupReason::BudgetExhausted,
                "wrapup request budget expired before historian round".to_string(),
            ));
        };
        let wait = historian::wrapup_round_wait_budget(
            task.historian_await_timeout,
            task.firing.model_chain.len(),
            remaining,
        );
        let factory = Arc::clone(&self.producer_factory);
        let handle = tokio::spawn(Self::execute_historian_firing_task(factory, task));
        match tokio::time::timeout(wait, handle).await {
            Ok(Ok(Ok(outcome))) => Ok(outcome),
            Ok(Ok(Err(error))) => {
                if matches!(&error, historian::HistorianDriveError::NoModels) {
                    return Err(WrapupFiringError::Terminal {
                        reason: "no_models",
                        detail: error.to_string(),
                    });
                }
                if matches!(
                    &error,
                    historian::HistorianDriveError::Producer(error)
                        if error.is_unknown_module()
                ) || matches!(
                    &error,
                    historian::HistorianDriveError::ProducerConnect { source, .. }
                        if source.is_unknown_module()
                ) {
                    return Err(WrapupFiringError::UnknownModule(error.to_string()));
                }
                let reason = match &error {
                    historian::HistorianDriveError::State(
                        historian::HistorianStateError::Publish(
                            mc_store::HistorianPublishError::CasConflict { .. }
                            | mc_store::HistorianPublishError::FenceRejected { .. },
                        ),
                    )
                    | historian::HistorianDriveError::State(
                        historian::HistorianStateError::Store(McStoreError::CasConflict { .. }),
                    ) => RetryableWrapupReason::SnapshotStale,
                    historian::HistorianDriveError::ProducerConnect {
                        backoff_error: None,
                        ..
                    }
                    | historian::HistorianDriveError::Producer(_)
                    | historian::HistorianDriveError::Validation(_) => {
                        RetryableWrapupReason::BackoffActive
                    }
                    historian::HistorianDriveError::ProducerConnect {
                        backoff_error: Some(_),
                        ..
                    } => RetryableWrapupReason::SnapshotUnavailable,
                    _ => RetryableWrapupReason::SnapshotUnavailable,
                };
                Err(WrapupFiringError::Retryable(reason, error.to_string()))
            }
            Ok(Err(error)) => Err(WrapupFiringError::Retryable(
                RetryableWrapupReason::SnapshotUnavailable,
                format!("historian task failed: {error}"),
            )),
            Err(_) if Instant::now() >= deadline => Err(WrapupFiringError::Retryable(
                RetryableWrapupReason::BudgetExhausted,
                "wrapup request budget expired during historian round".to_string(),
            )),
            Err(_) => Err(WrapupFiringError::Retryable(
                RetryableWrapupReason::SnapshotUnavailable,
                "historian round timed out after 600 seconds".to_string(),
            )),
        }
    }

    /// How long a join may wait for an already-running firing it did not start. The
    /// firing may walk its whole model chain (a timed-out attempt moves on to the next
    /// model), so the join allows one per-attempt budget per model rather than one
    /// attempt in total. The joiner does not know which timeout the running firing was
    /// started with, so it takes the larger of the host-supplied and default
    /// per-attempt timeouts; the chain length is the host's, the only chain there is.
    fn active_firing_join_budget(
        host_model_chain: Option<&[String]>,
        host_timeout_ms: Option<u64>,
    ) -> Duration {
        let host_chain_len = host_model_chain.map_or(0, <[String]>::len);
        let timeout = historian::historian_await_timeout(host_timeout_ms)
            .max(historian::historian_await_timeout(None));
        historian::firing_completion_wait_budget(timeout, host_chain_len)
    }

    async fn await_wrapup_historian_completion(
        &self,
        completion: LiveHistorianCompletionWait,
        deadline: Instant,
        join_budget: Duration,
    ) -> Result<(), String> {
        let Some(remaining) = Self::remaining_wrapup_budget(deadline) else {
            return Err("wrapup request budget expired before joining historian".to_string());
        };
        let wait = join_budget.min(remaining);
        match tokio::time::timeout(wait, completion).await {
            Ok(()) => Ok(()),
            Err(_) if Instant::now() >= deadline => {
                Err("wrapup request budget expired while joining historian".to_string())
            }
            Err(_) => Err("timed out while joining the active historian run".to_string()),
        }
    }

    fn spawn_historian_firing(&self, task: HistorianFiringTask) {
        let factory = Arc::clone(&self.producer_factory);
        tokio::spawn(async move {
            let session_id = task.session_id.clone();
            let result = Self::execute_historian_firing_task(factory, task).await;
            match result {
                Ok(outcome) => {
                    tracing::info!(
                        "mc-module: historian firing finished for {session_id}: {outcome:?}"
                    )
                }
                Err(e) => {
                    tracing::error!("mc-module: historian firing failed for {session_id}: {e}")
                }
            }
        });
    }

    fn handle_state_import_value(&self, channel: u16, request: Value) -> HandlerOutcome {
        let raw_session_id = request
            .get("session_id")
            .and_then(Value::as_str)
            .map(str::to_string);
        let batch_bytes = match serde_json::to_vec(&request) {
            Ok(bytes) if bytes.len() <= MAX_FACADE_FRAME_BYTES => bytes.len(),
            Ok(_) => {
                if let Some(session_id) = raw_session_id.as_deref() {
                    self.state_imports
                        .lock()
                        .expect("state import mutex")
                        .discard(session_id);
                }
                return invalid_params_error("request body exceeds the 1 MiB limit");
            }
            Err(error) => return invalid_params_error(error.to_string()),
        };
        let parsed: StateImportWire = match serde_json::from_value(request.clone()) {
            Ok(parsed) => parsed,
            Err(error) => {
                if let Some(session_id) = raw_session_id.as_deref() {
                    self.state_imports
                        .lock()
                        .expect("state import mutex")
                        .discard(session_id);
                }
                return invalid_params_error(error.to_string());
            }
        };
        let discard = |handler: &McHandler| {
            handler
                .state_imports
                .lock()
                .expect("state import mutex")
                .discard(&parsed.session_id);
        };
        if parsed.v != 1 {
            discard(self);
            return HandlerOutcome::Error {
                code: "state_import_version".to_string(),
                message: "state_import requires v=1".to_string(),
            };
        }
        if parsed.session_id.trim().is_empty() {
            discard(self);
            return invalid_params_error("state_import requires a nonempty session_id");
        }
        if parsed.import_id.is_empty() || parsed.import_id.len() > STATE_IMPORT_MAX_ID_BYTES {
            discard(self);
            return invalid_params_error(format!(
                "import_id must contain 1..={STATE_IMPORT_MAX_ID_BYTES} bytes"
            ));
        }
        if parsed.batch_count == 0 || parsed.batch_seq >= parsed.batch_count {
            discard(self);
            return HandlerOutcome::Error {
                code: "batch_seq_mismatch".to_string(),
                message: "batch_seq must be inside a nonempty batch_count".to_string(),
            };
        }

        let _binding = match self.resolve_binding(channel, &parsed.session_id) {
            Ok(binding) => binding,
            Err(BindingError::Unbound) => {
                discard(self);
                return HandlerOutcome::Error {
                    code: "route_unbound".to_string(),
                    message: "state_import on a channel with no session binding".to_string(),
                };
            }
            Err(BindingError::SessionMismatch) => {
                discard(self);
                return HandlerOutcome::Error {
                    code: "session_mismatch".to_string(),
                    message: "request session_id does not match the channel's bound session"
                        .to_string(),
                };
            }
        };
        let store = match self.store.get() {
            Some(store) => Arc::clone(store),
            None => {
                discard(self);
                return self.store_refusal();
            }
        };
        match store.preflight_state_import(&parsed.session_id, &parsed.import_id) {
            Ok(StateImportPreflight::Duplicate { imported }) => {
                discard(self);
                return respond(json!({
                    "ok": true,
                    "imported": imported,
                    "duplicate": true,
                }));
            }
            Ok(StateImportPreflight::Ready) => {}
            Err(StateImportError::SessionNotEmpty) => {
                discard(self);
                return HandlerOutcome::Error {
                    code: "session_not_empty".to_string(),
                    message: "state_import only accepts a session with no durable state"
                        .to_string(),
                };
            }
            Err(error) => {
                discard(self);
                return HandlerOutcome::Error {
                    code: "store_load_failed".to_string(),
                    message: error.to_string(),
                };
            }
        }

        let created_at = now_ms();
        let compartments = parsed
            .compartments
            .into_iter()
            .map(|compartment| compartment.into_stored(created_at))
            .collect::<Vec<_>>();
        if let Err(error) = validate_state_import_compartments(&compartments) {
            discard(self);
            return state_import_validation_error(error);
        }
        let digest = sha256_hex(canonical_value(&request).as_bytes());
        let action = self
            .state_imports
            .lock()
            .expect("state import mutex")
            .stage(
                &parsed.session_id,
                parsed.import_id,
                parsed.batch_seq,
                parsed.batch_count,
                digest,
                batch_bytes,
                compartments,
                Instant::now(),
            );
        match action {
            Ok(StateImportStageOutcome::Staged(staged)) => {
                respond(json!({ "ok": true, "staged": staged }))
            }
            Ok(StateImportStageOutcome::Apply {
                import_id,
                compartments,
            }) => {
                let outcome = store.commit_state_import(
                    &parsed.session_id,
                    &import_id,
                    &compartments,
                    created_at,
                );
                self.state_imports
                    .lock()
                    .expect("state import mutex")
                    .complete(&parsed.session_id, &import_id);
                match outcome {
                    Ok(result) => respond(json!({
                        "ok": true,
                        "imported": result.imported,
                        "duplicate": result.duplicate,
                    })),
                    Err(StateImportError::SessionNotEmpty) => HandlerOutcome::Error {
                        code: "session_not_empty".to_string(),
                        message: "state_import only accepts a session with no durable state"
                            .to_string(),
                    },
                    Err(StateImportError::Validation(error)) => {
                        state_import_validation_error(error)
                    }
                    Err(StateImportError::Store(error)) => HandlerOutcome::Error {
                        code: "store_write_failed".to_string(),
                        message: error.to_string(),
                    },
                }
            }
            Err(StateImportStageError::Validation(error)) => state_import_validation_error(error),
            Err(StateImportStageError::Protocol { code, message }) => HandlerOutcome::Error {
                code: code.to_string(),
                message: message.to_string(),
            },
        }
    }

    fn handle_agent_drops_value(&self, channel: u16, request: Value) -> HandlerOutcome {
        let Some(session_id) = request.get("session_id").and_then(Value::as_str) else {
            return HandlerOutcome::Error {
                code: "bad_request".to_string(),
                message: "agent_drops.append requires session_id".to_string(),
            };
        };
        let command_id = match command_id_from_agent_drops_request(&request) {
            Ok(command_id) => command_id,
            Err(message) => {
                return HandlerOutcome::Error {
                    code: "bad_request".to_string(),
                    message,
                };
            }
        };
        let Some(raw_drop) = request.get("drop").and_then(Value::as_str) else {
            return HandlerOutcome::Error {
                code: "bad_request".to_string(),
                message: "'drop' must be a nonempty string".to_string(),
            };
        };
        if raw_drop.trim().is_empty() {
            return HandlerOutcome::Error {
                code: "bad_request".to_string(),
                message: "'drop' must be a nonempty string".to_string(),
            };
        }
        let numbers = match parse_tag_range_string(raw_drop) {
            Ok(numbers) => numbers,
            Err(error) => {
                return HandlerOutcome::Error {
                    code: "bad_request".to_string(),
                    message: format!("invalid drop range syntax: {error}"),
                };
            }
        };
        let _binding = match self.resolve_binding(channel, session_id) {
            Ok(binding) => binding,
            Err(BindingError::Unbound) => {
                return HandlerOutcome::Error {
                    code: "route_unbound".to_string(),
                    message: "agent_drops.append on a channel with no session binding".to_string(),
                };
            }
            Err(BindingError::SessionMismatch) => {
                return HandlerOutcome::Error {
                    code: "session_mismatch".to_string(),
                    message: "request session_id does not match the channel's bound session"
                        .to_string(),
                };
            }
        };
        let store = match self.store.get() {
            Some(store) => Arc::clone(store),
            None => return self.store_refusal(),
        };
        let tags = match store.load_tags_for_session(session_id) {
            Ok(tags) => tags,
            Err(error) => {
                return HandlerOutcome::Error {
                    code: "store_write_failed".to_string(),
                    message: error.to_string(),
                };
            }
        };
        let by_number = tags
            .iter()
            .map(|row| (row.tag_number, &row.block_id))
            .collect::<HashMap<_, _>>();
        let requested_numbers = numbers;
        let unknown_numbers = requested_numbers
            .iter()
            .copied()
            .filter(|number| !by_number.contains_key(&(*number as i64)))
            .collect::<Vec<_>>();
        let mut drop_ids = requested_numbers
            .into_iter()
            .filter_map(|number| by_number.get(&(number as i64)).map(|id| (*id).clone()))
            .collect::<Vec<_>>();
        drop_ids.sort();
        drop_ids.dedup();
        if drop_ids.is_empty() {
            return HandlerOutcome::Error {
                code: "bad_request".to_string(),
                message: format!(
                    "ctx_reduce drop request has no valid tags: {} not found",
                    format_plain_tag_numbers(&unknown_numbers)
                ),
            };
        }

        match store.append_pending_agent_drops_with_command(
            session_id,
            Some(&command_id),
            &drop_ids,
            now_ms(),
            false,
        ) {
            Ok(outcome) if outcome.duplicate => {
                respond(json!({ "ok": true, "queued": 0, "duplicate": true }))
            }
            Ok(outcome) => {
                let mut resp = json!({ "ok": true, "queued": outcome.queued });
                if let Some(disposition) = &outcome.disposition {
                    resp["disposition"] = json!(disposition);
                }
                respond(resp)
            }
            Err(error) => HandlerOutcome::Error {
                code: "store_write_failed".to_string(),
                message: error.to_string(),
            },
        }
    }

    fn management_binding(
        &self,
        channel: u16,
        request: &Value,
        operation: &str,
    ) -> Result<(String, SessionBinding), HandlerOutcome> {
        if request.get("v").and_then(Value::as_u64) != Some(1) {
            return Err(HandlerOutcome::Error {
                code: "bad_request".to_string(),
                message: format!("{operation} requires v=1"),
            });
        }
        let Some(session_id) = request.get("session_id").and_then(Value::as_str) else {
            return Err(HandlerOutcome::Error {
                code: "bad_request".to_string(),
                message: format!("{operation} requires session_id"),
            });
        };
        if session_id.trim().is_empty() {
            return Err(HandlerOutcome::Error {
                code: "bad_request".to_string(),
                message: format!("{operation} requires a nonempty session_id"),
            });
        }
        let binding = match self.resolve_binding(channel, session_id) {
            Ok(binding) => binding,
            Err(BindingError::Unbound) => {
                return Err(HandlerOutcome::Error {
                    code: "route_unbound".to_string(),
                    message: format!("{operation} on a channel with no session binding"),
                });
            }
            Err(BindingError::SessionMismatch) => {
                return Err(HandlerOutcome::Error {
                    code: "session_mismatch".to_string(),
                    message: "request session_id does not match the channel's bound session"
                        .to_string(),
                });
            }
        };
        Ok((session_id.to_string(), binding))
    }

    fn handle_todo_state_set_value(&self, channel: u16, request: &Value) -> HandlerOutcome {
        let (session_id, _binding) =
            match self.management_binding(channel, request, "todo_state.set") {
                Ok(scope) => scope,
                Err(outcome) => return outcome,
            };
        let Some(state_json) = request.get("state_json").and_then(Value::as_str) else {
            return invalid_params_error("todo_state.set requires state_json");
        };
        if state_json.len() > MAX_FACADE_FRAME_BYTES {
            return invalid_params_error("state_json exceeds the 1 MiB limit");
        }
        let Some(owner_message_id) = request.get("owner_message_id").and_then(Value::as_str) else {
            return invalid_params_error("todo_state.set requires owner_message_id");
        };
        if owner_message_id.is_empty() || owner_message_id.len() > 128 {
            return invalid_params_error("owner_message_id must contain 1..=128 bytes");
        }
        let Some(normalized) = crate::injection::normalize_todo_state_json(state_json) else {
            return invalid_params_error("state_json must be a JSON todo array");
        };
        let state_hash = sha256_hex(normalized.as_bytes());
        let store = match self.store.get() {
            Some(store) => store,
            None => return self.store_refusal(),
        };
        match store.set_todo_state(&session_id, &normalized, owner_message_id, &state_hash) {
            Ok(TodoStateSetOutcome::Updated { .. }) | Ok(TodoStateSetOutcome::Noop) => {
                respond(json!({ "ok": true }))
            }
            Err(error) => HandlerOutcome::Error {
                code: "store_write_failed".to_string(),
                message: error.to_string(),
            },
        }
    }

    fn handle_session_flush_value(&self, channel: u16, request: &Value) -> HandlerOutcome {
        let (session_id, _binding) =
            match self.management_binding(channel, request, "session.flush") {
                Ok(scope) => scope,
                Err(outcome) => return outcome,
            };
        let store = match self.store.get() {
            Some(store) => store,
            None => return self.store_refusal(),
        };
        match store.arm_soft_refresh(&session_id) {
            Ok(armed) => respond(json!({ "ok": true, "armed": armed })),
            Err(error) => HandlerOutcome::Error {
                code: "store_write_failed".to_string(),
                message: error.to_string(),
            },
        }
    }

    fn handle_session_recomp_value(&self, channel: u16, request: &Value) -> HandlerOutcome {
        let (session_id, _binding) =
            match self.management_binding(channel, request, "session.recomp") {
                Ok(scope) => scope,
                Err(outcome) => return outcome,
            };
        let Some(command_id) = request.get("command_id").and_then(Value::as_str) else {
            return invalid_params_error("session.recomp requires command_id");
        };
        if command_id.is_empty() || command_id.len() > 128 {
            return invalid_params_error("command_id must contain 1..=128 bytes");
        }
        let store = match self.store.get() {
            Some(store) => store,
            None => return self.store_refusal(),
        };
        match store.load_recomp_command(&session_id, command_id) {
            Ok(Some(row)) => {
                return respond(json!({
                    "ok": true,
                    "disposition": row.disposition,
                }));
            }
            Ok(None) => {}
            Err(error) => {
                return HandlerOutcome::Error {
                    code: "store_load_failed".to_string(),
                    message: error.to_string(),
                };
            }
        }
        let _guard = match self.try_claim_recomp_session(&session_id) {
            Ok(guard) => guard,
            Err(()) => {
                return respond(json!({
                    "ok": true,
                    "disposition": "already_in_progress",
                }));
            }
        };

        let loaded = match store.load(&session_id) {
            Ok(loaded) => loaded,
            Err(error) => {
                return HandlerOutcome::Error {
                    code: "store_load_failed".to_string(),
                    message: error.to_string(),
                };
            }
        };
        let has_compartments = match store.has_compartments(&session_id) {
            Ok(has_compartments) => has_compartments,
            Err(error) => {
                return HandlerOutcome::Error {
                    code: "store_load_failed".to_string(),
                    message: error.to_string(),
                };
            }
        };
        let never_minted = !has_compartments && loaded.core.boundary_id.trim().is_empty();
        if never_minted {
            return match store.record_recomp_command(
                &session_id,
                command_id,
                "nothing_to_do",
                now_ms(),
            ) {
                Ok(row) => respond(json!({
                    "ok": true,
                    "disposition": row.disposition,
                })),
                Err(error) => HandlerOutcome::Error {
                    code: "store_write_failed".to_string(),
                    message: error.to_string(),
                },
            };
        }

        let _reset = match store.reset_session_for_recomp(&session_id, loaded.row_version) {
            Ok(reset) => reset,
            Err(error @ McStoreError::CasConflict { .. }) => {
                // A transform may have committed between the status reads and the reset.
                // The recomp latch remains held; ask the caller to retry rather than
                // claiming a reset that did not use the observed cache version.
                return HandlerOutcome::Error {
                    code: "store_conflict".to_string(),
                    message: error.to_string(),
                };
            }
            Err(error) => {
                return HandlerOutcome::Error {
                    code: "store_write_failed".to_string(),
                    message: error.to_string(),
                };
            }
        };
        self.serialized_outputs
            .lock()
            .expect("serialized output cache mutex")
            .remove(&session_id);
        self.native_attachments
            .lock()
            .expect("native attachment cache mutex")
            .remove(&session_id);
        self.boundary_tokens
            .lock()
            .expect("boundary token cache mutex")
            .remove(&session_id);
        // A transform generation is an in-memory fence for cached raw snapshots. Marking
        // this session in-flight prevents an already assembled historian from acquiring
        // a ready snapshot after the durable revert epoch has been bumped.
        self.transform_snapshots
            .lock()
            .expect("transform snapshots mutex")
            .begin(&session_id);
        match store.record_recomp_command(&session_id, command_id, "started", now_ms()) {
            Ok(row) => respond(json!({
                "ok": true,
                "disposition": row.disposition,
            })),
            Err(error) => HandlerOutcome::Error {
                code: "store_write_failed".to_string(),
                message: error.to_string(),
            },
        }
    }

    fn runtime_store_error_value(&self, session_id: &str) -> Value {
        self.runtime_store_errors
            .lock()
            .expect("runtime store errors mutex")
            .get(session_id)
            .map(|error| {
                json!({
                    "code": error.code,
                    "message": error.message,
                    "at_ms": error.at_ms,
                })
            })
            .unwrap_or(Value::Null)
    }

    fn handle_session_delete_value(&self, channel: u16, request: &Value) -> HandlerOutcome {
        let (session_id, binding) =
            match self.management_binding(channel, request, "session.delete") {
                Ok(scope) => scope,
                Err(outcome) => return outcome,
            };
        let store = match self.store.get() {
            Some(store) => store,
            None => return self.store_refusal(),
        };
        match store.delete_session(&session_id, &binding.project_root.to_string_lossy()) {
            Ok(deleted_rows) => {
                self.runtime_store_errors
                    .lock()
                    .expect("runtime store errors mutex")
                    .remove(&session_id);
                self.reattaching_sessions
                    .lock()
                    .expect("reattaching sessions mutex")
                    .remove(&session_id);
                self.wrapup_sessions
                    .lock()
                    .expect("wrapup sessions mutex")
                    .remove(&session_id);
                self.recomp_sessions
                    .lock()
                    .expect("recomp sessions mutex")
                    .remove(&session_id);
                // The delete removed the durable rows the lineage caches mirror. While a route
                // is still bound, its in-memory root is the only lineage proof left for facade
                // calls on that route, so it stays until `unbind_route` evicts it.
                let still_bound = self
                    .bindings
                    .lock()
                    .expect("bindings mutex")
                    .values()
                    .any(|candidate| candidate.session == session_id);
                if still_bound {
                    self.guidance_dates
                        .lock()
                        .expect("guidance date mutex")
                        .remove(&session_id);
                } else {
                    self.evict_session_lineage_caches(&session_id);
                }
                respond(json!({ "ok": true, "deleted_rows": deleted_rows }))
            }
            Err(error) => HandlerOutcome::Error {
                code: "store_write_failed".to_string(),
                message: error.to_string(),
            },
        }
    }

    /// The project a claim-lane request may act on, and the version check the rest
    /// of the management surface applies.
    ///
    /// The four claim ops cannot take a `session_id` the way the neighbouring
    /// management ops do: a claimant polls precisely because it does not know which
    /// session produced a run. What it can be held to is the channel's own binding.
    /// One module store serves every project on the machine, the queue row records
    /// which project queued the run, and `historian.claim` hands back the folded
    /// conversation transcript — so without this scope a second project's host
    /// process can list and claim the first project's runs and read its transcripts.
    ///
    /// The project is resolved through the authority route exactly as the transform
    /// that queued the run resolved it, so a workspace member and its authority
    /// project agree on one key rather than two spellings of the same project.
    fn historian_lane_binding(
        &self,
        channel: u16,
        request: &Value,
        operation: &str,
    ) -> Result<SessionBinding, HandlerOutcome> {
        if request.get("v").and_then(Value::as_u64) != Some(1) {
            return Err(HandlerOutcome::Error {
                code: "bad_request".to_string(),
                message: format!("{operation} requires v=1"),
            });
        }
        self.facade_binding(channel)
            .map_err(|_| HandlerOutcome::Error {
                code: "route_unbound".to_string(),
                message: format!("{operation} on a channel with no session binding"),
            })
    }

    /// The project key a bound channel's runs are queued under: the authority route
    /// resolution the transform applied when it queued them, so a workspace member
    /// and its authority project are one key rather than two spellings.
    fn historian_lane_project(
        &self,
        binding: &SessionBinding,
        store: &McStore,
    ) -> Result<String, HandlerOutcome> {
        let route_project_root = binding.project_root.to_string_lossy().to_string();
        match store.authority_project_for_route(&route_project_root, "memories") {
            Ok(Some(project)) => Ok(project),
            Ok(None) => Ok(route_project_root),
            Err(error) => Err(HandlerOutcome::Error {
                code: "authority_project_resolution_failed".to_string(),
                message: error.to_string(),
            }),
        }
    }

    /// `historian.pending {session_id?}` — runs waiting for a claimant.
    ///
    /// Omitting `session_id` lists every run of the caller's own project, because a
    /// claimant discovers runs by polling, not by already knowing which session
    /// produced them. Runs queued by any other project are not the caller's to see.
    fn handle_historian_pending_value(&self, channel: u16, request: &Value) -> HandlerOutcome {
        let binding = match self.historian_lane_binding(channel, request, "historian.pending") {
            Ok(binding) => binding,
            Err(outcome) => return outcome,
        };
        let session_id = match optional_run_string(request, "session_id") {
            Ok(value) => value,
            Err(outcome) => return outcome,
        };
        let store = match self.store.get() {
            Some(store) => store,
            None => return self.store_refusal(),
        };
        let project_path = match self.historian_lane_project(&binding, store) {
            Ok(project) => project,
            Err(outcome) => return outcome,
        };
        match store.list_pending_historian_runs(&project_path, session_id.as_deref(), now_ms()) {
            Ok(runs) => respond(json!({
                "ok": true,
                "runs": runs
                    .into_iter()
                    .map(|run| json!({
                        "run_id": run.run_id,
                        "session_id": run.session_id,
                        "chunk_fingerprint": run.chunk_fingerprint,
                        "prompt_bytes_len": run.prompt_bytes_len,
                        "deadline_ms": run.deadline_ms,
                    }))
                    .collect::<Vec<_>>(),
            })),
            Err(error) => HandlerOutcome::Error {
                code: "store_load_failed".to_string(),
                message: error.to_string(),
            },
        }
    }

    /// `historian.claim {run_id, claimant_instance_id}` — take a queued run.
    ///
    /// A lost race answers `{ok: false, refusal}` rather than an error frame: two
    /// claimants reaching for the same run is ordinary operation, and the caller's
    /// response is to move to the next run, not to treat the request as failed.
    /// Malformed requests still fail loudly.
    fn handle_historian_claim_value(&self, channel: u16, request: &Value) -> HandlerOutcome {
        let binding = match self.historian_lane_binding(channel, request, "historian.claim") {
            Ok(binding) => binding,
            Err(outcome) => return outcome,
        };
        let run_id = match required_run_string(request, "run_id", "historian.claim") {
            Ok(value) => value,
            Err(outcome) => return outcome,
        };
        let claimant = match required_run_string(request, "claimant_instance_id", "historian.claim")
        {
            Ok(value) => value,
            Err(outcome) => return outcome,
        };
        let store = match self.store.get() {
            Some(store) => store,
            None => return self.store_refusal(),
        };
        let project_path = match self.historian_lane_project(&binding, store) {
            Ok(project) => project,
            Err(outcome) => return outcome,
        };
        match store.claim_historian_run(&project_path, &run_id, &claimant, now_ms()) {
            Ok(mc_store::HistorianClaimOutcome::Claimed(claim)) => {
                let mut body = json!({
                "ok": true,
                "run_id": claim.run_id,
                "session_id": claim.session_id,
                "attempt": claim.attempt,
                "token": claim.token,
                "prompt": {
                    "system": claim.system_prompt,
                    "user": claim.user_prompt,
                },
                "model_chain": claim.model_chain,
                "await_budget_ms": claim.await_budget_ms,
                "claim_deadline_ms": claim.claim_deadline_ms,
                "heartbeat_interval_ms": mc_store::HISTORIAN_HEARTBEAT_INTERVAL_MS,
                });
                // The queuing request's per-attempt timeout. A claimant times each model
                // with it instead of its own configuration; one that predates the field
                // ignores it and keeps its own.
                if let Some(timeout) = claim.historian_timeout_ms {
                    body["historian_timeout_ms"] = json!(timeout);
                }
                respond(body)
            }
            Ok(mc_store::HistorianClaimOutcome::Refused(refusal)) => {
                respond(json!({ "ok": false, "refusal": refusal.as_wire_str() }))
            }
            Err(error) => HandlerOutcome::Error {
                code: "store_write_failed".to_string(),
                message: error.to_string(),
            },
        }
    }

    /// `historian.heartbeat {run_id, token}` — extend the current claim's lease.
    fn handle_historian_heartbeat_value(&self, channel: u16, request: &Value) -> HandlerOutcome {
        let binding = match self.historian_lane_binding(channel, request, "historian.heartbeat") {
            Ok(binding) => binding,
            Err(outcome) => return outcome,
        };
        let run_id = match required_run_string(request, "run_id", "historian.heartbeat") {
            Ok(value) => value,
            Err(outcome) => return outcome,
        };
        let token = match required_run_string(request, "token", "historian.heartbeat") {
            Ok(value) => value,
            Err(outcome) => return outcome,
        };
        let store = match self.store.get() {
            Some(store) => store,
            None => return self.store_refusal(),
        };
        let project_path = match self.historian_lane_project(&binding, store) {
            Ok(project) => project,
            Err(outcome) => return outcome,
        };
        match store.heartbeat_historian_run(&project_path, &run_id, &token, now_ms()) {
            Ok(mc_store::HistorianHeartbeatOutcome::Extended { claim_deadline_ms }) => {
                respond(json!({
                    "ok": true,
                    "claim_deadline_ms": claim_deadline_ms,
                    "heartbeat_interval_ms": mc_store::HISTORIAN_HEARTBEAT_INTERVAL_MS,
                }))
            }
            Ok(mc_store::HistorianHeartbeatOutcome::Refused(refusal)) => {
                respond(json!({ "ok": false, "refusal": refusal.as_wire_str() }))
            }
            Err(error) => HandlerOutcome::Error {
                code: "store_write_failed".to_string(),
                message: error.to_string(),
            },
        }
    }

    /// `historian.complete {run_id, token, output | error}` — the terminal report.
    ///
    /// The token is checked FIRST, before the report body is even read: a claimant
    /// that was replaced still holds a real token, and parsing its output before
    /// establishing that the claim is current would spend validation on a document
    /// that can never be published.
    ///
    /// Accepting a report does not publish it. It hands the text to the firing task
    /// that queued the run, which validates and publishes through exactly the same
    /// code the in-module producer path uses — same parser, same length-cap
    /// refusal, same publish CAS.
    ///
    /// When no task in this process is waiting — which is what a module restart
    /// inside the completion window looks like from here — the report is stored on
    /// the run's queue row instead of being refused, and the next transform pass
    /// for that session publishes it through that same code. A fold takes minutes,
    /// so the module being restarted inside one is ordinary rather than
    /// exceptional, and throwing away a provider call the host already paid for is
    /// the worse of the two answers. `publish` in the response says which of the
    /// two happened, so a claimant can log "handed over" separately from "stored
    /// for the next pass".
    fn handle_historian_complete_value(&self, channel: u16, request: &Value) -> HandlerOutcome {
        let binding = match self.historian_lane_binding(channel, request, "historian.complete") {
            Ok(binding) => binding,
            Err(outcome) => return outcome,
        };
        let run_id = match required_run_string(request, "run_id", "historian.complete") {
            Ok(value) => value,
            Err(outcome) => return outcome,
        };
        let token = match required_run_string(request, "token", "historian.complete") {
            Ok(value) => value,
            Err(outcome) => return outcome,
        };
        let store = match self.store.get() {
            Some(store) => store,
            None => return self.store_refusal(),
        };
        let project_path = match self.historian_lane_project(&binding, store) {
            Ok(project) => project,
            Err(outcome) => return outcome,
        };
        match store.authorize_historian_report(&project_path, &run_id, &token) {
            Ok(mc_store::HistorianReportOutcome::Authorized(_)) => {}
            Ok(mc_store::HistorianReportOutcome::Refused(refusal)) => {
                return respond(json!({ "ok": false, "refusal": refusal.as_wire_str() }));
            }
            Err(error) => {
                return HandlerOutcome::Error {
                    code: "store_load_failed".to_string(),
                    message: error.to_string(),
                };
            }
        }

        let report = match parse_historian_report(request) {
            Ok(report) => report,
            Err(outcome) => return outcome,
        };
        let durable = durable_report(&report);
        match self.host_runs.deliver(&run_id, report) {
            Ok(()) => respond(json!({ "ok": true, "accepted": true, "publish": "immediate" })),
            Err(HostReportDeliveryError::AlreadyReported) => respond(json!({
                "ok": false,
                "refusal": HostReportDeliveryError::AlreadyReported.as_wire_str(),
            })),
            // The token is re-checked inside `record_historian_report`: between the
            // authorization above and this write the lease can lapse and the run can
            // be handed to somebody else, and the replaced claim's report must not
            // be the one that lands.
            Err(HostReportDeliveryError::NoWaiter) => {
                match store.record_historian_report(
                    &project_path,
                    &run_id,
                    &token,
                    &durable,
                    now_ms(),
                ) {
                    Ok(mc_store::HistorianRecordOutcome::Recorded) => {
                        eprintln!(
                            "mc-module: historian report for {run_id} stored for the next pass (no firing task in this process is waiting on it)"
                        );
                        respond(json!({ "ok": true, "accepted": true, "publish": "deferred" }))
                    }
                    Ok(mc_store::HistorianRecordOutcome::Refused(refusal)) => {
                        respond(json!({ "ok": false, "refusal": refusal.as_wire_str() }))
                    }
                    Err(error) => HandlerOutcome::Error {
                        code: "store_write_failed".to_string(),
                        message: error.to_string(),
                    },
                }
            }
        }
    }

    fn handle_session_status_value(&self, channel: u16, request: &Value) -> HandlerOutcome {
        let (session_id, binding) =
            match self.management_binding(channel, request, "session.status") {
                Ok(scope) => scope,
                Err(outcome) => return outcome,
            };
        let store = match self.store.get() {
            Some(store) => store,
            None => return self.store_refusal(),
        };
        if request.get("state_sync_inventory").and_then(Value::as_bool) == Some(true) {
            let (meta, boundary, sequence) =
                match store.load_state_sync_inventory(&session_id, true) {
                    Ok(inventory) => inventory,
                    Err(error) => {
                        return HandlerOutcome::Error {
                            code: "store_load_failed".into(),
                            message: error.to_string(),
                        }
                    }
                };
            return respond(json!({ "state_sync_inventory": {
                "generation": meta.shadow_generation,
                "max_compartment_sequence": if meta.initialized { sequence } else { -1 },
                "boundary_id": if meta.initialized && !boundary.is_empty() { Some(boundary) } else { None },
            }}));
        }
        if let Some(seed_id) = request.get("state_sync_seed_id").and_then(Value::as_str) {
            let (meta, _, _) = match store.load_state_sync_inventory(&session_id, false) {
                Ok(inventory) => inventory,
                Err(error) => {
                    return HandlerOutcome::Error {
                        code: "store_load_failed".into(),
                        message: error.to_string(),
                    }
                }
            };
            let receipt = &meta.shadow_acked_watermarks;
            if receipt.get("_state_sync_seed_id").and_then(Value::as_str) == Some(seed_id)
                && receipt
                    .get("_state_sync_seed_generation")
                    .and_then(Value::as_u64)
                    == Some(meta.shadow_generation)
            {
                return respond(json!({ "state_sync": {
                    "seed_id": seed_id, "generation": meta.shadow_generation,
                    "shadow_seq": meta.shadow_seq, "completed": true,
                }}));
            }
            let mut seeds = self.state_sync_seeds.lock().expect("state sync seed mutex");
            seeds.evict_stale_collectors(self.state_sync_seed_now());
            let status = match seeds.sessions.get(&session_id).map(|state| &state.phase) {
                Some(StateSyncSeedPhase::Collecting(pending))
                    if pending.seed_id == seed_id
                        && pending.generation == meta.shadow_generation
                        && pending.expected_seq == meta.shadow_seq =>
                {
                    json!({
                        "seed_id": seed_id, "generation": pending.generation, "shadow_seq": pending.expected_seq,
                        "next_expected_index": pending.next_index, "completed": false,
                    })
                }
                Some(StateSyncSeedPhase::Applying {
                    seed_id: applying, ..
                }) if applying == seed_id => json!({
                    "seed_id": seed_id, "generation": meta.shadow_generation, "applying": true,
                }),
                _ => Value::Null,
            };
            return respond(json!({ "state_sync": status }));
        }
        let include_compartments_after_seq = match request.get("include_compartments_after_seq") {
            Some(value) => {
                let Some(after_sequence) = value.as_i64().filter(|value| *value >= -1) else {
                    return invalid_params_error(
                        "include_compartments_after_seq must be an integer >= -1",
                    );
                };
                Some((after_sequence, SESSION_STATUS_COMPARTMENT_PAGE_LIMIT))
            }
            None => None,
        };
        let sample_wrapup_latch = || {
            self.wrapup_sessions
                .lock()
                .expect("wrapup sessions mutex")
                .get(&session_id)
                .map(|session| (Arc::as_ptr(&session.token) as usize, session.rounds))
        };
        let latch_before = sample_wrapup_latch();
        let mut snapshot =
            match store.load_session_status_snapshot(&session_id, include_compartments_after_seq) {
                Ok(snapshot) => snapshot,
                Err(error) => {
                    return HandlerOutcome::Error {
                        code: "store_load_failed".to_string(),
                        message: error.to_string(),
                    };
                }
            };
        #[cfg(test)]
        if let Some(hook) = self
            .status_snapshot_hook
            .lock()
            .expect("status snapshot hook mutex")
            .take()
        {
            hook();
        }
        let mut wrapup_latch = sample_wrapup_latch();
        if latch_before != wrapup_latch {
            // Holding the latch mutex across SQLite I/O would block wrapup progress. A single
            // bounded re-read instead places the durable snapshot after the observed latch edge.
            snapshot = match store
                .load_session_status_snapshot(&session_id, include_compartments_after_seq)
            {
                Ok(snapshot) => snapshot,
                Err(error) => {
                    return HandlerOutcome::Error {
                        code: "store_load_failed".to_string(),
                        message: error.to_string(),
                    };
                }
            };
            wrapup_latch = sample_wrapup_latch();
        }
        let loaded = snapshot.loaded;
        let compartment_count = snapshot.compartment_count;
        let pending_drop_count = snapshot.pending_drop_count;
        let tag_count = snapshot.tag_count;
        let pass_trace = snapshot.pass_trace;
        let compartment_page = snapshot.compartment_page;
        let coverage = loaded
            .meta
            .coverage_ordinal
            .map(|ordinal| ordinal.to_string())
            .unwrap_or_else(|| "none".to_string());
        let boundary = if loaded.core.boundary_id.trim().is_empty() {
            "absent"
        } else {
            "present"
        };
        let surface = if loaded.meta.tagging_surface_active || loaded.meta.cc_u1_active {
            "active"
        } else {
            "inactive"
        };
        let descent_counters = &loaded.meta.lineage_descent_counters;
        let descent_pending_build_skew = descent_counters.pending_build_skew;
        let descent_pending_no_responses = descent_counters.pending_no_responses;
        let historian = historian_status_summary(&loaded.meta.historian);
        let consecutive_publish_failures = loaded.meta.historian.consecutive_publish_failures;
        let publish_health = if consecutive_publish_failures >= 3 {
            format!("publish health degraded: {consecutive_publish_failures} consecutive failures")
        } else {
            format!("publish failures: {consecutive_publish_failures}")
        };
        // When the Rust module is active, it manages the frozen m0 in its own store
        // instead of the harness SQLite cache. Report the exact session-history slice so
        // status attribution does not estimate size by summing all raw-history p1 rows.
        let compartment_tokens = loaded
            .core
            .frozen_units
            .iter()
            .find(|unit| unit.key == "m0")
            .and_then(|unit| {
                decay_render::extract_m0_block(&unit.frozen_payload, "session-history")
            })
            .map(|block| mc_tokenizer::estimate_tokens(&block))
            .unwrap_or(0);
        let newest_pass_at = pass_trace
            .as_ref()
            .map(|trace| {
                trace
                    .last_received_at_ms
                    .max(trace.last_completed_at_ms)
                    .max(trace.last_reject_at_ms.unwrap_or(0))
            })
            .unwrap_or(0)
            .max(loaded.meta.last_committed_pass_at_ms);
        let short_session = session_id.chars().take(12).collect::<String>();
        let age = format_traffic_age(newest_pass_at, now_ms());
        // Status can outlive the caller's current lineage. Naming the subject and its
        // durable traffic age makes a stale read visible instead of silently ambiguous.
        // Structured fields accompany the prose so reconciliation code can determine
        // completion without parsing the summary or issuing another operation: a retained
        // delivered-command record includes its coverage, row version, and current wrapup state.
        let m1_signal = match crate::m1_compose::m1_revision_signal_parts_for_pass(
            store,
            &binding.project_root.to_string_lossy(),
            &binding.project_root.to_string_lossy(),
            &session_id,
            loaded.meta.user_profile_version,
            !loaded.meta.memory_disabled,
            now_ms(),
        ) {
            Ok(signal) => Some(signal),
            Err(error) => {
                return HandlerOutcome::Error {
                    code: "store_load_failed".to_string(),
                    message: error.to_string(),
                };
            }
        };
        let pending_m1_delta = loaded.meta.initialized
            && m1_signal.as_ref().is_some_and(|signal| {
                signal.revision != signal.equivalent_applied_revision(loaded.meta.m1_revision)
            });
        let pending_m1_age_ms = pending_m1_delta
            .then(|| now_ms().saturating_sub(loaded.meta.m1_pending_since_ms.unwrap_or(now_ms())));
        let tail_hygiene = loaded.meta.tail_hygiene_baseline.as_ref().map(|baseline| {
            let (u, t) = crate::tail_hygiene::effective_tail_hygiene(baseline);
            json!({
                "u": u,
                "t": t,
                "severity": (u as f64 / t.max(1) as f64).clamp(0.0, 1.0),
                "evaluable": baseline.evaluable && !baseline.generation_invalidated,
                "generation_invalidated": baseline.generation_invalidated,
                "baseline_generation": baseline.baseline_generation,
                "computed_at_ms": baseline.computed_at_ms,
                "reclaimable_tool_output_count": crate::transform::reclaimable_tool_output_count(Some(baseline)),
            })
        });
        let raw_passthrough = raw_passthrough_status(&loaded);
        let raw_passthrough_summary = if raw_passthrough.is_null() {
            String::new()
        } else {
            format!(
                ", serving raw: retained boundary {} absent from the live array",
                loaded.core.boundary_id
            )
        };
        let summary = sanitize_status_text(
            &format!(
                "session {short_session} (last active {age}): {} {}, coverage ordinal {coverage}, boundary {boundary}{raw_passthrough_summary}, {} pending {}, {} {}, pending m1 delta {}, last historian: {historian}, {publish_health}, surface {surface}",
                compartment_count,
                plural_word(compartment_count, "compartment"),
                pending_drop_count,
                plural_word(pending_drop_count, "drop"),
                tag_count,
                plural_word(tag_count, "tag"),
                pending_m1_age_ms
                    .map(|age| format!("true age_ms={age}"))
                    .unwrap_or_else(|| "false".to_string()),
            ),
            500,
        );
        let wrapup_active = wrapup_latch.map(|(_, rounds)| rounds);
        if let Err(error) = self.observe_memory_mirror_frontier(store) {
            return HandlerOutcome::Error {
                code: "store_load_failed".to_string(),
                message: error.to_string(),
            };
        }
        let route_project_root = binding.project_root.to_string_lossy();
        let authority_status = |domain: &str| -> Result<Value, McStoreError> {
            Ok(
                match store.authority_project_state_for_route(&route_project_root, domain)? {
                    Some((project, state)) => json!({ "project": project, "state": state }),
                    None => Value::Null,
                },
            )
        };
        let memory_authority = match authority_status("memories") {
            Ok(authority) => authority,
            Err(error) => {
                return HandlerOutcome::Error {
                    code: "authority_status_failed".to_string(),
                    message: error.to_string(),
                }
            }
        };
        let notes_authority = match authority_status("notes") {
            Ok(authority) => authority,
            Err(error) => {
                return HandlerOutcome::Error {
                    code: "authority_status_failed".to_string(),
                    message: error.to_string(),
                }
            }
        };
        let mut response = json!({
            "ok": true,
            "summary": summary,
            "wrapup_active": wrapup_active.is_some(),
            "wrapup_rounds": wrapup_active,
            "coverage_ordinal": loaded.meta.coverage_ordinal,
            "row_version": loaded.row_version,
            "boundary_present": !loaded.core.boundary_id.trim().is_empty(),
            "compartment_count": compartment_count,
            "compartment_tokens": compartment_tokens,
            "pending_drop_count": pending_drop_count,
            "tag_count": tag_count,
            "pending_m1_delta": pending_m1_delta,
            "pending_m1_age_ms": pending_m1_age_ms,
            "raw_passthrough": raw_passthrough,
            "historian": {
                "consecutive_publish_failures": consecutive_publish_failures,
                "publish_health_degraded": consecutive_publish_failures >= 3,
                "last_outcome": historian,
                "last_failure": &loaded.meta.historian.last_failure,
                "last_no_fire": &loaded.meta.historian.last_no_fire,
                "refusal_stage": loaded.meta.historian.last_failure.as_deref()
                    .or(loaded.meta.historian.last_no_fire.as_deref())
                    .and_then(historian::runner_refusal_stage_from_detail)
                    .map(|stage| stage.as_str()),
                "canonical_cause": loaded.meta.historian.last_failure.as_deref()
                    .or(loaded.meta.historian.last_no_fire.as_deref())
                    .and_then(historian::runner_refusal_stage_from_detail)
                    .map(|stage| stage.canonical_cause()),
                "recent_decisions": &loaded.meta.historian.recent_decisions,
            },
            // Keep the current-pass attribution separate from the explicitly historical
            // `last_divergence` field so stable status reads cannot imply a fresh bust.
            "pass_trace": pass_trace,
            "runtime_store_error": self.runtime_store_error_value(&session_id),
            "memory_mirror": self.memory_mirror_status_value(now_ms().max(0) as u64),
            "single_store": crate::host_store::status_value(),
            "publish_timing": store.load_publish_timing(&session_id).ok().flatten(),
            "authority": {
                "memories": memory_authority,
                "notes": notes_authority,
            },
            "tail_identity_re_adopt_count": loaded.meta.tail_identity_re_adopt_count,
            "fake_compaction": {
                "compaction_seen": descent_counters.compaction_seen,
                "compaction_answered": descent_counters.compaction_answered,
                "fork_arm": descent_counters.fork_arm,
                "descent_pending": {
                    "build_skew": descent_pending_build_skew,
                    "no_responses": descent_pending_no_responses,
                },
                "dispositions": {
                    "descended": descent_counters.descended,
                    "unknown_ancestor": descent_counters.unknown_ancestor,
                    "already_bootstrapped": descent_counters.already_bootstrapped,
                    "not_compaction_shape": descent_counters.not_compaction_shape,
                    "observed_flag_missing_shape_present": descent_counters.observed_flag_missing_shape_present,
                    "cycle_detected": descent_counters.cycle_detected,
                },
                "last_disposition": loaded.meta.lineage_descent_disposition,
                "descent_completed": loaded.meta.descent_completed,
            },
            "epochs": {
                "memory_render_epoch": MEMORY_RENDER_FORMAT_EPOCH,
                "compartment_render_epoch": COMPARTMENT_RENDER_FORMAT_EPOCH,
                "profile_epoch": PROFILE_EPOCH_CLAUDE_CODE_ANTHROPIC,
                "tagger_epoch": TAGGER_FEATURE_EPOCH,
                "state_sync_deltas": true,
                "state_sync_resume": true,
            },
            "usage": {
                "current_total_input_tokens": loaded.meta.last_usage.as_ref().map_or(0, |usage| usage.current_total_input_tokens),
                "context_limit_tokens": loaded.meta.last_usage.as_ref().map_or(0, |usage| usage.context_limit_tokens),
            },
            "tail_hygiene": tail_hygiene,
        });
        if let Some(page) = compartment_page {
            let compartments = page
                .compartments
                .into_iter()
                .map(|compartment| {
                    json!({
                        "sequence": compartment.sequence,
                        "start_message": compartment.start_message,
                        "end_message": compartment.end_message,
                        "start_message_id": compartment.start_message_id,
                        "end_message_id": compartment.end_message_id,
                        "title": compartment.title,
                        "content": compartment.content,
                        "p1": compartment.p1,
                        "p2": compartment.p2,
                        "p3": compartment.p3,
                        "p4": compartment.p4,
                        "importance": compartment.importance,
                        "episode_type": compartment.episode_type,
                        "created_at": compartment.created_at,
                    })
                })
                .collect::<Vec<_>>();
            let body = response
                .as_object_mut()
                .expect("session.status response is an object");
            body.insert("compartments".to_string(), Value::Array(compartments));
            body.insert("max_sequence".to_string(), json!(page.max_sequence));
        }
        respond(response)
    }

    fn wrapup_snapshot_is_current(
        &self,
        store: &McStore,
        session_id: &str,
        generation: u64,
        revert_epoch: u64,
    ) -> Result<bool, McStoreError> {
        let generation_current = self
            .transform_snapshots
            .lock()
            .expect("transform snapshots mutex")
            .ready_generation_matches(session_id, generation);
        if !generation_current {
            return Ok(false);
        }
        Ok(store.load(session_id)?.meta.revert_epoch == revert_epoch)
    }

    fn retryable_wrapup_response(
        reason: RetryableWrapupReason,
        summary: impl Into<String>,
    ) -> HandlerOutcome {
        respond(json!({
            "ok": false,
            "disposition": "retryable",
            "reason": reason.as_str(),
            "summary": summary.into(),
        }))
    }

    fn terminal_wrapup_response(
        &self,
        store: &McStore,
        session_id: &str,
        command_id: Option<&str>,
        expected_generation: u64,
        expected_revert_epoch: u64,
        response: TerminalWrapupResponse,
    ) -> HandlerOutcome {
        let TerminalWrapupResponse {
            disposition,
            rounds,
            summary,
            reason,
            detail,
            include_rounds_without_command,
        } = response;
        debug_assert!(matches!(
            disposition,
            "completed" | "nothing_to_compact" | "failed"
        ));
        let ok = disposition != "failed";
        let (disposition, rounds, summary) = if let Some(command_id) = command_id {
            // The generation check and fenced SQLite insert share this short critical
            // section. The local write is bounded and prevents a transform from starting
            // after validation but before its terminal ledger row becomes durable.
            let snapshots = self
                .transform_snapshots
                .lock()
                .expect("transform snapshots mutex");
            if !snapshots.ready_generation_matches(session_id, expected_generation) {
                return Self::retryable_wrapup_response(
                    RetryableWrapupReason::SnapshotStale,
                    "wrapup snapshot changed before terminal result recording",
                );
            }
            let current = match store.load(session_id) {
                Ok(current) if current.meta.revert_epoch == expected_revert_epoch => current,
                Ok(_) => {
                    return Self::retryable_wrapup_response(
                        RetryableWrapupReason::SnapshotStale,
                        "wrapup state changed before terminal result recording",
                    );
                }
                Err(error) => {
                    return HandlerOutcome::Error {
                        code: "store_load_failed".to_string(),
                        message: error.to_string(),
                    };
                }
            };
            let ledger_summary = if disposition == "failed" {
                terminal_wrapup_failure_summary(
                    reason.unwrap_or("unknown"),
                    &summary,
                    detail.as_deref().unwrap_or("terminal wrapup failure"),
                )
            } else {
                summary.clone()
            };
            match store.record_wrapup_command_if_current(WrapupCommandRecord {
                session_id,
                command_id,
                disposition,
                rounds,
                summary: &ledger_summary,
                created_at: now_ms(),
                expected_row_version: current.row_version,
                expected_revert_epoch,
            }) {
                Ok(RecordWrapupCommandOutcome::Recorded(row)) => {
                    if disposition == "failed" {
                        (row.disposition, row.rounds, summary)
                    } else {
                        (row.disposition, row.rounds, row.summary)
                    }
                }
                Ok(RecordWrapupCommandOutcome::Stale { .. }) => {
                    return Self::retryable_wrapup_response(
                        RetryableWrapupReason::SnapshotStale,
                        "wrapup state changed before terminal result recording",
                    );
                }
                Err(error) => {
                    return HandlerOutcome::Error {
                        code: "store_commit_failed".to_string(),
                        message: format!("could not record terminal wrapup result: {error}"),
                    };
                }
            }
        } else {
            (disposition.to_string(), rounds, summary)
        };
        let mut payload = json!({
            "ok": ok,
            "disposition": disposition,
            "summary": summary,
        });
        if let Some(reason) = reason {
            payload["reason"] = json!(reason);
        }
        if let Some(detail) = detail {
            payload["detail"] = json!(detail);
        }
        if command_id.is_some() || include_rounds_without_command {
            payload["rounds"] = json!(rounds);
        }
        respond(payload)
    }

    fn replayed_wrapup_response(row: mc_store::WrapupCommandRow) -> HandlerOutcome {
        if row.disposition == "failed" {
            if let Some((reason, summary, detail)) = terminal_wrapup_failure_fields(&row.summary) {
                return respond(json!({
                    "ok": false,
                    "disposition": "failed",
                    "rounds": row.rounds,
                    "summary": summary,
                    "reason": reason,
                    "detail": detail,
                    "replayed": true,
                }));
            }
        }
        respond(json!({
            "ok": row.disposition != "failed",
            "disposition": row.disposition,
            "rounds": row.rounds,
            "summary": row.summary,
            "replayed": true,
        }))
    }

    async fn handle_session_wrapup_value(&self, channel: u16, request: &Value) -> HandlerOutcome {
        let deadline = Instant::now()
            .checked_add(self.wrapup_operation_budget())
            .unwrap_or_else(Instant::now);
        let (session_id, binding) =
            match self.management_binding(channel, request, "session.wrapup") {
                Ok(scope) => scope,
                Err(outcome) => return outcome,
            };
        let command_id = match request.get("command_id") {
            None => None,
            Some(value) => match value.as_str() {
                // Empty ids are rejected so every retrying caller cannot collide on one
                // shared durable ledger key.
                Some(command_id) if !command_id.is_empty() && command_id.len() <= 128 => {
                    Some(command_id)
                }
                _ => return HandlerOutcome::Error {
                    code: "bad_request".to_string(),
                    message:
                        "session.wrapup command_id must be a nonempty string of at most 128 bytes"
                            .to_string(),
                },
            },
        };
        let store = match self.store.get() {
            Some(store) => Arc::clone(store),
            None => return self.store_refusal(),
        };
        let route_project_root = binding.project_root.to_string_lossy().to_string();
        let project_path = match store.authority_project_for_route(&route_project_root, "memories")
        {
            Ok(Some(project)) => project,
            Ok(None) => route_project_root,
            Err(error) => {
                return HandlerOutcome::Error {
                    code: "authority_project_resolution_failed".to_string(),
                    message: error.to_string(),
                };
            }
        };
        if let Some(command_id) = command_id {
            match store.load_wrapup_command(&session_id, command_id) {
                // Rows written by the current terminal-failure path carry a marker in their
                // summary, while older failed rows remain eligible for a successful retry.
                Ok(Some(row))
                    if row.disposition == "failed"
                        && terminal_wrapup_failure_fields(&row.summary).is_none() => {}
                Ok(Some(row)) => return Self::replayed_wrapup_response(row),
                Ok(None) => {}
                Err(error) => {
                    return HandlerOutcome::Error {
                        code: "store_load_failed".to_string(),
                        message: error.to_string(),
                    };
                }
            }
        }
        let keep = match request.get("keep") {
            None => 20,
            // The requested keep watermark is honored as given: it counts raw messages of
            // every role, matching the TypeScript orchestrator, which accepts any positive
            // integer and applies only a floor of 1 (the boundary resolver enforces that
            // floor). A negative or zero keep therefore floors to 1 rather than erroring,
            // and no upper clamp exists — a caller asking to keep more than the live tail
            // simply gets a nothing-to-compact outcome.
            Some(value) => match value.as_i64() {
                Some(value) => usize::try_from(value.max(0)).unwrap_or(usize::MAX),
                None => {
                    return HandlerOutcome::Error {
                        code: "bad_request".to_string(),
                        message: "session.wrapup keep must be an integer".to_string(),
                    };
                }
            },
        };

        // The module owns the only store writer, so a process-local per-session latch is
        // sufficient to prevent duplicate producer drives. Durable historian state still
        // protects publication if the process exits while a round is running.
        let wrapup_guard = match self.try_claim_wrapup_session(&session_id) {
            Ok(guard) => guard,
            Err(rounds) => {
                return respond(json!({
                    "ok": true,
                    "disposition": "already_in_progress",
                    "rounds": rounds,
                    "summary": format!("wrapup already in progress, {rounds} rounds done"),
                }));
            }
        };

        let entry_state = match store.load(&session_id) {
            Ok(loaded) => loaded,
            Err(error) => {
                return HandlerOutcome::Error {
                    code: "store_load_failed".to_string(),
                    message: error.to_string(),
                };
            }
        };
        let entry_now = now_ms();
        if let Some(until) = entry_state.meta.historian.failure_backoff_at_ms {
            if until > entry_now {
                return Self::retryable_wrapup_response(
                    RetryableWrapupReason::BackoffActive,
                    format!(
                        "historian failure backoff active for {} ms",
                        until.saturating_sub(entry_now)
                    ),
                );
            }
        }

        let snapshot = self
            .transform_snapshots
            .lock()
            .expect("transform snapshots mutex")
            .get(&session_id);
        let ready = match snapshot {
            TransformSnapshotLookup::Ready(ready) => ready,
            TransformSnapshotLookup::LeaseBudgetExceeded => {
                return Self::retryable_wrapup_response(
                    RetryableWrapupReason::SnapshotUnavailable,
                    "too many concurrent wrapups",
                );
            }
            TransformSnapshotLookup::Missing => {
                return Self::retryable_wrapup_response(
                    RetryableWrapupReason::TransformNotObserved,
                    "wrapup unavailable until a full session transform has been observed",
                );
            }
            // A transform pass is running and will leave a snapshot when it finishes,
            // so a plain retry clears this one.
            TransformSnapshotLookup::InFlight => {
                return Self::retryable_wrapup_response(
                    RetryableWrapupReason::SnapshotUnavailable,
                    "wrapup unavailable while a session transform is in progress",
                );
            }
        };
        let parsed = Arc::clone(&ready.request);
        let initial_snapshot = match store.load_historian_assembly_snapshot(&session_id) {
            Ok(snapshot) => snapshot,
            Err(error) => {
                return HandlerOutcome::Error {
                    code: "store_load_failed".to_string(),
                    message: error.to_string(),
                };
            }
        };
        if ready.revert_epoch != initial_snapshot.revert_epoch {
            return Self::retryable_wrapup_response(
                RetryableWrapupReason::SnapshotStale,
                "wrapup unavailable until a full session transform has been observed",
            );
        }
        let projection = match crate::ck_wire::project_messages(&parsed.messages) {
            Ok(projection) => projection,
            Err(error) => {
                return Self::retryable_wrapup_response(
                    RetryableWrapupReason::SnapshotUnavailable,
                    format!("wrapup boundary assembly failed: {error}"),
                );
            }
        };
        let boundary_messages =
            wrapup_boundary_messages(&parsed, &projection, &self.boundary_tokens);
        self.boundary_tokens
            .lock()
            .expect("boundary token cache mutex")
            .replace(&parsed.session_id, boundary_messages.token_cache_snapshot);
        let boundary_messages = boundary_messages.messages;
        let initial_compartments = initial_snapshot.compartments;
        let initial_end = initial_compartments
            .iter()
            .map(|compartment| compartment.end_message as u64)
            .max();
        // The wrapup boundary snaps against the session's real geometry, resolved with
        // the same usage -> soft-geometry -> fallback order and host-threshold preference
        // as the historian trigger, so the user-boundary snap window matches the
        // TypeScript wrapup resolver instead of a synthetic constant.
        let wrapup_cfg = self.effective_config(&binding.project_root);
        let (wrapup_context_limit, _, _) =
            usage_numbers(parsed.usage.as_ref(), parsed.geometry.as_ref());
        let wrapup_threshold = parsed.execute_threshold_or(
            wrapup_cfg
                .resolve_execute_threshold(parsed.model_key.as_deref())
                .percentage,
        );
        let plan = boundary::resolve_wrapup_boundary(
            &boundary_messages,
            initial_end,
            keep,
            wrapup_context_limit,
            wrapup_threshold,
        );
        let target = plan.target_protected_start_ordinal;
        match self.wrapup_snapshot_is_current(
            &store,
            &session_id,
            ready.generation,
            ready.revert_epoch,
        ) {
            Ok(true) => {}
            Ok(false) => {
                return Self::retryable_wrapup_response(
                    RetryableWrapupReason::SnapshotStale,
                    "wrapup unavailable until a full session transform has been observed",
                );
            }
            Err(error) => {
                return HandlerOutcome::Error {
                    code: "store_load_failed".to_string(),
                    message: error.to_string(),
                };
            }
        }
        if plan.raw_messages_above_last_compartment <= keep
            || !wrapup_has_remaining_messages(&parsed.messages, initial_end, target)
        {
            return self.terminal_wrapup_response(
                &store,
                &session_id,
                command_id,
                ready.generation,
                ready.revert_epoch,
                TerminalWrapupResponse {
                    disposition: "nothing_to_compact",
                    rounds: 0,
                    summary: format!(
                        "nothing to compact; {} raw messages already fit within the keep watermark of {keep}",
                        plan.raw_messages_above_last_compartment,
                    ),
                    reason: None,
                    detail: None,
                    include_rounds_without_command: true,
                },
            );
        }

        let mut rounds = 0usize;
        let mut failure: Option<(RetryableWrapupReason, String)> = None;
        let mut terminal_failure: Option<(&'static str, String)> = None;
        // This observation is local to the current runner loop execution. A runner that is
        // still starting gets one bounded chance before a repeated route absence becomes terminal.
        let mut unknown_module_observed_at = None;
        // No round-count cap: the drain loops until the keep watermark is reached or a
        // stop condition trips. The request budget is the ceiling — every round re-checks
        // the deadline before driving, matching the TypeScript drain-until-target loop.
        loop {
            if Self::remaining_wrapup_budget(deadline).is_none() {
                failure = Some((
                    RetryableWrapupReason::BudgetExhausted,
                    "wrapup request budget expired before the next round".to_string(),
                ));
                break;
            }
            if !self
                .transform_snapshots
                .lock()
                .expect("transform snapshots mutex")
                .ready_generation_matches(&session_id, ready.generation)
            {
                failure = Some((
                    RetryableWrapupReason::SnapshotStale,
                    "wrapup unavailable because a newer full session transform started".to_string(),
                ));
                break;
            }
            let current_state = match store.load(&session_id) {
                Ok(loaded) => loaded,
                Err(error) => {
                    return HandlerOutcome::Error {
                        code: "store_load_failed".to_string(),
                        message: error.to_string(),
                    };
                }
            };
            if current_state.meta.revert_epoch != ready.revert_epoch {
                failure = Some((
                    RetryableWrapupReason::SnapshotStale,
                    "wrapup unavailable until a full session transform has been observed"
                        .to_string(),
                ));
                break;
            }
            let round_now = now_ms();
            if unknown_module_observed_at.is_none() {
                if let Some(until) = current_state.meta.historian.failure_backoff_at_ms {
                    if until > round_now {
                        failure = Some((
                            RetryableWrapupReason::BackoffActive,
                            format!(
                                "historian failure backoff active for {} ms",
                                until.saturating_sub(round_now)
                            ),
                        ));
                        break;
                    }
                }
            }
            let current_end = match store.max_compartment_end_ordinal(&session_id) {
                Ok(ordinal) => (ordinal > 0).then_some(ordinal as u64),
                Err(error) => {
                    return HandlerOutcome::Error {
                        code: "store_load_failed".to_string(),
                        message: error.to_string(),
                    };
                }
            };
            if !wrapup_has_remaining_messages(&parsed.messages, current_end, target) {
                break;
            }
            // Assembly re-reads one historian snapshot for this round. The firing carries
            // that snapshot's revert epoch, and publication loads the current row version
            // immediately before its store CAS, so a transform re-cut during production is
            // rejected at publication rather than publishing against retired state.
            let prepared = self.prepare_wrapup_fire(
                Arc::clone(&store),
                &parsed,
                &binding,
                &projection,
                &plan.boundary,
                WrapupPrepareContext {
                    now: round_now,
                    project_path: project_path.clone(),
                    allow_unknown_module_retry: unknown_module_observed_at.is_some(),
                },
            );
            // Assembly performs store reads, so verify the raw-history generation again
            // before joining or driving the action it produced. A transform that started
            // during assembly must invalidate this round.
            if !self
                .transform_snapshots
                .lock()
                .expect("transform snapshots mutex")
                .ready_generation_matches(&session_id, ready.generation)
            {
                failure = Some((
                    RetryableWrapupReason::SnapshotStale,
                    "wrapup unavailable because a newer full session transform started".to_string(),
                ));
                break;
            }
            match prepared {
                PreparedWrapupAction::FilteredNoiseSkipped => continue,
                PreparedWrapupAction::Busy(completion) => {
                    let join_budget = Self::active_firing_join_budget(
                        parsed.historian_model_chain.as_deref(),
                        parsed.historian_timeout_ms,
                    );
                    if let Err(reason) = self
                        .await_wrapup_historian_completion(completion, deadline, join_budget)
                        .await
                    {
                        let retry_reason = if reason.contains("request budget expired") {
                            RetryableWrapupReason::BudgetExhausted
                        } else {
                            RetryableWrapupReason::SnapshotUnavailable
                        };
                        failure = Some((retry_reason, reason));
                        break;
                    }
                }
                PreparedWrapupAction::Nothing(reason) => {
                    failure = Some((
                        RetryableWrapupReason::SnapshotUnavailable,
                        format!("historian made no forward progress: {reason}"),
                    ));
                    break;
                }
                PreparedWrapupAction::Failed(reason) => {
                    if reason == "no historian models are configured" {
                        terminal_failure = Some(("no_models", reason));
                        break;
                    }
                    if reason == WRAPUP_MODEL_CHAIN_MISSING {
                        terminal_failure = Some(("model_chain_missing", reason));
                        break;
                    }
                    let retry_reason = if reason.contains("backoff") {
                        RetryableWrapupReason::BackoffActive
                    } else {
                        RetryableWrapupReason::SnapshotUnavailable
                    };
                    failure = Some((retry_reason, reason));
                    break;
                }
                PreparedWrapupAction::FireReady(task) => {
                    let mut task = *task;
                    task.publication_fence = Some(Arc::new(WrapupSnapshotPublicationFence {
                        snapshots: Arc::clone(&self.transform_snapshots),
                        session_id: session_id.clone(),
                        generation: ready.generation,
                        #[cfg(test)]
                        after_store_publish: Arc::clone(&self.publication_fence_write_hook),
                    }));
                    match self.run_wrapup_firing(task, deadline).await {
                        Ok(historian::HistorianDriveOutcome::Completed(_)) => {
                            let after_end = store
                                .max_compartment_end_ordinal(&session_id)
                                .ok()
                                .and_then(|ordinal| (ordinal > 0).then_some(ordinal as u64));
                            if after_end <= current_end {
                                failure = Some((
                                    RetryableWrapupReason::SnapshotUnavailable,
                                    "historian completed without advancing the compartment boundary"
                                        .to_string(),
                                ));
                                break;
                            }
                            rounds += 1;
                            wrapup_guard.set_rounds(rounds);
                        }
                        Ok(historian::HistorianDriveOutcome::Busy(_)) => {
                            failure = Some((
                                RetryableWrapupReason::SnapshotUnavailable,
                                "historian became busy before the round started".to_string(),
                            ));
                            break;
                        }
                        Err(WrapupFiringError::Retryable(reason, detail)) => {
                            failure = Some((reason, detail));
                            break;
                        }
                        Err(WrapupFiringError::Terminal { reason, detail }) => {
                            terminal_failure = Some((reason, detail));
                            break;
                        }
                        Err(WrapupFiringError::UnknownModule(detail)) => {
                            if unknown_module_observed_at.is_some() {
                                terminal_failure = Some(("runner_module_unavailable", detail));
                                break;
                            }
                            unknown_module_observed_at = Some(Instant::now());
                            let delay = self.unknown_module_retry_delay();
                            let Some(remaining) = Self::remaining_wrapup_budget(deadline) else {
                                failure = Some((
                                    RetryableWrapupReason::BudgetExhausted,
                                    "wrapup request budget expired before retrying an unavailable runner module"
                                        .to_string(),
                                ));
                                break;
                            };
                            if delay > remaining {
                                failure = Some((
                                    RetryableWrapupReason::BudgetExhausted,
                                    "wrapup request budget expired before retrying an unavailable runner module"
                                        .to_string(),
                                ));
                                break;
                            }
                            tokio::time::sleep(delay).await;
                        }
                    }
                }
            }
        }

        let final_compartments = match store.load_compartments(&session_id) {
            Ok(compartments) => compartments,
            Err(error) => {
                return HandlerOutcome::Error {
                    code: "store_load_failed".to_string(),
                    message: error.to_string(),
                };
            }
        };
        let final_end = final_compartments
            .iter()
            .map(|compartment| compartment.end_message as u64)
            .max();
        let compacted_messages = parsed
            .messages
            .iter()
            .filter(|message| !message.ck.meta.synthetic)
            .filter(|message| initial_end.is_none_or(|end| message.ordinal > end))
            .filter(|message| final_end.is_some_and(|end| message.ordinal <= end))
            .count();
        let compartments_created = final_compartments
            .len()
            .saturating_sub(initial_compartments.len());
        // The drain loop only exits without a failure after the no-remaining-messages
        // check, and compartments never shrink, so a failure-free exit has reached the
        // keep watermark. Assert the invariant instead of carrying a round-cap fallback;
        // failure exits legitimately stop short of the watermark.
        debug_assert!(
            failure.is_some()
                || terminal_failure.is_some()
                || !wrapup_has_remaining_messages(&parsed.messages, final_end, target)
        );
        if let Some((reason, detail)) = terminal_failure {
            return self.terminal_wrapup_response(
                &store,
                &session_id,
                command_id,
                ready.generation,
                ready.revert_epoch,
                TerminalWrapupResponse {
                    disposition: "failed",
                    rounds,
                    summary: format!(
                        "compacted {compacted_messages} messages into {compartments_created} compartments; wrapup stopped permanently"
                    ),
                    reason: Some(reason),
                    detail: Some(detail),
                    include_rounds_without_command: true,
                },
            );
        }
        let effect = "takes effect on your next message";
        match failure {
            Some((reason, detail)) => Self::retryable_wrapup_response(
                reason,
                format!(
                    "compacted {compacted_messages} messages into {compartments_created} compartments; {detail}; {effect}"
                ),
            ),
            None if rounds == 0 => self.terminal_wrapup_response(
                &store,
                &session_id,
                command_id,
                ready.generation,
                ready.revert_epoch,
                TerminalWrapupResponse {
                    disposition: "nothing_to_compact",
                    rounds: 0,
                     summary:
                         "nothing to compact; the tail is already within the keep watermark"
                             .to_string(),
                     reason: None,
                     detail: None,
                     include_rounds_without_command: true,
                },
            ),
            None => self.terminal_wrapup_response(
                &store,
                &session_id,
                command_id,
                ready.generation,
                ready.revert_epoch,
                TerminalWrapupResponse {
                    disposition: "completed",
                    rounds,
                     summary: format!(
                         "compacted {compacted_messages} messages into {compartments_created} compartments; {effect}"
                     ),
                     reason: None,
                     detail: None,
                     include_rounds_without_command: true,
                },
            ),
        }
    }

    fn handle_authority_status_value(&self, channel: u16, request: &Value) -> HandlerOutcome {
        let Some(store) = self.store.get() else {
            return self.store_refusal();
        };
        let Some((context_store_uuid, project, domain)) = authority_request_key(request) else {
            return invalid_params_error(
                "authority.status requires context_store_uuid, project, and domain",
            );
        };
        match store.authority_status(context_store_uuid, project, domain) {
            Ok(Some(row)) => {
                if row.state == "MODULE" {
                    if let Err(error) =
                        self.bind_authority_route(store, channel, context_store_uuid, project)
                    {
                        return HandlerOutcome::Error {
                            code: "authority_route_binding_failed".to_string(),
                            message: error.to_string(),
                        };
                    }
                }
                respond(json!({ "ok": true, "authority": row }))
            }
            Ok(None) => respond(json!({ "ok": true, "authority": null })),
            Err(error) => HandlerOutcome::Error {
                code: "authority_status_failed".to_string(),
                message: error.to_string(),
            },
        }
    }

    fn handle_authority_prepare_value(&self, channel: u16, request: &Value) -> HandlerOutcome {
        let Some(store) = self.store.get() else {
            return self.store_refusal();
        };
        let Some((context_store_uuid, project, domain)) = authority_request_key(request) else {
            return invalid_params_error(
                "authority.prepare requires context_store_uuid, project, and domain",
            );
        };
        let phase = request
            .get("phase")
            .and_then(Value::as_str)
            .unwrap_or("begin");
        let result = match phase {
            "begin" => store.authority_begin_prepare(context_store_uuid, project, domain),
            "complete" => {
                let Some(expected_generation) = request.get("generation").and_then(Value::as_u64)
                else {
                    return invalid_params_error("authority.prepare complete requires generation");
                };
                let expected = request
                    .get("checksum_expected")
                    .and_then(Value::as_str)
                    .unwrap_or("");
                let actual =
                    match store.authority_seed_checksum(context_store_uuid, project, domain) {
                        Ok(checksum) => checksum,
                        Err(error) => {
                            return HandlerOutcome::Error {
                                code: "authority_checksum_failed".to_string(),
                                message: error.to_string(),
                            };
                        }
                    };
                store.authority_verify_prepare(
                    context_store_uuid,
                    project,
                    domain,
                    expected_generation,
                    expected,
                    &actual,
                )
            }
            "ack" => {
                let Some(expected_generation) = request.get("generation").and_then(Value::as_u64)
                else {
                    return invalid_params_error("authority.prepare ack requires generation");
                };
                store.authority_ack_prepare(
                    context_store_uuid,
                    project,
                    domain,
                    expected_generation,
                )
            }
            "abort" => {
                let Some(expected_generation) = request.get("generation").and_then(Value::as_u64)
                else {
                    return invalid_params_error("authority.prepare abort requires generation");
                };
                store.authority_abort_prepare(
                    context_store_uuid,
                    project,
                    domain,
                    expected_generation,
                )
            }
            _ => {
                return invalid_params_error(
                    "authority.prepare phase must be begin, complete, ack, or abort",
                );
            }
        };
        match result {
            Ok(row) => {
                if row.state == "MODULE" {
                    if let Err(error) =
                        self.bind_authority_route(store, channel, context_store_uuid, project)
                    {
                        return HandlerOutcome::Error {
                            code: "authority_route_binding_failed".to_string(),
                            message: error.to_string(),
                        };
                    }
                }
                respond(json!({ "ok": true, "authority": row }))
            }
            Err(error) => HandlerOutcome::Error {
                code: "authority_prepare_failed".to_string(),
                message: error.to_string(),
            },
        }
    }

    fn handle_authority_seed_value(&self, request: &Value) -> HandlerOutcome {
        let Some(store) = self.store.get() else {
            return self.store_refusal();
        };
        let Some((context_store_uuid, project, domain)) = authority_request_key(request) else {
            return invalid_params_error(
                "authority.seed requires context_store_uuid, project, and domain",
            );
        };
        let Some(rows) = request.get("rows").and_then(Value::as_array) else {
            return invalid_params_error("authority.seed requires a rows array");
        };
        let mut seed_rows = Vec::with_capacity(rows.len());
        for row in rows {
            let source_row_id = row
                .get("source_row_id")
                .and_then(Value::as_i64)
                .or_else(|| {
                    row.get("snapshot")
                        .and_then(|value| value.get("id"))
                        .and_then(Value::as_i64)
                });
            let Some(source_row_id) = source_row_id else {
                return invalid_params_error("authority.seed rows require source_row_id");
            };
            let snapshot = row.get("snapshot").unwrap_or(row);
            if snapshot.get("project_path").and_then(Value::as_str) != Some(project) {
                return HandlerOutcome::Error {
                    code: "authority_seed_project_mismatch".to_string(),
                    message: "seed snapshot project_path did not match the authority project"
                        .to_string(),
                };
            }
            seed_rows.push(AuthoritySeedRow {
                source_row_id,
                snapshot: snapshot.clone(),
            });
        }
        let module_row_ids =
            match store.seed_authority_rows(context_store_uuid, project, domain, &seed_rows) {
                Ok(ids) => ids,
                Err(error) => {
                    return HandlerOutcome::Error {
                        code: "authority_seed_failed".to_string(),
                        message: error.to_string(),
                    };
                }
            };
        respond(
            json!({ "ok": true, "seeded": module_row_ids.len(), "module_row_ids": module_row_ids }),
        )
    }

    fn handle_authority_drain_value(&self, request: &Value, method: &str) -> HandlerOutcome {
        let Some(store) = self.store.get() else {
            return self.store_refusal();
        };
        let Some((context_store_uuid, project, domain)) = authority_request_key(request) else {
            return invalid_params_error(
                "authority drain requires context_store_uuid, project, and domain",
            );
        };
        let action = request
            .get("action")
            .and_then(Value::as_str)
            .or_else(|| method.strip_prefix("authority.drain."))
            .unwrap_or("step");
        let result = match action {
            "begin" => {
                let lease = request.get("lease").and_then(Value::as_str).unwrap_or("");
                let expires = request
                    .get("lease_expires_at")
                    .and_then(Value::as_i64)
                    .unwrap_or(0);
                let started_at = request
                    .get("lease_started_at")
                    .and_then(Value::as_i64)
                    .unwrap_or_else(now_ms);
                store.authority_begin_drain(
                    context_store_uuid,
                    project,
                    domain,
                    lease,
                    expires,
                    started_at,
                )
            }
            "finish" | "flip" => {
                let Some(generation) = request.get("generation").and_then(Value::as_u64) else {
                    return invalid_params_error("authority drain finish requires generation");
                };
                let token = request
                    .get("coordinator_token")
                    .and_then(Value::as_str)
                    .unwrap_or("");
                let now = request
                    .get("now_ms")
                    .and_then(Value::as_i64)
                    .unwrap_or_else(now_ms);
                store.authority_finish_drain(
                    context_store_uuid,
                    project,
                    domain,
                    generation,
                    request
                        .get("checksum_expected")
                        .and_then(Value::as_str)
                        .unwrap_or(""),
                    request
                        .get("checksum_actual")
                        .and_then(Value::as_str)
                        .unwrap_or(""),
                    request
                        .get("verified")
                        .and_then(Value::as_bool)
                        .unwrap_or(false),
                    token,
                    now,
                )
            }
            step => {
                let Some(generation) = request.get("generation").and_then(Value::as_u64) else {
                    return invalid_params_error("authority drain step requires generation");
                };
                let step = step.strip_prefix("drain_").unwrap_or(step);
                let token = request
                    .get("coordinator_token")
                    .and_then(Value::as_str)
                    .unwrap_or("");
                let now = request
                    .get("now_ms")
                    .and_then(Value::as_i64)
                    .unwrap_or_else(now_ms);
                store.authority_drain_step(
                    context_store_uuid,
                    project,
                    domain,
                    generation,
                    step,
                    request.get("cursor").and_then(Value::as_i64),
                    token,
                    now,
                )
            }
        };
        match result {
            Ok(row) => respond(json!({ "ok": true, "authority": row })),
            Err(McStoreError::AuthorityFeedHeadAdvanced { captured, found }) => {
                HandlerOutcome::Error {
                    code: "authority_feed_head_advanced".to_string(),
                    message: format!(
                        "authority_feed_head_advanced: captured {captured}, found {found}"
                    ),
                }
            }
            Err(error) => HandlerOutcome::Error {
                code: "authority_drain_failed".to_string(),
                message: error.to_string(),
            },
        }
    }

    fn handle_mirror_memory_value(&self, request: &Value) -> HandlerOutcome {
        let Some(store) = self.store.get() else {
            return self.store_refusal();
        };
        let Some(module_row_id) = request.get("module_row_id").and_then(Value::as_i64) else {
            return invalid_params_error("mirror.memory requires module_row_id");
        };
        match store.pull_memory_changefeed_row(module_row_id) {
            Ok(row) => respond(json!({ "ok": true, "row": row })),
            Err(error) => HandlerOutcome::Error {
                code: "mirror_memory_failed".to_string(),
                message: error.to_string(),
            },
        }
    }

    fn handle_memory_identity_ack_value(&self, request: &Value) -> HandlerOutcome {
        let Some(store) = self.store.get() else {
            return self.store_refusal();
        };
        let Some(project) = request.get("project").and_then(Value::as_str) else {
            return invalid_params_error("memory.identity.ack requires project");
        };
        let Some(rows) = request.get("rows").and_then(Value::as_array) else {
            return invalid_params_error("memory.identity.ack requires rows");
        };
        let acknowledgements = rows
            .iter()
            .map(|row| {
                Some(HostMemoryIdentityAck {
                    module_row_id: row.get("module_row_id")?.as_i64()?,
                    host_row_id: row.get("context_row_id")?.as_i64()?,
                })
            })
            .collect::<Option<Vec<_>>>();
        let Some(acknowledgements) = acknowledgements else {
            return invalid_params_error(
                "memory.identity.ack rows require module_row_id and context_row_id",
            );
        };
        match store.acknowledge_host_memory_ids(project, &acknowledgements) {
            Ok(acknowledged) => respond(json!({ "ok": true, "acknowledged": acknowledged })),
            Err(error) => HandlerOutcome::Error {
                code: "memory_identity_ack_failed".to_string(),
                message: error.to_string(),
            },
        }
    }

    /// The `context.db` the single-store marker is read from.
    fn context_db_path(&self) -> PathBuf {
        #[cfg(test)]
        if let Some(path) = self
            .context_db_path_override
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .clone()
        {
            return path;
        }
        host_store::resolve_context_db_path()
    }

    /// Read which projects are marked single-store, answering a refusal when `project`
    /// is one of them or when the marker cannot be trusted.
    ///
    /// `project` is `None` for a caller that predates the marker (see
    /// `handle_mirror_pull_value`); it is refused only when the marker cannot be read.
    /// An open failure (for example no `context.db` at all) is reported under
    /// `open_failure_code`, because it says nothing about any project's marker.
    fn single_store_markers_for(
        &self,
        project: Option<&str>,
        open_failure_code: &str,
    ) -> Result<host_store::MarkerSnapshot, HandlerOutcome> {
        let path = self.context_db_path();
        match host_store::read_marker_snapshot(&path) {
            Ok(snapshot) if project.is_some_and(|project| snapshot.is_marked(project)) => {
                let project = project.unwrap_or_default();
                Err(HandlerOutcome::Error {
                code: host_store::SINGLE_STORE_TRIPWIRE_CODE.to_string(),
                    message: format!(
                        "project {project} is marked single-store in context.db; the store.db mirror does not serve it"
                    ),
                })
            }
            Ok(snapshot) => Ok(snapshot),
            Err(host_store::MarkerReadError::Open(error)) => Err(HandlerOutcome::Error {
                code: open_failure_code.to_string(),
                message: error.to_string(),
            }),
            Err(host_store::MarkerReadError::Untrusted(error)) => Err(HandlerOutcome::Error {
                code: host_store::SINGLE_STORE_TRIPWIRE_CODE.to_string(),
                message: format!(
                    "{}: the single-store marker cannot be read, so no project on this context.db is served: {error}",
                    error.code()
                ),
            }),
        }
    }

    /// Answer whether `project` may use the store.db mirror, without touching either
    /// database beyond the marker read. The plugin asks this before it starts a drain,
    /// a reconcile reset or a pull, so a refusal lands before any of their writes.
    fn handle_mirror_marker_status_value(&self, request: &Value) -> HandlerOutcome {
        let Some(project) = request.get("project").and_then(Value::as_str) else {
            return invalid_params_error("mirror.marker_status requires project");
        };
        match self.single_store_markers_for(Some(project), "mirror_pull_failed") {
            // The path lets the host confirm that it and the module read the same file;
            // the module resolves it from its own environment, not the host's.
            Ok(snapshot) => respond(json!({
                "ok": true,
                "marked": false,
                "below_lane": snapshot.below_lane,
                "context_db_path": self.context_db_path().display().to_string(),
            })),
            Err(outcome) => outcome,
        }
    }

    fn handle_mirror_pull_value(&self, request: &Value) -> HandlerOutcome {
        let Some(store) = self.store.get() else {
            return self.store_refusal();
        };
        let Some(domain) = request.get("domain").and_then(Value::as_str) else {
            return invalid_params_error("mirror.pull requires domain");
        };
        // A plugin built before the single-store marker sends no `project`. Such a plugin
        // cannot open a context.db at the marker lane (its schema fence is lower), so it
        // cannot be pulling for a marked project; it is served with the same exclusion
        // every other page gets, rather than refused.
        let project = request.get("project").and_then(Value::as_str);
        // Read before either pager: a marked project's pull is refused outright, and an
        // unmarked project's changefeed page leaves out every marked project's rows.
        let markers = match self.single_store_markers_for(project, "mirror_pull_failed") {
            Ok(markers) => markers,
            Err(outcome) => return outcome,
        };
        let cursor = request.get("cursor").and_then(Value::as_i64).unwrap_or(0);
        let limit = request.get("limit").and_then(Value::as_u64).unwrap_or(100) as usize;
        let live_only = request
            .get("live_only")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let page = if live_only {
            if domain != "memories" {
                return invalid_params_error("live mirror snapshots currently support memories");
            }
            store.pull_live_memory_snapshot(cursor, limit)
        } else {
            store
                .pull_changefeed(domain, cursor, limit)
                .map(|page| exclude_marked_projects(page, &markers))
        };
        match page {
            Ok(page) => {
                if domain == "memories" && !live_only {
                    if let (Ok(feed_head), Ok(live_rows)) = (
                        store.changefeed_head("memories"),
                        store.live_memory_row_count(),
                    ) {
                        self.memory_mirror_health
                            .observe_frontier(feed_head, live_rows);
                    }
                    self.memory_mirror_health
                        .observe_pull(page.next_cursor, now_ms().max(0) as u64);
                }
                respond(json!({ "ok": true, "page": page }))
            }
            Err(error) => HandlerOutcome::Error {
                code: "mirror_pull_failed".to_string(),
                message: error.to_string(),
            },
        }
    }

    fn freeze_prompt_surface_selection(
        &self,
        session_id: &str,
        requested: PromptSurfaceSelection,
    ) -> PromptSurfaceSelection {
        let mut epochs = self
            .prompt_surface_epochs
            .lock()
            .expect("prompt surface epoch mutex");
        if let Some(frozen) = epochs.get(session_id) {
            if frozen.model_key == requested.model_key
                && prompt_surface::selection_freeze_identity(frozen)
                    == prompt_surface::selection_freeze_identity(&requested)
            {
                return frozen.clone();
            }
        }
        epochs.insert(session_id.to_string(), requested.clone());
        requested
    }

    fn prompt_surface_selection_from_value(
        &self,
        request: &Value,
    ) -> Result<PromptSurfaceSelection, HandlerOutcome> {
        let preset = match request
            .get("preset")
            .or_else(|| request.get("prompt_surface_preset"))
        {
            None | Some(Value::Null) => PromptSurfacePreset::Full,
            Some(Value::String(value)) if value == "full" => PromptSurfacePreset::Full,
            Some(Value::String(value)) if value == "light" => PromptSurfacePreset::Light,
            _ => {
                return Err(invalid_params_error(
                    "prompt_surface preset must be \"full\" or \"light\"",
                ));
            }
        };
        let model_key = request
            .get("prompt_surface_model_key")
            .or_else(|| request.get("model_key"))
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(str::to_string);
        let config_identity = match request
            .get("prompt_surface_config_identity")
            .or_else(|| request.get("config_identity"))
        {
            None | Some(Value::Null) => String::new(),
            Some(Value::String(value)) => value.trim().to_string(),
            _ => {
                return Err(invalid_params_error(
                    "prompt_surface config identity must be a string",
                ));
            }
        };
        let descriptions = request
            .get("tool_descriptions")
            .or_else(|| request.get("prompt_surface_tool_descriptions"));
        let mut tool_descriptions = BTreeMap::new();
        if let Some(value) = descriptions.filter(|value| !value.is_null()) {
            let Some(object) = value.as_object() else {
                return Err(invalid_params_error(
                    "prompt_surface tool_descriptions must be an object",
                ));
            };
            for (tool_id, description) in object {
                if !prompt_surface::is_known_tool_id(tool_id) {
                    prompt_surface::warn_ignored_unknown_tool_description(tool_id);
                    continue;
                }
                let Some(description) = description.as_str() else {
                    return Err(invalid_params_error(format!(
                        "prompt_surface tool_descriptions.{tool_id} must be a string"
                    )));
                };
                if description.trim().is_empty() {
                    return Err(invalid_params_error(format!(
                        "prompt_surface tool_descriptions.{tool_id} must not be empty"
                    )));
                }
                tool_descriptions.insert(tool_id.clone(), description.to_string());
            }
        }
        let guidance_override = match request
            .get("guidance_override")
            .or_else(|| request.get("prompt_surface_guidance_override"))
        {
            None | Some(Value::Null) => None,
            Some(Value::String(value)) if !value.trim().is_empty() => Some(value.clone()),
            Some(Value::String(_)) => None,
            _ => {
                return Err(invalid_params_error(
                    "prompt_surface guidance_override must be a string",
                ));
            }
        };
        Ok(PromptSurfaceSelection {
            model_key,
            config_identity,
            preset,
            guidance_override,
            tool_descriptions,
        })
    }

    fn handle_prompt_surface_manifest_value(
        &self,
        channel: u16,
        request: &Value,
    ) -> HandlerOutcome {
        let Some(session_id) = request.get("session_id").and_then(Value::as_str) else {
            return invalid_params_error("manifest.get requires session_id");
        };
        let binding = match self.resolve_binding(channel, session_id) {
            Ok(binding) => binding,
            Err(error) => {
                return match error {
                    BindingError::Unbound => HandlerOutcome::Error {
                        code: "route_unbound".to_string(),
                        message: "manifest.get on a channel with no session binding".to_string(),
                    },
                    BindingError::SessionMismatch => HandlerOutcome::Error {
                        code: "session_mismatch".to_string(),
                        message: "request session_id does not match the channel's bound session"
                            .to_string(),
                    },
                };
            }
        };
        let mut requested = match self.prompt_surface_selection_from_value(request) {
            Ok(selection) => selection,
            Err(error) => return error,
        };
        if requested.guidance_override.is_none() {
            requested.guidance_override = binding.config.prompt_surface_guidance_override;
        }
        let selection = self.freeze_prompt_surface_selection(session_id, requested);
        let tools = prompt_surface::session_tools(&selection);
        respond(json!({
            "ok": true,
            "preset": selection.preset.as_str(),
            "served_preset": if prompt_surface::tool_manifest_falls_back(selection.preset) {
                "full"
            } else {
                selection.preset.as_str()
            },
            "preset_fallback": prompt_surface::tool_manifest_falls_back(selection.preset),
            "fallback_notice": prompt_surface::tool_manifest_falls_back(selection.preset)
                .then_some(prompt_surface::LIGHT_FALLBACK_NOTICE),
            "content_epoch": prompt_surface::manifest_content_epoch(&selection),
            "tools": tools,
        }))
    }

    fn handle_guidance_value(&self, channel: u16, request: &Value) -> HandlerOutcome {
        let store = match self.store.get() {
            Some(store) => Arc::clone(store),
            None => return self.store_refusal(),
        };
        let Some(session_id) = request.get("session_id").and_then(Value::as_str) else {
            return HandlerOutcome::Error {
                code: "bad_request".to_string(),
                message: "guidance.get requires session_id".to_string(),
            };
        };
        let binding = match self.resolve_binding(channel, session_id) {
            Ok(binding) => binding,
            Err(error) => {
                return match error {
                    BindingError::Unbound => HandlerOutcome::Error {
                        code: "route_unbound".to_string(),
                        message: "guidance.get on a channel with no session binding".to_string(),
                    },
                    BindingError::SessionMismatch => HandlerOutcome::Error {
                        code: "session_mismatch".to_string(),
                        message: "request session_id does not match the channel's bound session"
                            .to_string(),
                    },
                };
            }
        };

        let tool_present = match request.get("tool_present") {
            None => false,
            Some(value) => match value.as_bool() {
                Some(value) => value,
                None => {
                    return HandlerOutcome::Error {
                        code: "bad_request".to_string(),
                        message: "guidance.get tool_present must be a boolean".to_string(),
                    };
                }
            },
        };
        let profile = match request.get("serializer_profile").and_then(Value::as_str) {
            None => Some(SerializerProfile::ClaudeCodeAnthropic),
            Some(value) => match SerializerProfile::parse(value) {
                Some(profile) => Some(profile),
                None => return unknown_serializer_profile_error(),
            },
        };
        let mut requested_selection = match self.prompt_surface_selection_from_value(request) {
            Ok(selection) => selection,
            Err(error) => return error,
        };
        if requested_selection.guidance_override.is_none() {
            requested_selection.guidance_override = binding.config.prompt_surface_guidance_override;
        }
        let selection = self.freeze_prompt_surface_selection(session_id, requested_selection);
        // Claude Code keys the reduce-capable variant on its acknowledgement contract. A
        // Broca session gets it whenever its tool array includes ctx_reduce, because the
        // transform tags that session's messages. OpenCode builds its own guidance.
        let active = cc_u1_active(profile, tool_present)
            || (matches!(profile, Some(SerializerProfile::OwnedBroca)) && tool_present);
        let expected_variant = if active { "full" } else { "no_reduce" };
        if let Some(variant) = request.get("variant").and_then(Value::as_str) {
            if variant != expected_variant {
                return HandlerOutcome::Error {
                    code: "bad_request".to_string(),
                    message: format!(
                        "guidance variant {variant:?} contradicts tool_present={tool_present}"
                    ),
                };
            }
        }
        let date_line = match self.guidance_date_for_session(&store, session_id) {
            Ok(date) => date,
            Err(error) => {
                return HandlerOutcome::Error {
                    code: "store_write_failed".to_string(),
                    message: error.to_string(),
                };
            }
        };
        let variant = if active {
            prompt_surface::GuidanceVariant::Full
        } else {
            prompt_surface::GuidanceVariant::NoReduce
        };
        let asset = prompt_surface::guidance_asset(selection.preset, variant);
        let base_text = selection
            .guidance_override
            .as_deref()
            .unwrap_or(asset.bytes);
        let language_text = request
            .get("language")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|language| !language.is_empty());
        let language_directive = language_text.and_then(primary_language_directive);
        let localized_text = language_directive
            .as_deref()
            .map(|directive| format!("{base_text}\n\n{directive}"));
        let text_for_bytes = localized_text.as_deref().unwrap_or(base_text);
        let bytes = guidance_bytes_for(text_for_bytes, &date_line);
        respond(json!({
            "ok": true,
            "bytes": bytes,
            "hash": sha256_hex(bytes.as_bytes()),
            // The date line changes every day, so content_hash excludes it. Include the
            // selected preset so a future missing-asset fallback cannot reuse the full hash.
            "content_hash": prompt_surface::guidance_content_hash(text_for_bytes, selection.preset),
            "preset": selection.preset.as_str(),
            "served_preset": if asset.fallback {
                "full"
            } else {
                selection.preset.as_str()
            },
            "preset_fallback": asset.fallback,
            "fallback_notice": asset.fallback.then_some(prompt_surface::LIGHT_FALLBACK_NOTICE),
            "manifest_content_epoch": prompt_surface::manifest_content_epoch(&selection),
            "manifest_preset_fallback": prompt_surface::tool_manifest_falls_back(selection.preset),
            "tool_manifest": prompt_surface::session_tools(&selection),
        }))
    }

    fn guidance_date_for_session(
        &self,
        store: &McStore,
        session_id: &str,
    ) -> Result<String, mc_store::McStoreError> {
        for _ in 0..2 {
            let loaded = store.load(session_id)?;
            if !loaded.meta.guidance_date.is_empty() {
                self.guidance_dates
                    .lock()
                    .expect("guidance date mutex")
                    .remove(session_id);
                return Ok(loaded.meta.guidance_date);
            }
            let date_line = self
                .guidance_dates
                .lock()
                .expect("guidance date mutex")
                .entry(session_id.to_string())
                .or_insert_with(|| self.guidance_date_line())
                .clone();
            let Some(expected) = loaded.row_version else {
                return Ok(date_line);
            };
            let mut meta = loaded.meta.clone();
            meta.guidance_date.clone_from(&date_line);
            match store.commit(session_id, Some(expected), &loaded.core, &meta) {
                Ok(_) => return Ok(date_line),
                Err(mc_store::McStoreError::CasConflict { .. }) => continue,
                Err(error) => return Err(error),
            }
        }
        Ok(self
            .guidance_dates
            .lock()
            .expect("guidance date mutex")
            .get(session_id)
            .cloned()
            .unwrap_or_else(|| self.guidance_date_line()))
    }

    fn memory_holder_metrics(&self) -> Value {
        let (snapshot_bytes, snapshot_count, in_flight_count, lease_bytes, lease_count) = {
            let snapshots = self
                .transform_snapshots
                .lock()
                .expect("transform snapshots mutex");
            let ready_count = snapshots
                .entries
                .values()
                .filter(|entry| matches!(entry, TransformSnapshot::Ready { .. }))
                .count();
            let in_flight_count = snapshots.entries.len().saturating_sub(ready_count);
            let leases = snapshots
                .active_leases
                .lock()
                .expect("snapshot lease budget mutex");
            (
                snapshots.ready_bytes,
                ready_count,
                in_flight_count,
                leases.bytes,
                leases.count,
            )
        };
        let (projection_bytes, projection_count) = {
            let cache = self.projections.lock().expect("projection cache mutex");
            (cache.retained_bytes, cache.sessions.len())
        };
        let (native_bytes, native_count) = {
            let cache = self
                .native_attachments
                .lock()
                .expect("native attachment cache mutex");
            (cache.retained_bytes, cache.sessions.len())
        };
        let (serialized_bytes, serialized_count) = self
            .serialized_outputs
            .lock()
            .expect("serialized output cache mutex")
            .metrics();
        let (tag_baseline_bytes, tag_baseline_count) = transform::tag_baseline_cache_metrics();
        let (boundary_bytes, boundary_count) = {
            let cache = self
                .boundary_tokens
                .lock()
                .expect("boundary token cache mutex");
            (cache.retained_bytes, cache.sessions.len())
        };
        let (
            page_bytes,
            page_count,
            completed_response_bytes,
            completed_response_count,
            collector_active,
            oldest_queued_at_ms,
        ) = {
            let pages = self.transform_pages.lock().expect("transform page mutex");
            let completed = pages
                .sessions
                .values()
                .filter_map(|session| session.completed.as_ref())
                .collect::<Vec<_>>();
            (
                pages.total_staged_bytes,
                pages.pending_transform_count,
                completed
                    .iter()
                    .map(|completed| completed.result.len())
                    .sum::<usize>(),
                completed.len(),
                pages
                    .sessions
                    .values()
                    .any(|session| matches!(&session.phase, TransformPagePhase::Collecting(_))),
                pages.oldest_queued_at_ms(),
            )
        };

        // Every byte/count field uses zero when that accounting domain is empty. `false` means no
        // page collector is in Collecting. `oldest_queued_at_ms` uses `null` for no collector, while
        // a numeric zero would mean the Unix epoch rather than absence.
        json!({
            "snapshots": {
                "charged_bytes": snapshot_bytes,
                "entry_count": snapshot_count,
                "in_flight_entry_count": in_flight_count,
                "active_lease_charged_bytes": lease_bytes,
                "active_lease_entry_count": lease_count,
            },
            "projections": {
                "charged_bytes": projection_bytes,
                "entry_count": projection_count,
            },
            "native_attach": {
                "charged_bytes": native_bytes,
                "entry_count": native_count,
            },
            "serialized_output": {
                "charged_bytes": serialized_bytes,
                "entry_count": serialized_count,
            },
            "tag_baseline": {
                "charged_bytes": tag_baseline_bytes,
                "entry_count": tag_baseline_count,
            },
            "boundary_token": {
                "charged_bytes": boundary_bytes,
                "entry_count": boundary_count,
            },
            "page_coordinator": {
                "charged_bytes": page_bytes,
                "entry_count": page_count,
                "completed_response_bytes": completed_response_bytes,
                "completed_response_count": completed_response_count,
                "collector_active": collector_active,
                "oldest_queued_at_ms": oldest_queued_at_ms,
            },
        })
    }

    fn handle_status_value(&self, request: &Value) -> HandlerOutcome {
        let store = match self.store.get() {
            Some(store) => Arc::clone(store),
            None => return self.store_refusal(),
        };
        let Some(session_id) = request.get("session_id").and_then(Value::as_str) else {
            if let Err(error) = self.observe_memory_mirror_frontier(&store) {
                return HandlerOutcome::Error {
                    code: "store_load_failed".to_string(),
                    message: error.to_string(),
                };
            }
            return match store.load("__health__") {
                Ok(state) => respond(json!({
                    "ok": true,
                    "store_open": true,
                    "initialized": state.meta.initialized,
                    "row_version": state.row_version,
                    "epochs": {
                        "memory_render_epoch": MEMORY_RENDER_FORMAT_EPOCH,
                        "compartment_render_epoch": COMPARTMENT_RENDER_FORMAT_EPOCH,
                        "profile_epoch": PROFILE_EPOCH_CLAUDE_CODE_ANTHROPIC,
                        "tagger_epoch": TAGGER_FEATURE_EPOCH,
                        "state_sync_deltas": true,
                        "state_sync_resume": true,
                    },
                    "storage_versions": storage_versions_block(&store),
                    "memory_holders": self.memory_holder_metrics(),
                    "memory_mirror": self.memory_mirror_status_value(now_ms().max(0) as u64),
                })),
                Err(e) => HandlerOutcome::Error {
                    code: "store_load_failed".to_string(),
                    message: e.to_string(),
                },
            };
        };
        let loaded = match store.load(session_id) {
            Ok(loaded) => loaded,
            Err(e) => {
                return HandlerOutcome::Error {
                    code: "store_load_failed".to_string(),
                    message: e.to_string(),
                };
            }
        };
        let pass_trace = match store.load_pass_trace(session_id) {
            Ok(pass_trace) => pass_trace,
            Err(e) => {
                return HandlerOutcome::Error {
                    code: "store_load_failed".to_string(),
                    message: e.to_string(),
                };
            }
        };
        let side_channel_status = match store.historian_side_channel_status(session_id) {
            Ok(status) => status,
            Err(e) => {
                return HandlerOutcome::Error {
                    code: "store_load_failed".to_string(),
                    message: e.to_string(),
                };
            }
        };
        let mut historian = json!(&loaded.meta.historian);
        let historian_fields = historian
            .as_object_mut()
            .expect("historian status serializes as an object");
        historian_fields.insert(
            "side_channel_pending_count".to_string(),
            json!(side_channel_status.pending_count),
        );
        historian_fields.insert(
            "side_channel_last_failure".to_string(),
            json!(side_channel_status.last_failure),
        );
        respond(json!({
            "ok": true,
            "store_open": true,
            "session_id": session_id,
            "initialized": loaded.meta.initialized,
            "row_version": loaded.row_version,
            "historian": historian,
            "publication_floor_ordinal": loaded.meta.publication_floor_ordinal,
            "raw_passthrough": raw_passthrough_status(&loaded),
            "tail_identity_re_adopt_count": loaded.meta.tail_identity_re_adopt_count,
            "pass_trace": pass_trace,
            "runtime_store_error": self.runtime_store_error_value(session_id),
            "epochs": {
                "memory_render_epoch": MEMORY_RENDER_FORMAT_EPOCH,
                "compartment_render_epoch": COMPARTMENT_RENDER_FORMAT_EPOCH,
                "profile_epoch": PROFILE_EPOCH_CLAUDE_CODE_ANTHROPIC,
                "tagger_epoch": TAGGER_FEATURE_EPOCH,
                "state_sync_deltas": true,
                "state_sync_resume": true,
            },
            "storage_versions": storage_versions_block(&store),
        }))
    }

    async fn handle_transform_dispatch(
        &self,
        channel: u16,
        request: Value,
        inbound_bytes: Option<usize>,
    ) -> HandlerOutcome {
        let ticket = TransformDispatchTicket::new(&DISPATCH_HEALTH, channel);
        let outcome = if has_transform_page_fields(&request) {
            self.handle_transform_page_value(channel, request, TransformLane::Authority, &ticket)
                .await
        } else {
            self.handle_transform_value(channel, request, inbound_bytes, &ticket)
                .await
        };
        ticket.finish(matches!(outcome, HandlerOutcome::Error { .. }));
        outcome
    }

    async fn handle_transform_value(
        &self,
        channel: u16,
        request: Value,
        inbound_bytes: Option<usize>,
        ticket: &TransformDispatchTicket<'_>,
    ) -> HandlerOutcome {
        self.handle_transform_unpaged_value(channel, request, false, inbound_bytes, ticket)
            .await
    }

    async fn handle_transform_unpaged_value(
        &self,
        channel: u16,
        request: Value,
        from_page_apply: bool,
        _inbound_bytes: Option<usize>,
        ticket: &TransformDispatchTicket<'_>,
    ) -> HandlerOutcome {
        let handler_started_at = Instant::now();
        let request_decode_started_at = Instant::now();
        let mut delta_expand_ms = 0.0;
        const REQUEST_OBSERVED_KEY: &str = "request_observed_at_ms";
        let request_attempt_id = request
            .get("attempt_id")
            .and_then(Value::as_str)
            .filter(|attempt_id| !attempt_id.is_empty())
            .map(|attempt_id| attempt_id.chars().take(128).collect::<String>())
            .unwrap_or_else(|| {
                format!(
                    "legacy-{}-{}",
                    request
                        .get(REQUEST_OBSERVED_KEY)
                        .and_then(Value::as_u64)
                        .unwrap_or_default(),
                    request
                        .get("full_array_fingerprint")
                        .and_then(Value::as_str)
                        .unwrap_or("unknown")
                )
            });
        let request_observed_to_handler = request
            .get(REQUEST_OBSERVED_KEY)
            .and_then(Value::as_u64)
            .and_then(|observed| i64::try_from(observed).ok())
            .map(|observed| now_ms().saturating_sub(observed) as f64)
            .unwrap_or(0.0);
        let todo_verdict_probed = request.get("todo_verdict_probed").and_then(Value::as_bool);
        let mut parsed: TransformRequest = match serde_json::from_value(request) {
            Ok(req) => req,
            Err(e) => {
                return HandlerOutcome::Error {
                    code: "bad_request".to_string(),
                    message: e.to_string(),
                };
            }
        };
        let request_decode_ms = request_decode_started_at.elapsed().as_secs_f64() * 1_000.0;
        let handler_prepare_started_at = Instant::now();
        let serializer_profile = SerializerProfile::parse(&parsed.serializer_profile);
        if serializer_profile.is_none() {
            return unknown_serializer_profile_error();
        }
        if parsed.serve_native && serializer_profile != Some(SerializerProfile::OpencodeAiSdk) {
            return serve_native_unsupported_profile_error(&parsed.serializer_profile);
        }
        // The module's own producer sessions must NEVER be transformed: the historian's
        // request is a raw structured-extraction call whose [system, user] shape is part
        // of the prompt calibration. Identity pass-through, no store reads, no historian
        // evaluation (a transform here would recurse the historian into itself).
        if parsed
            .session_id
            .starts_with(historian::MC_CHILD_SESSION_PREFIX)
        {
            // The established historian namespace remains accepted for compatibility with
            // existing producer sessions. Dreamer IDs instead require registration and route
            // validation before they may bypass the transform.
            if parsed.tail_delta.is_some() {
                return need_full_sync_response(&parsed);
            }
            ticket.accept();
            return passthrough_transform_response(&parsed);
        }
        if self.dreamer_run_registered(&parsed.session_id) {
            // Registration is the authority for a dreamer exemption. Validate the route
            // before trusting it so a stale or cross-project channel cannot bypass transform.
            match self.resolve_binding(channel, &parsed.session_id) {
                Ok(_) => {
                    if parsed.tail_delta.is_some() {
                        return need_full_sync_response(&parsed);
                    }
                    ticket.accept();
                    return passthrough_transform_response(&parsed);
                }
                Err(BindingError::Unbound) => {
                    return HandlerOutcome::Error {
                        code: "route_unbound".to_string(),
                        message: "registered dreamer session has no bound route".to_string(),
                    };
                }
                Err(BindingError::SessionMismatch) => {
                    return HandlerOutcome::Error {
                        code: "session_mismatch".to_string(),
                        message: "registered dreamer session does not match the bound route"
                            .to_string(),
                    };
                }
            }
        }
        #[cfg(feature = "drive-fault")]
        if maybe_apply_transform_timeout_fault().await {
            return HandlerOutcome::Error {
                code: "drive_transform_timeout".to_string(),
                message: "drive fault stalled this transform before execution".to_string(),
            };
        }
        let store = match self.store_for_request().await {
            Ok(store) => store,
            Err(refusal) => return refusal.into_outcome(),
        };
        let binding = match self.resolve_binding(channel, &parsed.session_id) {
            Ok(b) => b,
            Err(BindingError::Unbound) => {
                return HandlerOutcome::Error {
                    code: "route_unbound".to_string(),
                    message: "transform on a channel with no session binding".to_string(),
                };
            }
            Err(BindingError::SessionMismatch) => {
                return HandlerOutcome::Error {
                    code: "session_mismatch".to_string(),
                    message: "request session_id does not match the channel's bound session"
                        .to_string(),
                };
            }
        };
        let pass_now = now_ms();
        let trace_received_started_at = Instant::now();
        let _ = store.trace_pass_received(&parsed.session_id, &request_attempt_id, pass_now);
        let trace_received_ms = trace_received_started_at.elapsed().as_secs_f64() * 1_000.0;
        apply_claude_code_config_controls(&mut parsed, &binding.config, serializer_profile);
        parsed
            .prompt_surface_tool_descriptions
            .retain(|tool_id, _| {
                if prompt_surface::is_known_tool_id(tool_id) {
                    true
                } else {
                    prompt_surface::warn_ignored_unknown_tool_description(tool_id);
                    false
                }
            });
        for (tool_id, description) in &parsed.prompt_surface_tool_descriptions {
            if description.trim().is_empty() {
                return invalid_params_error(format!(
                    "prompt_surface tool_descriptions.{tool_id} must not be empty"
                ));
            }
        }
        let requested_prompt_surface = PromptSurfaceSelection {
            model_key: parsed
                .prompt_surface_model_key
                .clone()
                .or_else(|| parsed.model_key.clone()),
            config_identity: parsed.prompt_surface_config_identity.clone(),
            preset: parsed.prompt_surface_preset,
            guidance_override: parsed.prompt_surface_guidance_override.clone(),
            tool_descriptions: parsed.prompt_surface_tool_descriptions.clone(),
        };
        let frozen_prompt_surface =
            self.freeze_prompt_surface_selection(&parsed.session_id, requested_prompt_surface);
        parsed.prompt_surface_preset = frozen_prompt_surface.preset;
        parsed.prompt_surface_model_key = frozen_prompt_surface.model_key;
        parsed.prompt_surface_config_identity = frozen_prompt_surface.config_identity;
        parsed.prompt_surface_guidance_override = frozen_prompt_surface.guidance_override;
        parsed.prompt_surface_tool_descriptions = frozen_prompt_surface.tool_descriptions;

        let lineage_root = canonical_root(&binding.project_root);
        self.transform_route_channels
            .lock()
            .expect("transform route channels mutex")
            .insert(channel, (binding.session.clone(), lineage_root.clone()));
        self.transform_session_roots
            .lock()
            .expect("transform session roots mutex")
            .entry(binding.session.clone())
            .or_default()
            .insert(lineage_root);
        let native_delta_frontier = if parsed.tail_delta.is_some() {
            let delta_expand_started_at = Instant::now();
            let expanded = self.expand_transform_tail_delta(&mut parsed);
            delta_expand_ms = delta_expand_started_at.elapsed().as_secs_f64() * 1_000.0;
            let Some(frontier) = expanded else {
                return need_full_sync_response(&parsed);
            };
            Some(frontier)
        } else {
            None
        };
        if !from_page_apply && self.transform_page_in_progress(&binding.session) {
            return HandlerOutcome::Error {
                code: "authority_transform_page_in_progress".to_string(),
                message: "transform is blocked until all transform pages arrive".to_string(),
            };
        }
        ticket.accept();
        // A newer full transform invalidates the prior wrapup snapshot before any store
        // mutation. If this pass later rejects, wrapup must not pair old raw bytes with
        // the state that the rejected pass may already have re-cut.
        let snapshot_generation = self
            .transform_snapshots
            .lock()
            .expect("transform snapshots mutex")
            .begin(&parsed.session_id);
        let route_project_root = binding.project_root.to_string_lossy().to_string();
        // Resolve the route root to the memory and note owner keys before any store read.
        // Keep the filesystem directory only for project documents and configuration below.
        let project_path = match store.authority_project_for_route(&route_project_root, "memories")
        {
            Ok(Some(project)) => project,
            Ok(None) => route_project_root.clone(),
            Err(error) => {
                return HandlerOutcome::Error {
                    code: "authority_project_resolution_failed".to_string(),
                    message: error.to_string(),
                };
            }
        };
        let note_project_path =
            match store.authority_project_for_route(&route_project_root, "notes") {
                Ok(Some(project)) => project,
                Ok(None) => route_project_root.clone(),
                Err(error) => {
                    return HandlerOutcome::Error {
                        code: "authority_project_resolution_failed".to_string(),
                        message: error.to_string(),
                    };
                }
            };
        match serializer_profile {
            Some(SerializerProfile::OpencodeAiSdk) => {
                if let Some((data_url, content_hash)) = host_mural_artifact(parsed.mural.as_ref()) {
                    if let Err(error) = store.upsert_project_mural_artifact(
                        &project_path,
                        data_url.as_bytes(),
                        &content_hash,
                        pass_now,
                    ) {
                        return HandlerOutcome::Error {
                            code: "mural_artifact_store_failed".to_string(),
                            message: error.to_string(),
                        };
                    }
                }
            }
            Some(SerializerProfile::ClaudeCodeAnthropic) => {
                match cc_mural_input(&store, &project_path) {
                    Ok(mural) => {
                        // The mural renderer is host-side by design. CC inherits the last OC artifact
                        // for this project and never renders or trusts a request-supplied mural itself.
                        // A CC-only project has no artifact, so it correctly composes without a mural.
                        parsed.mural = mural;
                    }
                    Err(error) => {
                        return HandlerOutcome::Error {
                            code: "mural_artifact_store_failed".to_string(),
                            message: error.to_string(),
                        };
                    }
                }
            }
            _ => {}
        }
        let parsed = Arc::new(parsed);
        let projection_cache_lookup_started_at = Instant::now();
        let projection_cache_input = native_delta_frontier
            .as_ref()
            .and_then(|frontier| frontier.projection_cache.clone())
            .or_else(|| self.lookup_full_projection_cache(&parsed));
        let projection_cache_lookup_ms =
            projection_cache_lookup_started_at.elapsed().as_secs_f64() * 1_000.0;
        // A previous publish may have committed while one independent side channel failed.
        // Retry on normal traffic rather than creating another background timer.
        let side_channel_drain_started_at = Instant::now();
        let _ = store.drain_historian_side_channels(
            &parsed.session_id,
            pass_now,
            HISTORIAN_SIDE_CHANNEL_DRAIN_PER_KIND,
        );
        let side_channel_drain_ms = side_channel_drain_started_at.elapsed().as_secs_f64() * 1_000.0;
        let hostless_usable_soft = parsed
            .geometry
            .as_ref()
            .map(|geometry| geometry.usable_soft)
            .or_else(|| {
                parsed
                    .usage
                    .as_ref()
                    .map(|usage| usage.context_limit_tokens)
                    .filter(|limit| *limit >= scheduler::MIN_PLAUSIBLE_CONTEXT_LIMIT)
            })
            .unwrap_or(200_000);
        let resolved_protected_tokens = binding
            .config
            .resolve_protected_tokens(hostless_usable_soft);
        // Bind frames have no model identity. Emit resolved policy once on the first transform for
        // this binding, when the host's model and optional overrides are available.
        if self
            .threshold_logged_routes
            .lock()
            .expect("threshold log mutex")
            .insert(channel)
        {
            let resolved = binding
                .config
                .resolve_execute_threshold(parsed.model_key.as_deref());
            tracing::debug!(
                "mc-module: execute_threshold channel={channel} model={} configured={} provenance={} effective={} source={}",
                parsed.model_key.as_deref().unwrap_or("default"),
                resolved.percentage,
                resolved.provenance,
                parsed.execute_threshold_or(resolved.percentage),
                if parsed.effective_execute_threshold.is_some() { "host" } else { "config" },
            );
            if let Some(warning) = &resolved_protected_tokens.warning {
                tracing::warn!("mc-module: config warning: {warning}");
            }
            tracing::debug!(
                "mc-module: protected_tokens channel={channel} provenance={} effective={} source={}",
                resolved_protected_tokens.provenance,
                parsed
                    .protected_tokens_effective
                    .unwrap_or(resolved_protected_tokens.floor),
                if parsed.protected_tokens_effective.is_some() {
                    "host"
                } else {
                    "config"
                },
            );
        }
        // Scheduler anchoring and durable historian activity read one lazy state snapshot for this
        // handler entry. The snapshot is initialized only if neither in-memory fast path answers.
        let handler_entry_state = OnceLock::new();
        let run_transform = || {
            let resolved_cache_ttl = parsed.cache_ttl.clone().map_or_else(
                || {
                    binding
                        .config
                        .resolve_cache_ttl_with_provenance(parsed.model_key.as_deref())
                },
                |value| config::ResolvedCacheTtl {
                    value,
                    // Host-resolved TTLs remain host-side; only a per-model config match may
                    // instruct the Claude Code marker owner.
                    provenance: config::CacheTtlProvenance::Default,
                },
            );
            let producer_ctx = transform::ProducerContext {
                project_path: &project_path,
                note_project_path: &note_project_path,
                project_directory: &route_project_root,
                // The authority adapter resolves this from the model context limit and
                // sends it on each pass. Keep the bind-time value only for older callers
                // that omit the field, and reject unusable values without disabling decay.
                history_budget_tokens: parsed
                    .history_budget_tokens
                    .filter(|budget| budget.is_finite() && *budget >= 0.0)
                    .unwrap_or(binding.history_budget_tokens),
                memory_enabled: binding.config.memory_enabled,
                inject_docs: binding.config.inject_docs,
                temporal_awareness: binding.config.temporal_awareness,
                memory_budget_tokens: binding.config.memory_budget_tokens,
                user_profile_budget_tokens: binding.config.user_profile_budget_tokens,
                now_ms: pass_now,
                // The host resolves per-model/token thresholds against this pass's usable window.
                // Without a host override, resolve the bind-time config using this request's model.
                execute_threshold_percentage: parsed.execute_threshold_or(
                    binding
                        .config
                        .resolve_execute_threshold(parsed.model_key.as_deref())
                        .percentage,
                ),
                protected_tokens_floor: resolved_protected_tokens.floor,
                protected_tokens_provenance: if resolved_protected_tokens.provenance == "derived" {
                    "derived"
                } else {
                    "absolute"
                },
                // Route-bound configuration selects either the full pipeline or the
                // additive-only memory/docs transform for every consumer profile.
                compaction_enabled: binding.config.compaction_enabled,
                smart_drops: binding.config.smart_drops,
                // OpenCode/Pi send their host-resolved value. Claude Code omits it, so resolve the
                // request's model while retaining whether the walk actually matched an entry.
                cache_ttl: resolved_cache_ttl.value,
                cache_ttl_provenance: resolved_cache_ttl.provenance,
                model_key: binding.model_key.clone(),
                observed_last_response_at_ms: self.observed_last_response_at_ms(
                    &store,
                    &parsed.session_id,
                    &handler_entry_state,
                ),
                guidance_date: Some(self.guidance_date_for_transform(&parsed.session_id, pass_now)),
                historian_active: self.historian_active(
                    &store,
                    &parsed.session_id,
                    &handler_entry_state,
                ),
                wrapup_active: self.wrapup_active(&parsed.session_id),
                #[cfg(test)]
                injected_reductions: self
                    .reduction_injection
                    .lock()
                    .expect("reduction injection mutex")
                    .remove(&parsed.session_id)
                    .unwrap_or_default(),
            };
            transform_with_projection_cached(
                &store,
                &parsed,
                &producer_ctx,
                &self.serialized_outputs,
                projection_cache_input.as_ref(),
            )
        };
        let reject_transform = |e: crate::transform::TransformError| {
            let code = if matches!(e, crate::transform::TransformError::AssistantTerminalRetry) {
                "assistant_terminal_retry"
            } else {
                "transform_failed"
            };
            let message = e.to_string();
            if matches!(&e, crate::transform::TransformError::Store(_)) {
                self.runtime_store_errors
                    .lock()
                    .expect("runtime store errors mutex")
                    .insert(
                        parsed.session_id.clone(),
                        RuntimeStoreError {
                            code: code.to_string(),
                            message: message.clone(),
                            at_ms: now_ms(),
                        },
                    );
            }
            let _ = store.trace_pass_rejected(
                &parsed.session_id,
                &request_attempt_id,
                &message,
                now_ms(),
            );
            HandlerOutcome::Error {
                code: code.to_string(),
                message,
            }
        };
        let handler_prepare_ms = handler_prepare_started_at.elapsed().as_secs_f64() * 1_000.0;
        let transform_execute_started_at = Instant::now();
        let mut result = match run_transform() {
            Ok(result) => {
                self.runtime_store_errors
                    .lock()
                    .expect("runtime store errors mutex")
                    .remove(&parsed.session_id);
                result
            }
            Err(e) => return reject_transform(e),
        };
        let transform_execute_ms = transform_execute_started_at.elapsed().as_secs_f64() * 1_000.0;
        let handler_followup_started_at = Instant::now();
        let mut emergency_pre_floor = (result.scheduler_pass
            == scheduler::PassDecision::Emergency95)
            .then_some(result.publication_floor_ordinal)
            .flatten();
        #[cfg(test)]
        if let Some(hook) = self
            .between_transform_and_prepare
            .lock()
            .expect("interleave hook mutex")
            .take()
        {
            hook();
        }
        let transform_followup_deadline =
            handler_started_at + self.transform_historian_followup_budget();
        let remaining_followup_budget = || {
            transform_followup_deadline
                .checked_duration_since(Instant::now())
                .unwrap_or(Duration::ZERO)
        };
        let mut trigger_timings = HistorianTriggerTimings::default();
        // Serve-then-fold. The emergency pass joins the fold inline only when this
        // module runs the completion itself. Under the host runner the completion is
        // made in another process, where it legitimately takes minutes; holding an
        // emergency pass open for it would block the request the user is waiting on
        // behind a background fold, and would make the hidden child's own context
        // hook dispatch while its parent transform is still blocked. The emergency
        // reduction this pass already computed is served instead, and the fold lands
        // on a later pass. What that costs is real and is accounted rather than
        // hidden: the tiered drops the emergency output makes are permanent, and the
        // fold's arrival pays for a second prefix rewrite.
        //
        // Resolved from the same place the firing itself resolves its runner
        // (`prepare_historian_fire`), not from the route's bind-time copy: a pass
        // that decided to wait inline while the firing went to the host would wait
        // for a completion that was never going to arrive in this process. Only an
        // emergency pass asks, so the ordinary pass pays nothing for it.
        let serve_then_fold = result.scheduler_pass == scheduler::PassDecision::Emergency95
            && self
                .effective_config(&binding.project_root)
                .historian_runner
                == HistorianRunnerKind::Host;
        let diagnostics = if parsed.is_subagent {
            historian_no_fire_diagnostics(NoFireDiagnosticsInput {
                no_fire: "subagent_session".into(),
                detail_kind: "subagent_session",
                cause: HistorianNoFireCause::SubagentSession,
                extra: None,
                reason: Some("subagent_session".to_string()),
                state: "disabled".to_string(),
                progress: None,
                last_failure: None,
            })
        } else if result.scheduler_pass == scheduler::PassDecision::Emergency95 && !serve_then_fold
        {
            match self.prepare_historian_fire(
                Arc::clone(&store),
                &parsed,
                &binding,
                &project_path,
                &result.projection,
                HistorianPrepareContext {
                    now: pass_now,
                    snapshot_generation,
                    tag_snapshot: result.historian_tags.clone(),
                    reclaim_ride_available: result.reclaim_ride_available,
                    timings: &mut trigger_timings,
                },
            ) {
                PreparedHistorianAction::Complete(diagnostics) => diagnostics,
                PreparedHistorianAction::Busy {
                    diagnostics,
                    completion,
                } => {
                    if self
                        .await_live_historian_completion(
                            &parsed.session_id,
                            completion,
                            remaining_followup_budget(),
                        )
                        .await
                    {
                        result = match run_transform() {
                            Ok(result) => result,
                            Err(e) => return reject_transform(e),
                        };
                        emergency_pre_floor = result.publication_floor_ordinal;
                        match self.prepare_historian_fire(
                            Arc::clone(&store),
                            &parsed,
                            &binding,
                            &project_path,
                            &result.projection,
                            HistorianPrepareContext {
                                now: pass_now,
                                snapshot_generation,
                                tag_snapshot: result.historian_tags.clone(),
                                reclaim_ride_available: result.reclaim_ride_available,
                                timings: &mut trigger_timings,
                            },
                        ) {
                            PreparedHistorianAction::Complete(diagnostics) => diagnostics,
                            PreparedHistorianAction::Busy { diagnostics, .. } => diagnostics,
                            PreparedHistorianAction::FireReady(prepared) => {
                                let diagnostics = prepared.diagnostics.clone();
                                match self
                                    .run_historian_firing_inline(
                                        &parsed.session_id,
                                        prepared.task,
                                        remaining_followup_budget(),
                                    )
                                    .await
                                {
                                    Ok(_) => {
                                        result = match run_transform() {
                                            Ok(result) => result,
                                            Err(e) => return reject_transform(e),
                                        };
                                        emergency_pre_floor = result.publication_floor_ordinal;
                                        diagnostics
                                    }
                                    Err(_) => self.refresh_historian_diagnostics(
                                        &store,
                                        &parsed.session_id,
                                        diagnostics,
                                    ),
                                }
                            }
                        }
                    } else {
                        diagnostics
                    }
                }
                PreparedHistorianAction::FireReady(prepared) => {
                    let diagnostics = prepared.diagnostics.clone();
                    match self
                        .run_historian_firing_inline(
                            &parsed.session_id,
                            prepared.task,
                            remaining_followup_budget(),
                        )
                        .await
                    {
                        Ok(_) => {
                            result = match run_transform() {
                                Ok(result) => result,
                                Err(e) => return reject_transform(e),
                            };
                            emergency_pre_floor = result.publication_floor_ordinal;
                            diagnostics
                        }
                        Err(_) => self.refresh_historian_diagnostics(
                            &store,
                            &parsed.session_id,
                            diagnostics,
                        ),
                    }
                }
            }
        } else {
            match self.prepare_historian_fire(
                Arc::clone(&store),
                &parsed,
                &binding,
                &project_path,
                &result.projection,
                HistorianPrepareContext {
                    now: pass_now,
                    snapshot_generation,
                    tag_snapshot: result.historian_tags.clone(),
                    reclaim_ride_available: result.reclaim_ride_available,
                    timings: &mut trigger_timings,
                },
            ) {
                PreparedHistorianAction::Complete(diagnostics) => diagnostics,
                PreparedHistorianAction::Busy { diagnostics, .. } => diagnostics,
                PreparedHistorianAction::FireReady(prepared) => {
                    let diagnostics = prepared.diagnostics.clone();
                    self.spawn_historian_firing(prepared.task);
                    diagnostics
                }
            }
        };
        // Emergency passes must return the freshest fold obtainable in this request: an
        // active run can publish between this request's transform and any of the arms
        // above (live entry already released, inline attempt failed, busy wait timed
        // out). One final check catches every such interleaving — a PUBLISH is the only
        // event that advances the publication floor (an abandon also bumps the row
        // version, so row advancement alone would re-run spuriously after a failed
        // inline drive); if the floor moved past what this request's transform saw,
        // re-run once so the response carries the published fold instead of pre-fold
        // bytes.
        if !parsed.is_subagent && result.scheduler_pass == scheduler::PassDecision::Emergency95 {
            let floor_advanced = store
                .load(&parsed.session_id)
                .map(|state| state.meta.publication_floor_ordinal != emergency_pre_floor)
                .unwrap_or(false);
            if floor_advanced {
                result = match run_transform() {
                    Ok(result) => result,
                    Err(e) => return reject_transform(e),
                };
            }
        }
        let handler_followup_ms = handler_followup_started_at.elapsed().as_secs_f64() * 1_000.0;
        let post_attach_started_at = Instant::now();
        let revert_epoch = result.revert_epoch;
        let reasoning_clear_units = &result.reasoning_clear_units;
        let transition_consumed = result.transition_consumed;
        let mutation_exempt_mid = result.mutation_exempt_mid;
        let lineage_anchor_mid = result.lineage_anchor_mid;
        let tag_numbers = result.tag_numbers;
        let projection = Arc::new(result.projection);
        let projection_cache_store_started_at = Instant::now();
        let request_message_charge = self.store_projection_cache(
            &parsed,
            revert_epoch,
            Arc::clone(&projection),
            native_delta_frontier
                .as_ref()
                .and_then(|frontier| frontier.projection_cache.as_ref()),
        );
        let projection_cache_store_ms =
            projection_cache_store_started_at.elapsed().as_secs_f64() * 1_000.0;
        let mut response = result.response;
        if unprobed_todo_bust(todo_verdict_probed, &response.decision) {
            // A local host predictor can miss module-owned repair decisions. Report
            // every unprobed bust, even when no todo pair was emitted, so a stale
            // permission verdict can never be consumed without an audit signal.
            self.log_unprobed_todo_bust(
                &parsed.session_id,
                parsed.todo_tool_present == Some(true),
                &response.decision,
                response.materialize_reason.as_deref().unwrap_or("unknown"),
            );
        }
        if response.committed {
            self.guidance_dates
                .lock()
                .expect("guidance date mutex")
                .remove(&parsed.session_id);
        }
        response.historian = Some(diagnostics);
        let native_attach_started_at = Instant::now();
        let native_cache_stats = if parsed.serve_native {
            attach_native_messages_incremental(
                &mut response,
                &parsed,
                reasoning_clear_units,
                &tag_numbers,
                mutation_exempt_mid.as_deref(),
                lineage_anchor_mid.as_deref(),
                transition_consumed,
                native_delta_frontier.as_ref(),
                revert_epoch,
                &self.native_attachments,
                NativeCacheKeyMode::Normal,
            )
        } else {
            NativeAttachmentCacheStats::default()
        };
        if let Err(error) = record_reasoning_native_evidence(
            &store,
            &mut response,
            &parsed,
            reasoning_clear_units,
            &tag_numbers,
            mutation_exempt_mid.as_deref(),
            lineage_anchor_mid.as_deref(),
            transition_consumed,
        ) {
            tracing::error!("mc-module: native reasoning replay proof not recorded: {error}");
        }
        finalize_native_messages_response(
            &mut response,
            &parsed,
            reasoning_clear_units,
            &tag_numbers,
            mutation_exempt_mid.as_deref(),
            lineage_anchor_mid.as_deref(),
            transition_consumed,
            native_delta_frontier.as_ref(),
            native_cache_stats,
        );
        let native_attach_ms = native_attach_started_at.elapsed().as_secs_f64() * 1_000.0;
        let trace_complete_started_at = Instant::now();
        let _ = store.trace_pass_completed(&parsed.session_id, &request_attempt_id, now_ms());
        let trace_complete_ms = trace_complete_started_at.elapsed().as_secs_f64() * 1_000.0;
        let response_observation_started_at = Instant::now();
        self.record_response_observation(&parsed.session_id, now_ms());
        let response_observation_ms =
            response_observation_started_at.elapsed().as_secs_f64() * 1_000.0;
        // Tail deltas have already been expanded at this point. Charge the retained request tree,
        // not the much smaller inbound suffix, so the ready LRU and active-lease budget describe
        // the same object their `Arc`s keep alive.
        let retained_size_started_at = Instant::now();
        let retained_bytes = parsed.retained_bytes_with_charges(
            (native_cache_stats.request_native_retained_bytes > 0)
                .then_some(native_cache_stats.request_native_retained_bytes),
            Some(request_message_charge),
        );
        let retained_size_ms = retained_size_started_at.elapsed().as_secs_f64() * 1_000.0;
        let snapshot_store_started_at = Instant::now();
        self.transform_snapshots
            .lock()
            .expect("transform snapshots mutex")
            .finish_ready(
                &parsed.session_id,
                snapshot_generation,
                Arc::clone(&parsed),
                revert_epoch,
                retained_bytes,
            );
        let snapshot_store_ms = snapshot_store_started_at.elapsed().as_secs_f64() * 1_000.0;
        match self.observe_memory_mirror_frontier(&store) {
            Ok(feed_head) => response.memory_mirror_head = Some(feed_head),
            Err(error) => {
                tracing::error!("mc-module: memory mirror frontier probe failed: {error}");
            }
        }
        if let Some(timings) = response.timings.as_mut() {
            timings.handler_total = handler_started_at.elapsed().as_secs_f64() * 1_000.0;
            timings.request_decode = request_decode_ms;
            timings.handler_prepare = handler_prepare_ms;
            timings.transform_execute = transform_execute_ms;
            timings.handler_followup = handler_followup_ms;
            timings.request_observed_to_handler = request_observed_to_handler;
            timings.delta_expand = delta_expand_ms;
            timings.side_channel_drain = side_channel_drain_ms;
            timings.trace_received = trace_received_ms;
            timings.projection_cache_lookup = projection_cache_lookup_ms;
            timings.projection_cache_store = projection_cache_store_ms;
            timings.native_attach = native_attach_ms;
            timings.trace_complete = trace_complete_ms;
            timings.response_observation = response_observation_ms;
            timings.retained_size = retained_size_ms;
            timings.snapshot_store = snapshot_store_ms;
            timings.trigger_ms = trigger_timings.elapsed_ms;
            timings.trigger_boundary_build = trigger_timings.boundary_build_ms;
            timings.trigger_eval = trigger_timings.trigger_eval_ms;
            timings.trigger_cache_store = trigger_timings.cache_store_ms;
            timings.trigger_token_cache_hits = trigger_timings.token_cache_hits;
            timings.trigger_tokenized_blocks = trigger_timings.tokenized_blocks;
            timings.native_cache_reused_messages = native_cache_stats.reused_messages;
            timings.native_cache_encoded_messages = native_cache_stats.encoded_messages;
            timings.native_cache_refused_store = native_cache_stats.refused_store;
            timings.native_cache_degraded_store = native_cache_stats.degraded_store;
            timings.native_cache_evicted = native_cache_stats.evicted;
            timings.native_cache_reencode_drift = native_cache_stats.reencode_drift;
            timings.post_attach = post_attach_started_at.elapsed().as_secs_f64() * 1_000.0;
        }
        respond_transform(&parsed, response)
    }

    fn state_sync_seed_now(&self) -> Instant {
        #[cfg(test)]
        if let Some(now) = *self
            .state_sync_seed_now
            .lock()
            .expect("state sync seed clock mutex")
        {
            return now;
        }
        Instant::now()
    }

    #[cfg(test)]
    async fn handle_transform_for_test(&self, channel: u16, request: Value) -> HandlerOutcome {
        let inbound_bytes = serde_json::to_vec(&request)
            .map(|bytes| bytes.len())
            .unwrap_or(MAX_TRANSFORM_FRAME_BYTES);
        self.handle_transform_dispatch(channel, request, Some(inbound_bytes))
            .await
    }

    #[cfg(test)]
    async fn handle_transform_for_test_with_body_size(
        &self,
        channel: u16,
        request: Value,
        inbound_bytes: usize,
    ) -> HandlerOutcome {
        self.handle_transform_dispatch(channel, request, Some(inbound_bytes))
            .await
    }

    fn handle_state_sync_value(&self, channel: u16, request: Value) -> HandlerOutcome {
        let started = Instant::now();
        let mut timing = state_sync_timing::StateSyncTiming {
            session: request
                .get("session_id")
                .and_then(Value::as_str)
                .unwrap_or("bound")
                .to_string(),
            page: request
                .get("seed_batch_index")
                .and_then(Value::as_u64)
                .unwrap_or(0),
            pages: request
                .get("seed_batch_total")
                .and_then(Value::as_u64)
                .unwrap_or(1),
            compartments: request
                .get("compartments")
                .and_then(Value::as_array)
                .map_or(0, Vec::len),
            tags: request
                .get("drop_seeds")
                .and_then(Value::as_array)
                .map_or(0, Vec::len),
            bytes: 0,
            decode_ms: 0.0,
            stage_page_ms: 0.0,
            assemble_series_ms: 0.0,
            import_ms: 0.0,
            ack_started: None,
        };
        const ENVELOPE_FIELDS: [&str; 5] = [
            "seed_id",
            "seed_generation",
            "seed_batch_index",
            "seed_batch_total",
            "seed_complete",
        ];
        let envelope_fields_present = ENVELOPE_FIELDS
            .iter()
            .filter(|field| request.get(**field).is_some())
            .count();
        let parsed: ModuleStateSyncWire = match serde_json::from_value(request.clone()) {
            Ok(req) => req,
            Err(error) => {
                if envelope_fields_present > 0 {
                    if let Ok(binding) = self.state_sync_binding(channel, None) {
                        self.discard_state_sync_seed(&binding.session);
                    }
                }
                return invalid_params_error(error.to_string());
            }
        };
        timing.decode_ms = started.elapsed().as_secs_f64() * 1000.0;
        let staging_started = Instant::now();
        let binding = match self.state_sync_binding(channel, parsed.session_id.as_deref()) {
            Ok(binding) => binding,
            Err(outcome) => return outcome,
        };
        timing.session = binding.session.clone();
        let store = match self.store.get() {
            Some(store) => Arc::clone(store),
            None => return self.store_refusal(),
        };

        if envelope_fields_present == 0 {
            let awaiting_attempt = {
                let seeds = self.state_sync_seeds.lock().expect("state sync seed mutex");
                match seeds
                    .sessions
                    .get(&binding.session)
                    .map(|state| &state.phase)
                {
                    Some(
                        StateSyncSeedPhase::Collecting(_) | StateSyncSeedPhase::Applying { .. },
                    ) => {
                        return HandlerOutcome::Error {
                            code: "state_sync_seed_in_progress".to_string(),
                            message: "a paged state-sync seed is already in progress".to_string(),
                        };
                    }
                    Some(StateSyncSeedPhase::AwaitingSeed {
                        generation,
                        expected_seq,
                    }) => Some((*generation, *expected_seq)),
                    Some(StateSyncSeedPhase::Idle) | None => None,
                }
            };
            timing.bytes = serde_json::to_vec(&request).map_or(0, |bytes| bytes.len());
            timing.stage_page_ms = staging_started.elapsed().as_secs_f64() * 1000.0;
            let import_started = Instant::now();
            let outcome = self.apply_state_sync_wire(&binding, &store, parsed);
            timing.import_ms = import_started.elapsed().as_secs_f64() * 1000.0;
            timing.ack_started = Some(Instant::now());
            if let Some((generation, expected_seq)) = awaiting_attempt {
                let mut seeds = self.state_sync_seeds.lock().expect("state sync seed mutex");
                let still_same_attempt =
                    seeds.sessions.get(&binding.session).is_some_and(|state| {
                        matches!(
                            state.phase,
                            StateSyncSeedPhase::AwaitingSeed {
                                generation: current_generation,
                                expected_seq: current_seq,
                            } if current_generation == generation && current_seq == expected_seq
                        )
                    });
                if still_same_attempt {
                    seeds.discard_pending(&binding.session);
                }
            }
            return outcome;
        }

        if envelope_fields_present != ENVELOPE_FIELDS.len() {
            self.discard_state_sync_seed(&binding.session);
            return invalid_params_error("seed envelope must be all-or-none");
        }
        let seed_id = parsed.seed_id.clone().unwrap_or_default();
        let seed_generation = parsed.seed_generation.unwrap_or_default();
        let batch_index = parsed.seed_batch_index.unwrap_or_default();
        let batch_total = parsed.seed_batch_total.unwrap_or_default();
        let seed_complete = parsed.seed_complete.unwrap_or(false);
        if seed_id.is_empty() || seed_id.len() > STATE_SYNC_SEED_MAX_ID_BYTES {
            self.discard_state_sync_seed(&binding.session);
            return invalid_params_error(format!(
                "seed_id must contain 1..={STATE_SYNC_SEED_MAX_ID_BYTES} bytes"
            ));
        }
        let digest = state_sync_seed_content_digest(&request);
        {
            let seeds = self.state_sync_seeds.lock().expect("state sync seed mutex");
            if let Some(completed) = seeds
                .sessions
                .get(&binding.session)
                .and_then(|state| state.completed.as_ref())
                .filter(|completed| completed.seed_id == seed_id)
            {
                if completed.final_digest == digest {
                    return HandlerOutcome::Response(completed.result.clone());
                }
                return HandlerOutcome::Error {
                    code: "state_sync_seed_digest_mismatch".to_string(),
                    message: format!(
                        "completed seed content changed (generation={}, seq={}, total={})",
                        completed.generation, completed.expected_seq, completed.total
                    ),
                };
            }
        }
        if parsed.shadow_generation != seed_generation {
            self.discard_state_sync_seed(&binding.session);
            return HandlerOutcome::Error {
                code: "state_sync_seed_attempt_mismatch".to_string(),
                message: "shadow_generation must match seed_generation".to_string(),
            };
        }
        if batch_total == 0 || batch_index >= batch_total {
            self.discard_state_sync_seed(&binding.session);
            return HandlerOutcome::Error {
                code: "state_sync_seed_protocol_mismatch".to_string(),
                message: "seed batch index/total is invalid".to_string(),
            };
        }
        if seed_complete != (batch_index + 1 == batch_total) {
            self.discard_state_sync_seed(&binding.session);
            return HandlerOutcome::Error {
                code: "state_sync_seed_protocol_mismatch".to_string(),
                message: "seed_complete disagrees with the final batch index".to_string(),
            };
        }
        let scalar_tail_fields = [
            "seed_boundary_id",
            "workspace",
            "last_todo_state",
            "acked_watermarks",
            "todo_synthetic_anchor",
            "emergency_latches",
        ]
        .iter()
        .filter(|field| {
            request
                .as_object()
                .is_some_and(|object| object.contains_key(**field))
        })
        .count();
        let seed_skip_fields_present = request.as_object().is_some_and(|object| {
            [
                "drop_seed_skipped",
                "pending_agent_drops_skipped",
                "auto_search_hint_skipped",
            ]
            .iter()
            .any(|field| object.contains_key(*field))
        });
        if !seed_complete && (scalar_tail_fields != 0 || seed_skip_fields_present)
            || seed_complete && scalar_tail_fields < 4
        {
            self.discard_state_sync_seed(&binding.session);
            return HandlerOutcome::Error {
                code: "state_sync_seed_protocol_mismatch".to_string(),
                message: "seed scalar tail must appear only and completely on the final batch"
                    .to_string(),
            };
        }

        let batch_bytes = match serde_json::to_vec(&request) {
            Ok(bytes) => bytes.len(),
            Err(error) => {
                self.discard_state_sync_seed(&binding.session);
                return invalid_params_error(error.to_string());
            }
        };
        timing.bytes = batch_bytes;
        // Batch zero is checked against durable metadata before the process-local state is
        // touched. A stale retry therefore cannot evict or allocate another live attempt.
        if batch_index == 0 {
            let loaded = match store.load(&binding.session) {
                Ok(loaded) => loaded,
                Err(error) => {
                    return HandlerOutcome::Error {
                        code: "store_load_failed".to_string(),
                        message: error.to_string(),
                    };
                }
            };
            if loaded.meta.shadow_generation != seed_generation {
                return HandlerOutcome::Error {
                    code: "state_sync_generation_mismatch".to_string(),
                    message: format!(
                        "seed_generation {seed_generation} did not match durable generation {}",
                        loaded.meta.shadow_generation
                    ),
                };
            }
            if loaded.meta.shadow_seq != parsed.expected_shadow_seq {
                return state_sync_seq_mismatch_error(
                    parsed.expected_shadow_seq,
                    loaded.meta.shadow_seq,
                );
            }
        }

        enum StageAction {
            Ack(usize),
            Apply {
                batches: Vec<ModuleStateSyncWire>,
                seed_id: String,
                final_digest: String,
                generation: u64,
                expected_seq: u64,
                total: usize,
            },
        }

        let action = {
            let mut seeds = self.state_sync_seeds.lock().expect("state sync seed mutex");
            let activity_at = self.state_sync_seed_now();
            seeds.evict_stale_collectors(activity_at);
            let phase = {
                let state = seeds.sessions.entry(binding.session.clone()).or_default();
                std::mem::replace(&mut state.phase, StateSyncSeedPhase::Idle)
            };
            // Authority callers can send a paged initial feed without a separate reset.
            // Their bound real session already owns the current generation, so arm the
            // same bounded collector automatically for the first batch.
            let phase = match phase {
                StateSyncSeedPhase::Idle if batch_index == 0 => StateSyncSeedPhase::AwaitingSeed {
                    generation: seed_generation,
                    expected_seq: parsed.expected_shadow_seq,
                },
                phase => phase,
            };
            let phase = match phase {
                StateSyncSeedPhase::Collecting(pending)
                    if batch_index == 0
                        && (pending.seed_id != seed_id
                            || pending.generation != seed_generation
                            || pending.expected_seq != parsed.expected_shadow_seq
                            || pending.total != batch_total) =>
                {
                    // A sender rebuilding after a lost acknowledgement starts a fresh
                    // attempt at batch zero. Replace the stale collector while holding
                    // the coordinator lock, and release its bytes before charging the
                    // new first batch in the AwaitingSeed arm below.
                    let stale = StateSyncSeedPhase::Collecting(pending);
                    seeds.release_phase(&stale);
                    StateSyncSeedPhase::AwaitingSeed {
                        generation: seed_generation,
                        expected_seq: parsed.expected_shadow_seq,
                    }
                }
                phase => phase,
            };
            match phase {
                StateSyncSeedPhase::Idle => {
                    seeds.set_phase(&binding.session, StateSyncSeedPhase::Idle);
                    return HandlerOutcome::Error {
                        code: "state_sync_seed_not_armed".to_string(),
                        message: "paged state-sync batches must start at index zero".to_string(),
                    };
                }
                applying @ StateSyncSeedPhase::Applying { .. } => {
                    seeds.set_phase(&binding.session, applying);
                    return HandlerOutcome::Error {
                        code: "state_sync_seed_in_progress".to_string(),
                        message: "the final state-sync seed batch is being applied".to_string(),
                    };
                }
                awaiting @ StateSyncSeedPhase::AwaitingSeed {
                    generation,
                    expected_seq,
                } => {
                    if batch_index != 0
                        || generation != seed_generation
                        || expected_seq != parsed.expected_shadow_seq
                    {
                        seeds.release_phase(&awaiting);
                        return HandlerOutcome::Error {
                            code: "state_sync_seed_attempt_mismatch".to_string(),
                            message: "seed batch does not match the active state-sync attempt"
                                .to_string(),
                        };
                    }
                    if batch_bytes > seeds.max_staged_bytes
                        || seeds
                            .total_staged_bytes
                            .checked_add(batch_bytes)
                            .is_none_or(|bytes| bytes > seeds.max_staged_bytes)
                    {
                        seeds.release_phase(&awaiting);
                        return HandlerOutcome::Error {
                            code: "state_sync_seed_buffer_overflow".to_string(),
                            message: "state-sync seed staging exceeded the handler-wide byte cap"
                                .to_string(),
                        };
                    }
                    seeds.total_staged_bytes += batch_bytes;
                    if seed_complete {
                        seeds.set_phase(
                            &binding.session,
                            StateSyncSeedPhase::Applying {
                                seed_id: seed_id.clone(),
                                bytes: batch_bytes,
                            },
                        );
                        StageAction::Apply {
                            batches: vec![parsed],
                            seed_id: seed_id.clone(),
                            final_digest: digest,
                            generation: seed_generation,
                            expected_seq,
                            total: batch_total,
                        }
                    } else {
                        seeds.set_phase(
                            &binding.session,
                            StateSyncSeedPhase::Collecting(PendingStateSyncSeed {
                                seed_id: seed_id.clone(),
                                generation: seed_generation,
                                expected_seq,
                                total: batch_total,
                                next_index: 1,
                                digests: vec![digest],
                                batches: vec![parsed],
                                bytes: batch_bytes,
                                last_activity: activity_at,
                            }),
                        );
                        StageAction::Ack(1)
                    }
                }
                StateSyncSeedPhase::Collecting(mut pending) => {
                    if pending.seed_id != seed_id
                        || pending.generation != seed_generation
                        || pending.expected_seq != parsed.expected_shadow_seq
                        || pending.total != batch_total
                    {
                        let discarded = StateSyncSeedPhase::Collecting(pending);
                        seeds.release_phase(&discarded);
                        return HandlerOutcome::Error {
                            code: "state_sync_seed_attempt_mismatch".to_string(),
                            message: "seed envelope changed during collection".to_string(),
                        };
                    }
                    if batch_index < pending.next_index {
                        let matches = pending
                            .digests
                            .get(batch_index)
                            .is_some_and(|accepted| accepted == &digest);
                        if matches {
                            let next_index = pending.next_index;
                            pending.last_activity = activity_at;
                            seeds.set_phase(
                                &binding.session,
                                StateSyncSeedPhase::Collecting(pending),
                            );
                            StageAction::Ack(next_index)
                        } else {
                            let discarded = StateSyncSeedPhase::Collecting(pending);
                            seeds.release_phase(&discarded);
                            return HandlerOutcome::Error {
                                code: "state_sync_seed_digest_mismatch".to_string(),
                                message: "redriven seed batch content changed".to_string(),
                            };
                        }
                    } else if batch_index > pending.next_index {
                        let discarded = StateSyncSeedPhase::Collecting(pending);
                        seeds.release_phase(&discarded);
                        return HandlerOutcome::Error {
                            code: "state_sync_seed_order_mismatch".to_string(),
                            message: "seed batches must arrive in strict index order".to_string(),
                        };
                    } else {
                        let next_seed_bytes = pending.bytes.checked_add(batch_bytes);
                        let next_total_bytes = seeds.total_staged_bytes.checked_add(batch_bytes);
                        if next_seed_bytes.is_none_or(|bytes| bytes > seeds.max_staged_bytes)
                            || next_total_bytes.is_none_or(|bytes| bytes > seeds.max_staged_bytes)
                        {
                            let discarded = StateSyncSeedPhase::Collecting(pending);
                            seeds.release_phase(&discarded);
                            return HandlerOutcome::Error {
                                code: "state_sync_seed_buffer_overflow".to_string(),
                                message:
                                    "state-sync seed staging exceeded the handler-wide byte cap"
                                        .to_string(),
                            };
                        }
                        pending.bytes = next_seed_bytes.unwrap_or(usize::MAX);
                        seeds.total_staged_bytes = next_total_bytes.unwrap_or(usize::MAX);
                        pending.last_activity = activity_at;
                        pending.next_index += 1;
                        pending.digests.push(digest.clone());
                        pending.batches.push(parsed);
                        if seed_complete {
                            let bytes = pending.bytes;
                            let batches = std::mem::take(&mut pending.batches);
                            let generation = pending.generation;
                            let expected_seq = pending.expected_seq;
                            let total = pending.total;
                            let completed_seed_id = pending.seed_id.clone();
                            seeds.set_phase(
                                &binding.session,
                                StateSyncSeedPhase::Applying {
                                    seed_id: completed_seed_id.clone(),
                                    bytes,
                                },
                            );
                            StageAction::Apply {
                                batches,
                                seed_id: completed_seed_id,
                                final_digest: digest,
                                generation,
                                expected_seq,
                                total,
                            }
                        } else {
                            let next_index = pending.next_index;
                            seeds.set_phase(
                                &binding.session,
                                StateSyncSeedPhase::Collecting(pending),
                            );
                            StageAction::Ack(next_index)
                        }
                    }
                }
            }
        };

        timing.stage_page_ms = staging_started.elapsed().as_secs_f64() * 1000.0;
        timing.ack_started = Some(Instant::now());
        match action {
            StageAction::Ack(next_expected_index) => respond(json!({
                "ok": true,
                "staged": true,
                "next_expected_index": next_expected_index,
            })),
            StageAction::Apply {
                batches,
                seed_id,
                final_digest,
                generation,
                expected_seq,
                total,
            } => {
                let assemble_started = Instant::now();
                let mut assembled = assemble_state_sync_seed(batches, generation, expected_seq);
                timing.assemble_series_ms = assemble_started.elapsed().as_secs_f64() * 1000.0;
                // The receipt shares the import transaction through the existing watermark JSON.
                // A lost final response or daemon restart cannot erase a committed series identity.
                if let Some(Value::Object(watermarks)) = assembled.acked_watermarks.as_mut() {
                    watermarks.insert("_state_sync_seed_id".into(), json!(seed_id));
                    watermarks.insert("_state_sync_seed_generation".into(), json!(generation));
                }
                let import_started = Instant::now();
                let outcome = self.apply_state_sync_wire(&binding, &store, assembled);
                timing.import_ms = import_started.elapsed().as_secs_f64() * 1000.0;
                timing.ack_started = Some(Instant::now());
                let completed_result = match &outcome {
                    HandlerOutcome::Response(bytes) => Some(bytes.clone()),
                    HandlerOutcome::Error { .. }
                    | HandlerOutcome::ErrorWithDetail { .. }
                    | HandlerOutcome::Streamed => None,
                };
                let mut seeds = self.state_sync_seeds.lock().expect("state sync seed mutex");
                let phase = {
                    let state = seeds.sessions.entry(binding.session.clone()).or_default();
                    std::mem::replace(&mut state.phase, StateSyncSeedPhase::Idle)
                };
                match phase {
                    StateSyncSeedPhase::Applying {
                        seed_id: applying_seed_id,
                        bytes,
                    } if applying_seed_id == seed_id => {
                        seeds.release_phase(&StateSyncSeedPhase::Applying {
                            seed_id: applying_seed_id,
                            bytes,
                        });
                        if let Some(result) = completed_result {
                            seeds
                                .sessions
                                .entry(binding.session.clone())
                                .or_default()
                                .completed = Some(CompletedStateSyncSeed {
                                seed_id,
                                final_digest,
                                generation,
                                expected_seq,
                                total,
                                result,
                            });
                        }
                    }
                    current => seeds.set_phase(&binding.session, current),
                }
                outcome
            }
        }
    }

    fn apply_state_sync_wire(
        &self,
        binding: &SessionBinding,
        store: &McStore,
        mut parsed: ModuleStateSyncWire,
    ) -> HandlerOutcome {
        let note_evaluation_available = parsed.note_evaluation_available.unwrap_or(false);
        let user_profile_present = parsed.user_profile.is_some();
        let user_profile = parsed.user_profile.take().unwrap_or_default();
        let workspace_present = parsed.workspace.is_some();
        let workspace = parsed.workspace.take().flatten();
        let drop_seeds: Vec<ModuleDropSeedRow> = parsed
            .drop_seeds
            .into_iter()
            .map(|seed| ModuleDropSeedRow {
                block_id: seed.block_id,
                related_block_ids: seed.related_block_ids,
                drop_mode: seed.drop_mode,
                payload: seed.payload,
            })
            .collect();
        let pending_agent_drops: Vec<PendingAgentDropSeedRow> = parsed
            .pending_agent_drops
            .into_iter()
            .map(|seed| PendingAgentDropSeedRow {
                block_id: seed.block_id,
                queued_at_ms: seed.queued_at_ms,
            })
            .collect();
        let user_hint_seeds: Vec<UserHintSeedRow> = parsed
            .auto_search_hint_decisions
            .into_iter()
            .map(|seed| UserHintSeedRow {
                block_id: seed.block_id,
                hint_text: seed.hint_text,
            })
            .collect();
        let note_nudge_anchors = parsed.note_nudge_anchors.map(|anchors| {
            anchors
                .into_iter()
                .map(|anchor| NoteNudgeAnchorSeed {
                    message_id: anchor.message_id,
                    text: anchor.text,
                })
                .collect::<Vec<_>>()
        });
        let todo_synthetic_anchor_present = parsed.todo_synthetic_anchor.is_some();
        let todo_synthetic_anchor = parsed.todo_synthetic_anchor.flatten().and_then(|seed| {
            let pair = injection::build_synthetic_todo_pair(&seed.state_json)?;
            (pair.call_id == seed.call_id).then(|| {
                pair.freeze_at(
                    (seed.message_id != "__magic_context_todo_head__").then_some(seed.message_id),
                )
            })
        });
        let emergency_latches = parsed.emergency_latches.map(|seed| {
            (
                seed.last_input_sample,
                seed.has_prior_drop,
                seed.last_execute_ordinal,
            )
        });
        let compartments = parsed
            .compartments
            .into_iter()
            .map(StoredCompartment::from)
            .collect::<Vec<_>>();
        if !compartments.is_empty() {
            let historian_phase = match store.load(&binding.session) {
                Ok(loaded) => loaded.meta.historian.state,
                Err(error) => {
                    return HandlerOutcome::Error {
                        code: "store_load_failed".to_string(),
                        message: error.to_string(),
                    };
                }
            };
            if historian_phase != HistorianPhase::Idle {
                // Do not stage or adopt compartment rows while a historian owns the
                // snapshot. The TS sender treats this typed rejection as retry-later,
                // retaining its acknowledged sequence and watermarks instead of forcing
                // a full re-seed on every active historian pass.
                return historian_compartment_sync_busy_error(historian_phase);
            }
        }
        let root_path = binding.project_root.to_string_lossy().to_string();
        let authority_project = match store.authority_project_for_route(&root_path, "memories") {
            Ok(project) => project,
            Err(error) => {
                return HandlerOutcome::Error {
                    code: "authority_project_resolution_failed".to_string(),
                    message: error.to_string(),
                };
            }
        };
        let store_project_path = authority_project.as_deref().unwrap_or(&root_path);
        let has_workspace = workspace.is_some();
        let (workspace, member_paths) =
            match prepare_authority_workspace(store_project_path, workspace) {
                Ok(prepared) => prepared,
                Err(error) => return invalid_params_error(error),
            };
        let memories = match parsed
            .memories
            .into_iter()
            .map(|memory| {
                authority_source_path(
                    memory.project_path.as_deref(),
                    store_project_path,
                    &member_paths,
                    has_workspace,
                )
                .map(|project_path| memory.into_row(project_path))
            })
            .collect::<Result<Vec<ModuleMemoryRow>, String>>()
        {
            Ok(memories) => memories,
            Err(error) => return invalid_params_error(error),
        };
        let memory_mutations = match parsed
            .memory_mutations
            .into_iter()
            .map(|mutation| {
                authority_source_path(
                    mutation.project_path.as_deref(),
                    store_project_path,
                    &member_paths,
                    has_workspace,
                )
                .map(|project_path| mutation.into_row(project_path))
            })
            .collect::<Result<Vec<ModuleMemoryMutationRow>, String>>()
        {
            Ok(mutations) => mutations,
            Err(error) => return invalid_params_error(error),
        };
        let acked_watermarks = parsed.acked_watermarks.unwrap_or_else(|| {
            json!({
                "compartment_seq": compartments.iter().map(|c| c.sequence).max(),
                "memory_id": memories.iter().map(|m| m.id).max(),
                "memory_mutation_id": memory_mutations.iter().map(|m| m.mutation.id).max(),
                "last_todo_state": parsed.last_todo_state.is_some(),
            })
        });
        #[cfg(test)]
        if let Some(hook) = self
            .state_sync_before_apply_hook
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .take()
        {
            hook();
        }
        match store.apply_authority_state_sync(ModuleStateSyncRequest {
            session_id: &binding.session,
            project_path: &root_path,
            shadow_generation: parsed.shadow_generation,
            expected_shadow_seq: parsed.expected_shadow_seq,
            seed_boundary_id: parsed.seed_boundary_id.as_deref(),
            drop_seeds: &drop_seeds,
            drop_seed_skipped: parsed.drop_seed_skipped,
            pending_agent_drops: &pending_agent_drops,
            pending_agent_drops_skipped: parsed.pending_agent_drops_skipped,
            user_hint_seeds: &user_hint_seeds,
            auto_search_hint_skipped: parsed.auto_search_hint_skipped,
            note_nudge_anchors: note_nudge_anchors.as_deref(),
            todo_synthetic_anchor: todo_synthetic_anchor.as_ref(),
            todo_synthetic_anchor_present,
            emergency_latches,
            pending_compaction_marker: parsed
                .pending_compaction_marker
                .as_ref()
                .map(|marker| marker.as_ref()),
            deferred_execute_state: parsed
                .deferred_execute_state
                .as_ref()
                .map(|deferred| deferred.as_ref()),
            channel2_nudge_state: parsed.channel2_nudge_state.as_deref(),
            strip_seeds: &parsed
                .strip_seeds
                .iter()
                .map(|seed| ModuleStripSeedRow {
                    message_id: seed.message_id.clone(),
                    strip_kind: seed.strip_kind.clone(),
                })
                .collect::<Vec<_>>(),
            strip_seed_skipped: parsed.strip_seed_skipped,
            reasoning_cleared_through_tag: parsed.reasoning_cleared_through_tag,
            compartments: &compartments,
            memories: &memories,
            memory_mutations: &memory_mutations,
            user_profile: &user_profile,
            user_profile_present,
            workspace: workspace.as_ref(),
            workspace_present,
            last_todo_state: parsed.last_todo_state,
            project_memory_epoch: parsed.project_memory_epoch,
            user_profile_version: parsed.user_profile_version,
            acked_watermarks,
        }) {
            Ok(result) => {
                self.set_note_evaluation_capability(
                    &binding.project_root,
                    note_evaluation_available,
                );
                respond(json!({
                    "ok": true,
                    "shadow_generation": result.shadow_generation,
                    "shadow_seq": result.shadow_seq,
                    "row_version": result.row_version,
                    "memories_skipped": result.memories_skipped,
                    "drop_seeds_skipped": result.drop_seeds_skipped,
                    "pending_agent_drops_seeded": result.pending_agent_drops_seeded,
                    "pending_agent_drops_skipped": result.pending_agent_drops_skipped,
                    "user_hint_seeds_seeded": result.user_hint_seeds_seeded,
                    "auto_search_hint_skipped": result.auto_search_hint_skipped,
                    "note_nudge_anchors_seeded": result.note_nudge_anchors_seeded,
                    "todo_synthetic_anchor_seeded": result.todo_synthetic_anchor_seeded,
                    "emergency_latches_seeded": result.emergency_latches_seeded,
                    "strip_seeds_skipped": result.strip_seeds_skipped,
                }))
            }
            Err(ModuleStateSyncError::GenerationMismatch { expected, found }) => {
                HandlerOutcome::Error {
                    code: "state_sync_generation_mismatch".to_string(),
                    message: format!(
                        "shadow_generation {expected} is stale; current generation is {found}"
                    ),
                }
            }
            Err(ModuleStateSyncError::AuthoritySeqMismatch { expected, found }) => {
                state_sync_seq_mismatch_error(expected, found)
            }
            Err(ModuleStateSyncError::NonRetryableStoreConstraint { detail }) => {
                HandlerOutcome::Error {
                    code: "state_sync_non_retryable".to_string(),
                    message: json!({
                        "code": "state_sync_non_retryable",
                        "retryable": false,
                        "detail": detail,
                    })
                    .to_string(),
                }
            }
            Err(ModuleStateSyncError::HistorianBusy { phase }) => {
                historian_compartment_sync_busy_error(phase)
            }
            Err(ModuleStateSyncError::InvalidSeedBoundary { declared, detail }) => {
                HandlerOutcome::Error {
                    code: "state_sync_seed_boundary_mismatch".to_string(),
                    message: format!("seed boundary {declared:?} rejected: {detail}"),
                }
            }
            Err(error) => HandlerOutcome::Error {
                code: "state_sync_failed".to_string(),
                message: error.to_string(),
            },
        }
    }

    async fn handle_transform_page_value(
        &self,
        channel: u16,
        request: Value,
        lane: TransformLane,
        ticket: &TransformDispatchTicket<'_>,
    ) -> HandlerOutcome {
        let present = TRANSFORM_PAGE_FIELDS
            .iter()
            .filter(|field| request.get(**field).is_some())
            .count();
        let session_id = request.get("session_id").and_then(Value::as_str);
        let binding = match self.state_sync_binding(channel, session_id) {
            Ok(binding) => binding,
            Err(outcome) => return outcome,
        };
        if present != TRANSFORM_PAGE_FIELDS.len() {
            self.discard_transform_pages(&binding.session);
            return invalid_params_error("transform page envelope must be all-or-none");
        }
        let transform_id = match request.get("transform_page_id").and_then(Value::as_str) {
            Some(id) if !id.is_empty() && id.len() <= TRANSFORM_PAGE_MAX_ID_BYTES => id.to_string(),
            _ => {
                self.discard_transform_pages(&binding.session);
                return invalid_params_error(format!(
                    "transform_page_id must contain 1..={TRANSFORM_PAGE_MAX_ID_BYTES} bytes"
                ));
            }
        };
        let Some(generation) = request.get("transform_generation").and_then(Value::as_u64) else {
            self.discard_transform_pages(&binding.session);
            return invalid_params_error("transform_generation must be an unsigned integer");
        };
        let Some(page_index) = request.get("transform_page_index").and_then(Value::as_u64) else {
            self.discard_transform_pages(&binding.session);
            return invalid_params_error("transform_page_index must be an unsigned integer");
        };
        let Some(page_total) = request.get("transform_page_total").and_then(Value::as_u64) else {
            self.discard_transform_pages(&binding.session);
            return invalid_params_error("transform_page_total must be an unsigned integer");
        };
        let Some(page_complete) = request
            .get("transform_page_complete")
            .and_then(Value::as_bool)
        else {
            self.discard_transform_pages(&binding.session);
            return invalid_params_error("transform_page_complete must be a boolean");
        };
        let Some(page_digest) = request.get("transform_page_digest").and_then(Value::as_str) else {
            self.discard_transform_pages(&binding.session);
            return invalid_params_error("transform_page_digest must be a string");
        };
        let page_index = usize::try_from(page_index).unwrap_or(usize::MAX);
        let page_total = usize::try_from(page_total).unwrap_or(usize::MAX);
        if page_total == 0 || page_index >= page_total {
            self.discard_transform_pages(&binding.session);
            return transform_page_error(
                lane,
                "protocol_mismatch",
                "transform page index/total is invalid",
            );
        }
        if page_complete != (page_index + 1 == page_total) {
            self.discard_transform_pages(&binding.session);
            return transform_page_error(
                lane,
                "protocol_mismatch",
                "transform page completion disagrees with the final page index",
            );
        }
        if !page_complete
            && request.as_object().is_some_and(|object| {
                object.keys().any(|key| {
                    !["method", "session_id", "shadow_generation"]
                        .into_iter()
                        .chain(TRANSFORM_PAGE_FIELDS)
                        .chain(TRANSFORM_PAGE_ARRAY_FIELDS)
                        .chain(TRANSFORM_PAGE_MAP_FIELDS)
                        .any(|allowed| allowed == key.as_str())
                })
            })
        {
            self.discard_transform_pages(&binding.session);
            return transform_page_error(
                lane,
                "protocol_mismatch",
                "non-final transform pages may carry only message arrays and pageable maps",
            );
        }
        let page_digest_started_at = Instant::now();
        let digest_matches = transform_page_content_digest(&request) == page_digest;
        let page_digest_ms = page_digest_started_at.elapsed().as_secs_f64() * 1_000.0;
        if !digest_matches {
            self.discard_transform_pages(&binding.session);
            return transform_page_error(
                lane,
                "digest_mismatch",
                "transform page content digest did not match the supplied digest",
            );
        }
        let page_size_started_at = Instant::now();
        let page_bytes = match serde_json::to_vec(&request) {
            Ok(bytes) => bytes.len(),
            Err(error) => {
                self.discard_transform_pages(&binding.session);
                return invalid_params_error(error.to_string());
            }
        };
        let page_size_encode_ms = page_size_started_at.elapsed().as_secs_f64() * 1_000.0;
        if page_bytes > TRANSFORM_PAGE_MAX_BYTES {
            self.discard_transform_pages(&binding.session);
            return transform_page_error(
                lane,
                "buffer_overflow",
                "transform page exceeded the 512 KiB page cap",
            );
        }
        {
            let transforms = self.transform_pages.lock().expect("transform page mutex");
            if let Some(completed) = transforms.completed(&binding.session, &transform_id) {
                if completed.generation != generation {
                    return transform_page_error(
                        lane,
                        "digest_mismatch",
                        "completed transform generation changed",
                    );
                }
                if !page_complete {
                    // Content-addressed attempt ids let a caller whose route disappeared
                    // replay page admission cheaply. The final-page digest below remains
                    // the response adoption fence; random ids from older adapters never
                    // collide with a retained completion.
                    return respond(json!({
                        "ok": true,
                        "staged": true,
                        "next_expected_index": page_index + 1,
                        "completed_replay": true,
                    }));
                }
                if completed.final_digest == page_digest {
                    return HandlerOutcome::Response(completed.result.clone());
                }
                return transform_page_error(
                    lane,
                    "digest_mismatch",
                    "completed transform page content changed",
                );
            }
        }
        let queued_at_ms = now_ms().max(0) as u64;
        let page_stage_started_at = Instant::now();
        let staged = {
            let mut transforms = self.transform_pages.lock().expect("transform page mutex");
            transforms.stage(
                &binding.session,
                transform_id,
                generation,
                page_index,
                page_total,
                page_digest.to_string(),
                request,
                page_bytes,
                page_complete,
                queued_at_ms,
            )
        };
        let page_stage_ms = page_stage_started_at.elapsed().as_secs_f64() * 1_000.0;
        self.refresh_oldest_queued_at_ms();
        tracing::info!(
            target: "perf",
            "mc-transform-page-timing session={} page={}/{} bytes={} digest={:.1} size_encode={:.1} stage={:.1}",
            binding.session,
            page_index + 1,
            page_total,
            page_bytes,
            page_digest_ms,
            page_size_encode_ms,
            page_stage_ms,
        );
        let action = match staged {
            Ok(action) => {
                ticket.accept();
                action
            }
            Err(error) => {
                let (suffix, message) = match error {
                    TransformPageStageError::AttemptMismatch => (
                        "attempt_mismatch",
                        "transform page generation or envelope changed during collection",
                    ),
                    TransformPageStageError::DigestMismatch => {
                        ("digest_mismatch", "redriven transform page content changed")
                    }
                    TransformPageStageError::OrderMismatch => (
                        "order_mismatch",
                        "transform pages must arrive in strict index order",
                    ),
                    TransformPageStageError::BufferOverflow => (
                        "buffer_overflow",
                        "transform page staging exceeded the handler-wide byte cap",
                    ),
                    TransformPageStageError::InProgress => {
                        ("in_progress", "the final transform page is being applied")
                    }
                };
                return transform_page_error(lane, suffix, message);
            }
        };
        match action {
            TransformPageStageAction::Ack(next_expected_index) => respond(json!({
                "ok": true,
                "staged": true,
                "next_expected_index": next_expected_index,
            })),
            TransformPageStageAction::Apply {
                pages,
                transform_id,
                generation,
                final_digest,
                inbound_bytes,
            } => {
                let page_assembly_started_at = Instant::now();
                let assembled = match assemble_transform_pages(pages) {
                    Ok(assembled) => assembled,
                    Err(error) => {
                        self.discard_transform_pages(&binding.session);
                        let (suffix, message) = match error {
                            TransformPageAssemblyError::ProtocolMismatch(message) => {
                                ("protocol_mismatch", message)
                            }
                            TransformPageAssemblyError::DigestMismatch(message) => {
                                ("digest_mismatch", message)
                            }
                        };
                        return transform_page_error(lane, suffix, message);
                    }
                };
                let page_assembly_ms = page_assembly_started_at.elapsed().as_secs_f64() * 1_000.0;
                tracing::debug!(
                    "mc-transform-page-assembly session={} pages={} inbound_bytes={} assembly={:.1}",
                    binding.session, page_total, inbound_bytes, page_assembly_ms,
                );
                let outcome = self
                    .handle_transform_unpaged_value(
                        channel,
                        assembled,
                        true,
                        Some(inbound_bytes),
                        ticket,
                    )
                    .await;
                let completed_result = match &outcome {
                    HandlerOutcome::Response(bytes) => Some(bytes.clone()),
                    HandlerOutcome::Error { .. }
                    | HandlerOutcome::ErrorWithDetail { .. }
                    | HandlerOutcome::Streamed => None,
                };
                let mut transforms = self.transform_pages.lock().expect("transform page mutex");
                let phase = {
                    let session = transforms
                        .sessions
                        .entry(binding.session.clone())
                        .or_default();
                    std::mem::replace(&mut session.phase, TransformPagePhase::Idle)
                };
                match phase {
                    TransformPagePhase::Applying {
                        transform_id: applying_id,
                        bytes,
                    } if applying_id == transform_id => {
                        transforms.release_phase(&TransformPagePhase::Applying {
                            transform_id: applying_id,
                            bytes,
                        });
                        if let Some(result) = completed_result {
                            transforms
                                .sessions
                                .entry(binding.session.clone())
                                .or_default()
                                .completed = Some(CompletedTransformPage {
                                transform_id,
                                generation,
                                final_digest,
                                result,
                            });
                        }
                    }
                    current => transforms.set_phase(&binding.session, current),
                }
                drop(transforms);
                self.refresh_oldest_queued_at_ms();
                outcome
            }
        }
    }

    fn register_dreamer_run(&self, session_id: &str) -> DreamerRunGuard {
        self.active_dreamer_runs
            .lock()
            .expect("dreamer registry mutex")
            .insert(session_id.to_string());
        DreamerRunGuard {
            registry: Arc::clone(&self.active_dreamer_runs),
            session_id: session_id.to_string(),
        }
    }

    fn unregister_dreamer_run(&self, session_id: &str) {
        self.active_dreamer_runs
            .lock()
            .expect("dreamer registry mutex")
            .remove(session_id);
    }

    fn dreamer_run_registered(&self, session_id: &str) -> bool {
        self.active_dreamer_runs
            .lock()
            .expect("dreamer registry mutex")
            .contains(session_id)
    }

    async fn handle_dreamer_run_task(&self, channel: u16, request: &Value) -> HandlerOutcome {
        let (ledger_session, binding) =
            match self.management_binding(channel, request, "dreamer.run_task") {
                Ok(value) => value,
                Err(outcome) => return outcome,
            };
        let Some(store) = self.store.get().cloned() else {
            return self.store_refusal();
        };
        let Some(task) = request.get("task").and_then(Value::as_str) else {
            return invalid_params_error("dreamer.run_task requires task");
        };
        if task != CLASSIFY_TASK {
            // Enumerating the task here is a capability boundary: callers cannot use this
            // route to select an arbitrary system prompt, model, or tool-enabled run.
            return invalid_params_error(format!("unknown dreamer task {task:?}"));
        }
        let Some(command_id) = request.get("command_id").and_then(Value::as_str) else {
            return invalid_params_error("dreamer.run_task requires command_id");
        };
        if command_id.trim().is_empty() || command_id.len() > 256 {
            return invalid_params_error("dreamer.run_task command_id must be 1-256 bytes");
        }
        let Some(authority_generation) =
            request.get("authority_generation").and_then(Value::as_u64)
        else {
            return invalid_params_error("dreamer.run_task requires authority_generation");
        };
        let route_root = binding.project_root.to_string_lossy().to_string();
        let Some(project) = (match store.authority_project_for_route(&route_root, "memories") {
            Ok(project) => project,
            Err(error) => {
                return HandlerOutcome::Error {
                    code: "authority_lookup_failed".to_string(),
                    message: error.to_string(),
                };
            }
        }) else {
            return HandlerOutcome::Error {
                code: "authority_not_module".to_string(),
                message: "memories authority for this route is not MODULE".to_string(),
            };
        };
        let Some((context_store_uuid, authority_project)) =
            (match store.module_authority_for_project(&project, "memories") {
                Ok(authority) => authority,
                Err(error) => {
                    return HandlerOutcome::Error {
                        code: "authority_lookup_failed".to_string(),
                        message: error.to_string(),
                    };
                }
            })
        else {
            return HandlerOutcome::Error {
                code: "authority_not_module".to_string(),
                message: "memories authority for this route is not MODULE".to_string(),
            };
        };
        let authority =
            match store.authority_status(&context_store_uuid, &authority_project, "memories") {
                Ok(Some(authority)) => authority,
                Ok(None) => {
                    return HandlerOutcome::Error {
                        code: "authority_not_module".to_string(),
                        message: "memories authority row is missing".to_string(),
                    };
                }
                Err(error) => {
                    return HandlerOutcome::Error {
                        code: "authority_lookup_failed".to_string(),
                        message: error.to_string(),
                    };
                }
            };
        if authority.state != "MODULE" {
            return HandlerOutcome::Error {
                code: "authority_not_module".to_string(),
                message: format!("memories authority is {}", authority.state),
            };
        }
        if authority.generation != authority_generation {
            return HandlerOutcome::Error {
                code: "authority_generation_mismatch".to_string(),
                message: format!(
                    "authority generation is {}, request used {authority_generation}",
                    authority.generation
                ),
            };
        }
        let Some(payload) = request.get("payload").and_then(Value::as_object) else {
            return invalid_params_error("dreamer.run_task requires an object payload");
        };
        let Some(prompt_body) = payload.get("prompt_body").and_then(Value::as_str) else {
            return invalid_params_error("classify payload requires prompt_body");
        };
        if prompt_body.len() > MAX_CLASSIFY_PROMPT_BYTES {
            return HandlerOutcome::Error {
                code: "payload_too_large".to_string(),
                message: format!("classify prompt_body exceeds {MAX_CLASSIFY_PROMPT_BYTES} bytes"),
            };
        }
        if payload.get("items").and_then(Value::as_array).is_none() {
            return invalid_params_error("classify payload requires items");
        }

        if let Ok(Some(recorded)) = store.load_dream_task_command(&ledger_session, command_id) {
            return replay_dream_task_response(&recorded.response_json);
        }

        let requested_model_chain = match request.get("model_chain") {
            None => None,
            Some(Value::Array(entries)) if entries.len() <= 16 => {
                let mut models = Vec::with_capacity(entries.len());
                for entry in entries {
                    let Some(model) = entry.as_str() else {
                        return invalid_params_error(
                            "dreamer.run_task model_chain entries must be strings",
                        );
                    };
                    if model.trim().is_empty() || model.len() > 256 {
                        return invalid_params_error(
                            "dreamer.run_task model_chain entries must be 1-256 bytes",
                        );
                    }
                    if !models.iter().any(|existing| existing == model) {
                        models.push(model.to_string());
                    }
                }
                Some(models)
            }
            Some(Value::Array(_)) => {
                return invalid_params_error(
                    "dreamer.run_task model_chain supports at most 16 entries",
                );
            }
            Some(_) => {
                return invalid_params_error("dreamer.run_task model_chain must be an array");
            }
        };
        // The host resolves each dreamer task's model chain and sends it; the module
        // keeps no chain of its own to fall back to.
        let Some(model_chain) = requested_model_chain.as_deref() else {
            tracing::warn!(
                "mc-module: dreamer.run_task {task} refused: the request carried no model_chain"
            );
            return HandlerOutcome::Error {
                code: "model_chain_missing".to_string(),
                message: "dreamer.run_task requires the host-resolved model_chain".to_string(),
            };
        };
        let classify_system_prompt = historian_prompt::with_content_language_directive(
            CLASSIFY_SYSTEM_PROMPT,
            binding.config.language.as_deref(),
            historian_prompt::ContentLanguageDirectiveOptions::default(),
        );
        let host_completion = match request.get("host_completion") {
            None | Some(Value::Null) => None,
            Some(value) => match parse_host_classify_completion(value) {
                Ok(completion) => Some(completion),
                Err(message) => return invalid_params_error(message),
            },
        };
        // Under the host runner this module has no completion runner to attempt the
        // chain on. The request is answered with what the host needs to run the
        // completion itself, and the host sends the text back on a second request.
        // Nothing is recorded in the command ledger, so that second request under
        // the same command id is not answered from a replay of this one.
        if host_completion.is_none()
            && self
                .effective_config(&binding.project_root)
                .historian_runner
                == HistorianRunnerKind::Host
        {
            tracing::info!(
                "mc-module: classify runner=host: the host runs the completion for command {command_id}"
            );
            return respond(json!({
                "ok": false,
                "code": HOST_COMPLETION_REQUIRED,
                "message": "historian.runner is host: run the classify completion on the host and resend it as host_completion",
                "system_prompt": classify_system_prompt.as_ref(),
                "max_output_tokens": CLASSIFY_MAX_OUTPUT_TOKENS,
                "temperature": CLASSIFY_TEMPERATURE,
            }));
        }
        let mut attempts = 0usize;
        // Every attempt's failure is kept. Overwriting one slot reported whichever model
        // happened to be last and threw away the cause of the run that actually broke.
        let mut attempt_errors: Vec<String> = Vec::new();
        let mut output = None;
        let runner = if host_completion.is_some() {
            "host"
        } else {
            "module"
        };
        if let Some(completion) = host_completion {
            attempts = 1;
            let outcome = if has_manifest_envelope(&completion.text) {
                "manifest"
            } else {
                "no_manifest"
            };
            tracing::info!(
                "mc-module: classify attempt=1 model={} session=host outcome={outcome}",
                completion.model
            );
            if outcome == "manifest" {
                output = Some((
                    completion.model,
                    historian_producer::ProducerOutput {
                        text: completion.text,
                        length_capped: completion.length_capped,
                        usage: completion.usage,
                    },
                    "host".to_string(),
                ));
            } else {
                attempt_errors.push(format!(
                    "{}: classify host completion returned no classify manifest envelope",
                    completion.model
                ));
            }
        }
        // The chain is walked here only when this module ran the completion itself.
        let producer_models: &[String] = if runner == "host" { &[] } else { model_chain };
        for model in producer_models {
            attempts += 1;
            // Each attempt gets its OWN provider session. An attempt can end while its run
            // is still active (a parked run, or one abandoned at the await deadline), and a
            // send into a session that still holds an active run is queued behind it rather
            // than started -- which the classifier cannot drain.
            let child_session =
                child_session_id(&authority_project, command_id, next_attempt_nonce(now_ms()));
            let _dreamer_run_guard = self.register_dreamer_run(&child_session);
            let mut record_attempt = |outcome: &str, detail: String| {
                tracing::info!(
                    "mc-module: classify attempt={attempts} model={model} session={child_session} outcome={outcome}{}",
                    if detail.is_empty() {
                        String::new()
                    } else {
                        format!(": {detail}")
                    }
                );
                if !detail.is_empty() {
                    attempt_errors.push(format!("{model}: {detail}"));
                }
            };
            let mut producer = match self.producer_factory.connect(&binding.project_root).await {
                Ok(producer) => producer,
                Err(error) => {
                    record_attempt("connect_failed", error.to_string());
                    continue;
                }
            };
            let started = producer
                .start_with_generation(
                    &child_session,
                    classify_system_prompt.as_ref(),
                    prompt_body,
                    model,
                    CLASSIFY_MAX_OUTPUT_TOKENS,
                    CLASSIFY_TEMPERATURE,
                )
                .await;
            let attempt_output = match started {
                Ok(handle) => match producer
                    .await_output_with_timeout(&handle.run_id, CLASSIFY_AWAIT_TIMEOUT)
                    .await
                {
                    Ok(result) => Ok(result),
                    Err(HistorianProducerError::TimedOut) => {
                        producer
                            .redrain_output_with_timeout(&handle.run_id, CLASSIFY_RECOVERY_TIMEOUT)
                            .await
                    }
                    Err(error) => Err(error),
                },
                Err(error) => Err(error),
            };
            match attempt_output {
                Ok(result) if has_manifest_envelope(&result.text) => {
                    // The module checks only for the task-specific envelope. Even if the
                    // output limit truncated a result, this layer accepts it when the
                    // envelope remains; the host parser rejects malformed contents.
                    record_attempt("manifest", String::new());
                    output = Some((model.clone(), result, child_session.clone()));
                    producer.purge_session(&child_session).await;
                    break;
                }
                Ok(_) => record_attempt(
                    "no_manifest",
                    "classify producer returned no classify manifest envelope".to_string(),
                ),
                Err(error) => record_attempt("failed", error.to_string()),
            }
            producer.purge_session(&child_session).await;
        }
        if output.is_none() {
            let failure = if attempt_errors.is_empty() {
                "classify producer has no usable model".to_string()
            } else {
                attempt_errors.join("; ")
            };
            let response = json!({
                "ok": false,
                "code": "dreamer_run_failed",
                "message": failure,
            });
            let _ = store.record_dream_task_command(
                &ledger_session,
                command_id,
                &response.to_string(),
                now_ms(),
            );
            return HandlerOutcome::Error {
                code: "dreamer_run_failed".to_string(),
                message: failure,
            };
        }
        let (model, result, child_session) = output.expect("classifier output set");
        let mut response = json!({
            "ok": true,
            "manifest_text": result.text,
            "truncated": result.length_capped,
            "diagnostics": {
                "task": CLASSIFY_TASK,
                "model": model,
                "attempts": attempts,
                "child_session_id": child_session,
                "temperature": CLASSIFY_TEMPERATURE,
                "max_output_tokens": CLASSIFY_MAX_OUTPUT_TOKENS,
                "await_timeout_ms": CLASSIFY_AWAIT_TIMEOUT.as_millis(),
                "recovery_timeout_ms": CLASSIFY_RECOVERY_TIMEOUT.as_millis(),
            }
        });
        if runner == "host" {
            response["diagnostics"]["runner"] = json!("host");
        }
        // The runner's token spend for the successful attempt, so the host can record
        // it on its invocation row. Omitted when the runner reported none; hosts that
        // predate the field ignore it.
        if let Some(usage) = result.usage {
            response["usage"] = json!({
                "input": usage.input,
                "output": usage.output,
                "cache_read": usage.cache_read,
                "cache_write": usage.cache_write,
            });
        }
        match store.record_dream_task_command(
            &ledger_session,
            command_id,
            &response.to_string(),
            now_ms(),
        ) {
            Ok(recorded) => replay_dream_task_response(&recorded.response_json),
            Err(error) => HandlerOutcome::Error {
                code: "dreamer_ledger_failed".to_string(),
                message: error.to_string(),
            },
        }
    }

    async fn handle_memory_set_classification(
        &self,
        channel: u16,
        request: &Value,
    ) -> HandlerOutcome {
        let Some(args) = facade_arguments(request, &["rows"]) else {
            return invalid_params_error("memory.set_classification requires arguments");
        };
        let Some(memory_project) = non_empty_string_arg(&args, "memory_project") else {
            return invalid_params_error("memory.set_classification requires memory_project");
        };
        if let Err(outcome) = self.bind_facade_route_for_write(channel, &args, "memories") {
            return outcome;
        }
        let binding = match self.facade_binding(channel) {
            Ok(binding) => binding,
            Err(_) => return session_unresolved_error(),
        };
        let route_root = binding.project_root.to_string_lossy().to_string();
        let Some(store) = self.store.get() else {
            return self.store_refusal();
        };
        let authority_project =
            match store.authority_project_state_for_route(&route_root, "memories") {
                Ok(Some((project, state))) if state == "MODULE" => project,
                Ok(Some(_)) => return authority_draining_error("memories"),
                Ok(None) => {
                    return HandlerOutcome::Error {
                        code: "authority_not_module".to_string(),
                        message: "classification requires MODULE memories authority".to_string(),
                    };
                }
                Err(error) => {
                    return HandlerOutcome::Error {
                        code: "authority_lookup_failed".to_string(),
                        message: error.to_string(),
                    };
                }
            };
        if authority_project != memory_project {
            return HandlerOutcome::Error {
                code: "facade_project_vocabulary_mismatch".to_string(),
                message: format!(
                    "classification route is owned by {authority_project}, not {memory_project}"
                ),
            };
        }
        let Some(context_store_uuid) = args.get("context_store_uuid").and_then(Value::as_str)
        else {
            return invalid_params_error("memory.set_classification requires context_store_uuid");
        };
        let Some(authority_generation) = args.get("authority_generation").and_then(Value::as_u64)
        else {
            return invalid_params_error("memory.set_classification requires authority_generation");
        };
        let Some(rows) = args.get("rows").and_then(Value::as_array) else {
            return invalid_params_error("memory.set_classification requires rows");
        };
        let mut updates = Vec::with_capacity(rows.len());
        for row in rows {
            let Some(row) = row.as_object() else {
                return invalid_params_error("classification rows must be objects");
            };
            let Some(memory_id) = row.get("memory_id").and_then(Value::as_i64) else {
                return invalid_params_error("classification row requires memory_id");
            };
            let Some(hash) = row.get("content_hash_at_prompt").and_then(Value::as_str) else {
                return invalid_params_error("classification row requires content_hash_at_prompt");
            };
            updates.push(mc_store::ClassificationUpdate {
                memory_id,
                content_hash_at_prompt: hash.to_string(),
                importance: row
                    .get("importance")
                    .and_then(Value::as_i64)
                    .map(|value| value as i32),
                scope: row
                    .get("scope")
                    .and_then(Value::as_str)
                    .map(ToString::to_string),
                shareable: row.get("shareable").and_then(Value::as_bool),
            });
        }
        #[cfg(test)]
        if let Some(hook) = self
            .classification_before_apply_hook
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .take()
        {
            hook();
        }
        match store.with_facade_mutation(&route_root, "memories", || {
            store.set_memory_classification(
                context_store_uuid,
                memory_project,
                authority_generation,
                &updates,
                now_ms(),
            )
        }) {
            Ok(result) => respond(json!({
                "accepted": result.accepted,
                "rejected": result.rejected.iter().map(|row| json!({ "memory_id": row.memory_id, "reason": row.reason })).collect::<Vec<_>>(),
            })),
            Err(McStoreError::AuthorityGenerationMismatch { expected, found }) => {
                HandlerOutcome::Error {
                    code: "authority_generation_mismatch".to_string(),
                    message: format!("authority generation is {found}, request used {expected}"),
                }
            }
            Err(McStoreError::AuthorityStateMismatch { found, .. }) if found == "DRAINING" => {
                authority_draining_error("memories")
            }
            Err(McStoreError::AuthorityStateMismatch { expected, found }) => {
                HandlerOutcome::Error {
                    code: "authority_state_mismatch".to_string(),
                    message: format!("authority state is {found}, expected {expected}"),
                }
            }
            Err(error) if store_error_is_authority_draining(&error) => {
                authority_draining_error("memories")
            }
            Err(error) => HandlerOutcome::Error {
                code: "classification_apply_failed".to_string(),
                message: error.to_string(),
            },
        }
    }

