        handler.begin_store_open(descriptor, DescriptorOrigin::DevFallback);
        wait_for_store_open_phase(&handler, STORE_OPEN_WAITING).await;
        wait_for_store_open_phase(&handler, STORE_OPEN_IDLE).await;

