    #[test]
    fn transform_snapshot_cache_is_generation_safe_and_lru_bounded() {
        let request = |session_id: &str| {
            let mut request = transform_request(vec![ck("m1", 1, "text")], 1, 200_000);
            request.session_id = session_id.to_string();
            Arc::new(request)
        };
        let mut cache = TransformSnapshotCache::new(10);
        assert!(!cache.generation_present_in_flight_or_ready("a", 1));
        let a = cache.begin("a");
        assert!(cache.generation_present_in_flight_or_ready("a", a));
        cache.finish_ready("a", a, request("a"), 1, 5);
        assert!(cache.generation_present_in_flight_or_ready("a", a));
        let b = cache.begin("b");
        cache.finish_ready("b", b, request("b"), 2, 5);
        assert!(matches!(cache.get("a"), TransformSnapshotLookup::Ready(_)));

        let c = cache.begin("c");
        cache.finish_ready("c", c, request("c"), 3, 5);
        assert!(matches!(cache.get("b"), TransformSnapshotLookup::Missing));
        assert!(matches!(cache.get("a"), TransformSnapshotLookup::Ready(_)));
        assert!(matches!(cache.get("c"), TransformSnapshotLookup::Ready(_)));
        assert_eq!(cache.ready_bytes, 10);

        let stale = cache.begin("a");
        let current = cache.begin("a");
        cache.finish_ready("a", stale, request("stale"), 4, 1);
        assert!(matches!(cache.get("a"), TransformSnapshotLookup::InFlight));
        cache.finish_ready("a", current, request("a"), 5, 4);
        assert!(cache.ready_generation_matches("a", current));
        assert!(cache.ready_bytes <= cache.max_ready_bytes);

        let oversized = cache.begin("oversized");
        cache.finish_ready("oversized", oversized, request("oversized"), 0, 11);
        assert!(matches!(
            cache.get("oversized"),
            TransformSnapshotLookup::Missing
        ));
    }

    #[test]
    fn snapshot_lease_budget_survives_cache_churn_and_releases_exact_charge() {
        let request = |session_id: &str| {
            let mut request = transform_request(vec![ck("m1", 1, "text")], 1, 200_000);
            request.session_id = session_id.to_string();
            Arc::new(request)
        };
        let mut cache = TransformSnapshotCache::new(10);
        {
            let mut budget = cache
                .active_leases
                .lock()
                .expect("snapshot lease budget mutex");
            budget.max_bytes = 10;
            budget.max_count = 1;
        }
        let a = cache.begin("a");
        cache.finish_ready("a", a, request("a"), 0, 5);
        let b = cache.begin("b");
        cache.finish_ready("b", b, request("b"), 0, 5);
        let lease = match cache.get("a") {
            TransformSnapshotLookup::Ready(lease) => lease,
            _ => panic!("first lease must fit"),
        };

        // Churning the map can evict the map entry, but the leased Arc remains charged
        // until its guard drops and neither accounting domain may exceed its own bound.
        let c = cache.begin("c");
        cache.finish_ready("c", c, request("c"), 0, 6);
        assert!(cache.ready_bytes <= cache.max_ready_bytes);
        assert!(matches!(
            cache.get("c"),
            TransformSnapshotLookup::LeaseBudgetExceeded
        ));
        {
            let budget = cache
                .active_leases
                .lock()
                .expect("snapshot lease budget mutex");
            assert_eq!((budget.count, budget.bytes), (1, 5));
            assert!(budget.count <= budget.max_count);
            assert!(budget.bytes <= budget.max_bytes);
        }
        assert_eq!(lease.request.session_id, "a");
        drop(lease);
        {
            let budget = cache
                .active_leases
                .lock()
                .expect("snapshot lease budget mutex");
            assert_eq!((budget.count, budget.bytes), (0, 0));
        }
        assert!(matches!(cache.get("c"), TransformSnapshotLookup::Ready(_)));
    }

    #[test]
    fn snapshot_lease_budget_rejects_second_lease_on_bytes_alone() {
        let request = |session_id: &str| {
            let mut request = transform_request(vec![ck("m1", 1, "text")], 1, 200_000);
            request.session_id = session_id.to_string();
            Arc::new(request)
        };
        let mut cache = TransformSnapshotCache::new(16);
        {
            let mut budget = cache
                .active_leases
                .lock()
                .expect("snapshot lease budget mutex");
            budget.max_bytes = 9;
            budget.max_count = 8;
        }
        let first_generation = cache.begin("first");
        cache.finish_ready("first", first_generation, request("first"), 0, 5);
        let second_generation = cache.begin("second");
        cache.finish_ready("second", second_generation, request("second"), 0, 5);

        let first = match cache.get("first") {
            TransformSnapshotLookup::Ready(lease) => lease,
            _ => panic!("first lease must fit within both budgets"),
        };
        assert!(matches!(
            cache.get("second"),
            TransformSnapshotLookup::LeaseBudgetExceeded
        ));
        {
            let budget = cache
                .active_leases
                .lock()
                .expect("snapshot lease budget mutex");
            assert_eq!(budget.count, 1);
            assert!(
                budget.count < budget.max_count,
                "the count cap must not decide this case"
            );
            assert_eq!(budget.bytes, 5);
        }

        drop(first);
        assert!(matches!(
            cache.get("second"),
            TransformSnapshotLookup::Ready(_)
        ));
    }

    #[derive(Default)]
    struct ProducerState {
        connects: AtomicUsize,
        starts: AtomicUsize,
        start_errors: Mutex<VecDeque<Result<RunHandle, HistorianProducerError>>>,
        binds: AtomicUsize,
        statuses: AtomicUsize,
        await_outputs: AtomicUsize,
        await_timeouts: Mutex<Vec<Duration>>,
        block_output: std::sync::atomic::AtomicBool,
        notify: Notify,
        connect_errors: Mutex<VecDeque<HistorianProducerError>>,
        await_results: Mutex<VecDeque<Result<ProducerOutput, HistorianProducerError>>>,
        outputs: Mutex<VecDeque<String>>,
        next_fact: Mutex<Option<String>>,
        fact_each_run: Mutex<Option<String>>,
        prompts: Mutex<Vec<String>>,
        systems: Mutex<Vec<String>>,
        models: Mutex<Vec<String>>,
        /// The provider session each start ran under, in attempt order.
        sessions: Mutex<Vec<String>>,
        on_await_output: Mutex<Option<Box<dyn FnOnce() + Send>>>,
    }

    struct TestProducerFactory {
        state: Arc<ProducerState>,
    }

    #[async_trait]
    impl HistorianProducerFactory for TestProducerFactory {
        async fn connect(
            &self,
            _project_root: &Path,
        ) -> Result<Box<dyn HistorianProducerDriver + Send>, HistorianProducerError> {
            self.state.connects.fetch_add(1, Ordering::SeqCst);
            if let Some(err) = self
                .state
                .connect_errors
                .lock()
                .expect("connect errors mutex")
                .pop_front()
            {
                return Err(err);
            }
            Ok(Box::new(TestProducer {
                state: Arc::clone(&self.state),
            }))
        }
    }

    struct TestProducer {
        state: Arc<ProducerState>,
    }

    #[async_trait]
    impl HistorianProducerDriver for TestProducer {
        async fn bind_session(&mut self, _session_id: &str) -> Result<(), HistorianProducerError> {
            self.state.binds.fetch_add(1, Ordering::SeqCst);
            Ok(())
        }

        async fn start(
            &mut self,
            session_id: &str,
            system: &str,
            prompt: &str,
            model: &str,
        ) -> Result<RunHandle, HistorianProducerError> {
            let n = self.state.starts.fetch_add(1, Ordering::SeqCst) + 1;
            self.state
                .sessions
                .lock()
                .expect("sessions mutex")
                .push(session_id.to_string());
            self.state
                .prompts
                .lock()
                .expect("prompts mutex")
                .push(prompt.to_string());
            self.state
                .systems
                .lock()
                .expect("systems mutex")
                .push(system.to_string());
            self.state
                .models
                .lock()
                .expect("models mutex")
                .push(model.to_string());
            if let Some(result) = self
                .state
                .start_errors
                .lock()
                .expect("start errors mutex")
                .pop_front()
            {
                return result;
            }
            let one_shot_fact = self.state.next_fact.lock().expect("next fact mutex").take();
            let repeated_fact = self
                .state
                .fact_each_run
                .lock()
                .expect("fact each run mutex")
                .clone();
            let output = match one_shot_fact.or_else(|| {
                repeated_fact.map(|prefix| {
                    let (start, end) = prompt_ordinal_range(prompt).unwrap_or((1, 3));
                    format!("{prefix} {start}-{end}")
                })
            }) {
                Some(fact) => {
                    let (start, end) = prompt_ordinal_range(prompt).unwrap_or((1, 3));
                    historian_output_with_fact(start, end, &fact)
                }
                None => historian_output_for_prompt(prompt),
            };
            self.state
                .outputs
                .lock()
                .expect("outputs mutex")
                .push_back(output);
            Ok(RunHandle {
                run_id: format!("run-{n}"),
            })
        }

        async fn await_output_with_timeout(
            &mut self,
            run_id: &str,
            timeout: Duration,
        ) -> Result<ProducerOutput, HistorianProducerError> {
            self.state
                .await_timeouts
                .lock()
                .expect("await timeouts mutex")
                .push(timeout);
            self.await_output(run_id).await
        }

        async fn await_output(
            &mut self,
            _run_id: &str,
        ) -> Result<ProducerOutput, HistorianProducerError> {
            self.state.await_outputs.fetch_add(1, Ordering::SeqCst);
            if let Some(hook) = self
                .state
                .on_await_output
                .lock()
                .expect("await-output hook mutex")
                .take()
            {
                hook();
            }
            while self.state.block_output.load(Ordering::SeqCst) {
                self.state.notify.notified().await;
            }
            if let Some(result) = self
                .state
                .await_results
                .lock()
                .expect("await results mutex")
                .pop_front()
            {
                return result;
            }
            let text = self
                .state
                .outputs
                .lock()
                .expect("outputs mutex")
                .pop_front()
                .unwrap_or_else(|| historian_output(1, 3, "reattached summary"));
            Ok(ProducerOutput {
                text,
                length_capped: false,
                usage: None,
            })
        }

        async fn status(&mut self, _run_id: &str) -> Result<RunState, HistorianProducerError> {
            self.state.statuses.fetch_add(1, Ordering::SeqCst);
            Ok(RunState::Active)
        }

        async fn cancel(&mut self, _run_id: &str) -> Result<(), HistorianProducerError> {
            Ok(())
        }

        async fn close(&mut self) {}
    }

    fn handler_with_store(
        state: Arc<ProducerState>,
        config: McModuleConfig,
    ) -> (McHandler, Arc<McStore>, tempfile::TempDir, PathBuf) {
        handler_with_store_and_resolver(state, config, Arc::new(MissingSessionResolver))
    }

    fn handler_with_store_and_resolver(
        state: Arc<ProducerState>,
        config: McModuleConfig,
        resolver: Arc<dyn SessionResolver>,
    ) -> (McHandler, Arc<McStore>, tempfile::TempDir, PathBuf) {
        let dir = tempfile::tempdir().unwrap();
        let data_home = dir.path().join("data");
        std::fs::create_dir_all(&data_home).unwrap();
        let store =
            Arc::new(McStore::open(&dev_descriptor_at(data_home.to_str().unwrap())).unwrap());
        let handler = McHandler::with_producer_factory_config_resolver(
            Arc::new(TestProducerFactory { state }),
            config,
            resolver,
        );
        handler.store.set(Arc::clone(&store)).ok().unwrap();
        let project = dir.path().join("project");
        std::fs::create_dir_all(&project).unwrap();
        handler.bind_route(7, binding(project.to_str().unwrap(), "ses"));
        (handler, store, dir, project)
    }

    /// The project key the claim lane resolves for a channel bound to this project
    /// root.
    ///
    /// The lane scopes every op to the caller's project, resolving the key through
    /// the authority route the way the transform that queued the run did. A test
    /// that reads the queue directly has to use the same key, or it looks in the
    /// wrong project and reads an empty queue as "nothing was queued".
    fn lane_project_key(store: &McStore, project_root: &std::path::Path) -> String {
        let route_root = project_root.to_string_lossy().to_string();
        store
            .authority_project_for_route(&route_root, "memories")
            .unwrap()
            .unwrap_or(route_root)
    }

    #[tokio::test(flavor = "current_thread")]
    async fn host_mural_write_family_is_hash_gated_and_claude_code_inherits_by_project() {
        let (handler, store, _dir, project) =
            handler_with_store(Arc::new(ProducerState::default()), default_test_config());
        let project_path = project.to_string_lossy().to_string();
        let mural_a = "data:image/png;base64,YQ==";

        let mut first = request(vec![ck("oc-1", 1, "OpenCode tail")]);
        first["serializer_profile"] = json!("opencode-aisdk");
        first["mural"] = json!({
            "enabled": true,
            "supports_vision": true,
            "data_url": mural_a,
            "content_hash": "mural-a",
        });
        let first_response = call_transform_request(&handler, first).await;
        assert_eq!(first_response["status"], "ok", "{first_response}");
        let artifact = store
            .load_project_mural_artifact(&project_path)
            .unwrap()
            .expect("OpenCode host artifact");
        assert_eq!(artifact.data_url, mural_a.as_bytes());
        assert_eq!(artifact.content_hash, "mural-a");

        let mut same_hash = request(vec![ck("oc-1", 1, "OpenCode tail")]);
        same_hash["serializer_profile"] = json!("opencode-aisdk");
        same_hash["render_config"] = json!("cfg1");
        same_hash["mural"] = json!({
            "enabled": true,
            "supports_vision": true,
            "data_url": "data:image/png;base64,c2FtZS1oYXNoLWRyaWZ0",
            "content_hash": "mural-a",
        });
        let same_hash_response = call_transform_request(&handler, same_hash).await;
        assert_eq!(same_hash_response["status"], "ok", "{same_hash_response}");
        assert_eq!(
            store
                .load_project_mural_artifact(&project_path)
                .unwrap()
                .expect("hash-gated artifact"),
            artifact,
        );

        handler.bind_route(
            7,
            binding_with_harness(project.to_str().unwrap(), "claude-code", "cc-ses"),
        );
        let mut claude_code = request(vec![ck("cc-1", 1, "Claude Code tail")]);
        claude_code["serializer_profile"] = json!("claude-code-anthropic");
        claude_code["session_id"] = json!("cc-ses");
        claude_code["mural"] = json!({
            "enabled": true,
            "supports_vision": true,
            "data_url": "data:image/png;base64,dW50cnVzdGVkLWNjLWJ5dGVz",
            "content_hash": "untrusted-cc-hash",
        });
        let claude_code_response = call_transform_request(&handler, claude_code).await;
        assert_eq!(
            claude_code_response["status"], "ok",
            "{claude_code_response}"
        );
        let response_bytes = serde_json::to_string(&claude_code_response).unwrap();
        assert!(response_bytes.contains(mural_a));
        assert!(!response_bytes.contains("dW50cnVzdGVkLWNjLWJ5dGVz"));
    }

    #[test]
    fn claude_code_config_controls_fill_request_without_changing_default_request_bytes() {
        let value = json!({
            "kind": "transform",
            "v": 2,
            "serializer_profile": "claude-code-anthropic",
            "session_id": "config-controls",
            "render_config": "cfg",
            "messages": []
        });
        let mut default_request: TransformRequest = serde_json::from_value(value.clone()).unwrap();
        assert!(default_request.channel2_delivered_id.is_none());
        let before = serde_json::to_vec(&default_request).unwrap();
        assert!(
            serde_json::from_slice::<Value>(&before)
                .unwrap()
                .get("channel2_delivered_id")
                .is_none(),
            "an absent delivery echo must remain absent on the compatibility wire"
        );
        apply_claude_code_config_controls(
            &mut default_request,
            &McModuleConfig::default(),
            Some(SerializerProfile::ClaudeCodeAnthropic),
        );
        assert_eq!(serde_json::to_vec(&default_request).unwrap(), before);

        let mut echoed_value = value.clone();
        echoed_value["channel2_delivered_id"] = json!("directive-1");
        let echoed_request: TransformRequest = serde_json::from_value(echoed_value).unwrap();
        assert_eq!(
            echoed_request.channel2_delivered_id.as_deref(),
            Some("directive-1")
        );

        let mut configured = McModuleConfig::default();
        configured.auto_search.enabled = false;
        configured.auto_search.score_threshold = 0.8;
        configured.auto_search.min_prompt_chars = 42;
        configured.caveman.enabled = true;
        configured.caveman.min_size = 900;
        configured.prompt_surface_guidance_override =
            Some("## Magic Context\n\nTrusted route guidance.".to_string());
        apply_claude_code_config_controls(
            &mut default_request,
            &configured,
            Some(SerializerProfile::ClaudeCodeAnthropic),
        );
        assert!(!default_request.auto_search_enabled);
        assert_eq!(default_request.auto_search_score_threshold, 0.8);
        assert_eq!(default_request.auto_search_min_prompt_chars, 42);
        assert!(default_request.caveman_enabled);
        assert_eq!(default_request.caveman_min_chars, 900);
        assert_eq!(
            default_request.prompt_surface_guidance_override.as_deref(),
            Some("## Magic Context\n\nTrusted route guidance.")
        );

        let mut open_code_request: TransformRequest = serde_json::from_value(value).unwrap();
        open_code_request.serializer_profile = "opencode-aisdk".to_string();
        let unchanged = open_code_request.clone();
        apply_claude_code_config_controls(
            &mut open_code_request,
            &configured,
            Some(SerializerProfile::OpencodeAiSdk),
        );
        assert_eq!(
            serde_json::to_vec(&open_code_request).unwrap(),
            serde_json::to_vec(&unchanged).unwrap()
        );
    }

    #[tokio::test]
    async fn cc_dispatch_resolves_model_threshold_and_keeps_host_override_authoritative() {
        let mut config = default_test_config();
        config.execute_threshold_user_config = Some(scheduler::ExecuteThresholdConfig::ByModel(
            [
                ("default".to_string(), 75.0),
                ("openai/gpt-6-astra".to_string(), 85.0),
            ]
            .into_iter()
            .collect(),
        ));
        config.execute_threshold_user_configured = true;
        let (handler, _store, _dir, project) =
            handler_with_store(Arc::new(ProducerState::default()), config.clone());
        let mut route = binding(project.to_str().unwrap(), "ses");
        route.config = config;
        handler.bind_route(7, route.clone());
        for (model, usage, host, expected) in [
            ("anthropic/claude-sonnet-5", 70_000, None, "defer"),
            ("anthropic/claude-sonnet-5", 70_000, Some(65), "execute"),
            ("openai/gpt-6-astra-fast", 80_000, None, "defer"),
        ] {
            let mut wire = request(vec![ck("tail", 1, "raw tail")]);
            wire["serializer_profile"] = json!("claude-code-anthropic");
            wire["model_key"] = json!(model);
            handler.record_response_observation("ses", now_ms());
            wire["usage"] =
                json!({"current_total_input_tokens": usage, "context_limit_tokens": 100_000});
            if let Some(host) = host {
                wire["effective_execute_threshold"] = json!(host);
            }
            let response = call_transform_request(&handler, wire).await;
            assert_eq!(response["scheduler_decision"], expected, "{response}");
        }
        assert!(handler.threshold_logged_routes.lock().unwrap().contains(&7));
        handler.bind_route(7, route);
        assert!(!handler.threshold_logged_routes.lock().unwrap().contains(&7));
    }

    #[test]
    fn wire_execute_threshold_overrides_config_and_absence_preserves_fallback_both_directions() {
        fn decision(wire_threshold: Option<f64>, config_threshold: f64) -> scheduler::BaseDecision {
            let mut request = json!({
                "kind": "transform",
                "v": 2,
                "serializer_profile": "owned-llmrunner",
                "session_id": "threshold-wire",
                "render_config": "cfg",
                "messages": []
            });
            if let Some(threshold) = wire_threshold {
                request["effective_execute_threshold"] = json!(threshold);
            }
            let parsed: TransformRequest = serde_json::from_value(request).unwrap();
            scheduler::should_execute(
                &scheduler::SchedulerConfig {
                    execute_threshold_percentage: scheduler::ExecuteThresholdConfig::Percentage(
                        parsed.execute_threshold_or(config_threshold),
                    ),
                    execute_threshold_tokens: None,
                },
                &scheduler::SessionMeta {
                    last_response_time_ms: 100,
                    cache_ttl: "5m".to_string(),
                },
                &scheduler::ContextUsage {
                    percentage: 60.0,
                    input_tokens: 60_000.0,
                    hard_wall_percentage: None,
                },
                100,
                None,
                Some(100_000.0),
            )
        }

        assert_eq!(decision(Some(50.0), 70.0), scheduler::BaseDecision::Execute);
        assert_eq!(decision(None, 70.0), scheduler::BaseDecision::Defer);
        assert_eq!(decision(Some(70.0), 50.0), scheduler::BaseDecision::Defer);
        assert_eq!(decision(None, 50.0), scheduler::BaseDecision::Execute);
    }

