    fn big_messages_from(start_ordinal: u64) -> Vec<CkIngressMessage> {
        (0..80)
            .map(|idx| {
                let ordinal = start_ordinal + idx;
                ck(
                    &format!("m{ordinal}"),
                    ordinal,
                    &format!("message {ordinal} {}", "word ".repeat(800)),
                )
            })
            .collect()
    }

    fn big_messages() -> Vec<CkIngressMessage> {
        big_messages_from(1)
    }

    fn zero_based_messages_with_system_lead() -> Vec<CkIngressMessage> {
        let mut messages = vec![ck_with_role("m0", 0, "system", "identity lead")];
        messages.extend((1..=80).map(|ordinal| {
            ck(
                &format!("m{ordinal}"),
                ordinal,
                &format!("message {ordinal} {}", "word ".repeat(800)),
            )
        }));
        messages
    }

    fn request_with_usage(
        messages: Vec<CkIngressMessage>,
        current_total_input_tokens: u64,
        context_limit_tokens: u64,
    ) -> Value {
        json!({
            "kind": "transform",
            "v": 2,
            "serializer_profile": "owned-llmrunner",
            "session_id": "ses",
            "render_config": "cfg0",
            "usage": ModuleUsage {
                current_total_input_tokens,
                context_limit_tokens,
                ..ModuleUsage::default()
            },
            "messages": messages,
            // The host sends its resolved historian chain with every transform.
            "historian_model_chain": [TEST_HISTORIAN_MODEL],
        })
    }

    const TEST_HISTORIAN_MODEL: &str = "test/model";

    fn request(messages: Vec<CkIngressMessage>) -> Value {
        request_with_usage(messages, 45_000, 50_000)
    }

    fn transform_request(
        messages: Vec<CkIngressMessage>,
        current_total_input_tokens: u64,
        context_limit_tokens: u64,
    ) -> TransformRequest {
        serde_json::from_value(request_with_usage(
            messages,
            current_total_input_tokens,
            context_limit_tokens,
        ))
        .unwrap()
    }

    async fn call_transform_request(handler: &McHandler, request: Value) -> Value {
        call_transform_request_on_channel(handler, 7, request).await
    }

    async fn call_transform_request_on_channel(
        handler: &McHandler,
        channel: u16,
        request: Value,
    ) -> Value {
        match handler.handle_transform_for_test(channel, request).await {
            HandlerOutcome::Response(bytes) => serde_json::from_slice(&bytes).unwrap(),
            other => panic!("unexpected handler outcome: {other:?}"),
        }
    }

    async fn call_transform_outcome(handler: &McHandler, request: Value) -> HandlerOutcome {
        handler.handle_transform_for_test(7, request).await
    }

    async fn call_dispatch_request(handler: &McHandler, request: Value) -> Value {
        call_dispatch_request_on_channel(handler, 7, request).await
    }

    async fn call_dispatch_request_on_channel(
        handler: &McHandler,
        channel: u16,
        request: Value,
    ) -> Value {
        match handler.dispatch_value(channel, request).await {
            HandlerOutcome::Response(bytes) => serde_json::from_slice(&bytes).unwrap(),
            other => panic!("unexpected handler outcome: {other:?}"),
        }
    }

    fn error_frame(outcome: HandlerOutcome) -> (String, String) {
        match outcome {
            HandlerOutcome::Error { code, message } => (code, message),
            other => panic!("expected error outcome, got {other:?}"),
        }
    }

    fn error_code(outcome: HandlerOutcome) -> String {
        error_frame(outcome).0
    }

    async fn call_facade(handler: &McHandler, name: &str, arguments: Value) -> HandlerOutcome {
        call_facade_on_channel(handler, 7, name, arguments).await
    }

    async fn call_facade_on_channel(
        handler: &McHandler,
        channel: u16,
        name: &str,
        arguments: Value,
    ) -> HandlerOutcome {
        handler
            .dispatch_value(channel, json!({ "name": name, "arguments": arguments }))
            .await
    }

    fn tool_body(outcome: HandlerOutcome) -> Value {
        match outcome {
            HandlerOutcome::Response(bytes) => serde_json::from_slice(&bytes).unwrap(),
            other => panic!("expected tool response, got {other:?}"),
        }
    }

    fn tool_is_error(outcome: HandlerOutcome) -> bool {
        tool_body(outcome)["isError"].as_bool().unwrap_or(false)
    }

    fn tool_text(outcome: HandlerOutcome) -> String {
        tool_body(outcome)["content"][0]["text"]
            .as_str()
            .unwrap()
            .to_string()
    }

    fn insert_memory(
        store: &McStore,
        project: &str,
        category: &str,
        content: &str,
        now: i64,
    ) -> i64 {
        let id = store
            .insert_memory(InsertMemoryInput {
                project_path: project,
                route_project_root: None,
                category,
                content,
                source_session_id: Some(project),
                source_type: Some("test"),
                importance: Some(50),
                expires_at: None,
                metadata_json: None,
                now_ms: now,
            })
            .unwrap();
        store
            .acknowledge_host_memory_ids(
                project,
                &[HostMemoryIdentityAck {
                    module_row_id: id,
                    host_row_id: id,
                }],
            )
            .unwrap();
        id
    }

    fn activate_module_authority(
        store: &McStore,
        context_store_uuid: &str,
        identity: &str,
        route_project_root: &str,
        domain: &str,
    ) {
        let preparing = store
            .authority_begin_prepare(context_store_uuid, identity, domain)
            .unwrap();
        let checksum = store
            .authority_seed_checksum(context_store_uuid, identity, domain)
            .unwrap();
        store
            .authority_verify_prepare(
                context_store_uuid,
                identity,
                domain,
                preparing.generation,
                &checksum,
                &checksum,
            )
            .unwrap();
        let module = store
            .authority_ack_prepare(context_store_uuid, identity, domain, preparing.generation)
            .unwrap();
        assert_eq!(module.state, "MODULE");
        store
            .bind_authority_route(context_store_uuid, identity, route_project_root)
            .unwrap();
    }

    fn seed_workspace(store: &McStore, own: &str, foreign: &str) {
        store
            .seed_workspace_member("ws", own, "[\"CONSTRAINTS\"]")
            .unwrap();
        store
            .seed_workspace_member("ws", foreign, "[\"CONSTRAINTS\"]")
            .unwrap();
    }

    fn synthetic_text(response: &Value, index: usize) -> String {
        response["ck_messages"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|message| message["meta"]["synthetic"] == json!(true))
            .nth(index)
            .and_then(|message| message["content"][0]["kind"]["text"].as_str())
            .unwrap_or_default()
            .to_string()
    }

    async fn call_transform(handler: &McHandler, messages: Vec<CkIngressMessage>) -> Value {
        call_transform_request(handler, request(messages)).await
    }

    #[tokio::test(flavor = "current_thread")]
    async fn cc_inherits_oc_project_mural_on_a_natural_hard_without_defer_first_apply() {
        let (handler, store, _dir, project) =
            handler_with_store(Arc::new(ProducerState::default()), default_test_config());
        handler.bind_route(8, binding(project.to_str().unwrap(), "cc-mural"));
        let messages = vec![ck("tail", 1, "raw")];
        let mural_a = json!({
            "enabled": true,
            "supports_vision": true,
            "data_url": "data:image/png;base64,YQ==",
            "content_hash": "mural-a",
        });
        let mural_b = json!({
            "enabled": true,
            "supports_vision": true,
            "data_url": "data:image/png;base64,Yg==",
            "content_hash": "mural-b",
        });

        let mut oc_request = request(messages.clone());
        oc_request["serializer_profile"] = json!("opencode-aisdk");
        oc_request["mural"] = mural_a;
        let oc_first = call_transform_request_on_channel(&handler, 7, oc_request.clone()).await;
        assert_eq!(oc_first["action"], "HARD", "{oc_first}");
        assert_eq!(
            store
                .load_project_mural_artifact(project.to_str().unwrap())
                .unwrap()
                .unwrap()
                .content_hash,
            "mural-a"
        );

        let mut cc_request = request(messages);
        cc_request["serializer_profile"] = json!("claude-code-anthropic");
        cc_request["session_id"] = json!("cc-mural");
        let cc_first = call_transform_request_on_channel(&handler, 8, cc_request.clone()).await;
        assert_eq!(cc_first["action"], "HARD", "{cc_first}");
        assert_eq!(
            serde_json::to_vec(&oc_first["ck_messages"][0]).unwrap(),
            serde_json::to_vec(&cc_first["ck_messages"][0]).unwrap(),
            "the same project artifact must compose the same frozen m0 bytes for OC and CC"
        );

        oc_request["mural"] = mural_b;
        let oc_deferred = call_transform_request_on_channel(&handler, 7, oc_request).await;
        assert_eq!(oc_deferred["action"], "SOFT+", "{oc_deferred}");
        assert_eq!(
            store
                .load_project_mural_artifact(project.to_str().unwrap())
                .unwrap()
                .unwrap()
                .content_hash,
            "mural-b"
        );

        let cc_deferred = call_transform_request_on_channel(&handler, 8, cc_request.clone()).await;
        assert_eq!(cc_deferred["action"], "SOFT+", "{cc_deferred}");
        assert_eq!(
            serde_json::to_vec(&cc_deferred["ck_messages"]).unwrap(),
            serde_json::to_vec(&cc_first["ck_messages"]).unwrap(),
            "a newly inherited artifact must wait for CC's next natural HARD"
        );

        cc_request["render_config"] = json!("cfg1");
        let cc_refolded = call_transform_request_on_channel(&handler, 8, cc_request).await;
        assert_eq!(cc_refolded["action"], "HARD", "{cc_refolded}");
        assert_eq!(
            cc_refolded["ck_messages"][0]["content"][1]["kind"]["source"]["url"],
            "data:image/png;base64,Yg=="
        );
        assert!(
            store
                .load("cc-mural")
                .unwrap()
                .meta
                .last_render_config
                .contains("mural-b"),
            "the inherited content identity must ride the HARD render fold"
        );
    }

