    #[tokio::test(flavor = "current_thread")]
    async fn handler_delta_d5_lineage_descent_forces_full_projection() {
        let target = "projection-lineage-target";
        let source = "projection-lineage-source";
        let resolver = FakeSessionResolver::with(&[
            (target, FakeResolve::Hit(target.to_string())),
            (source, FakeResolve::Hit(source.to_string())),
        ]);
        let (handler, store, _dir, project) = handler_with_store_and_resolver(
            Arc::new(ProducerState::default()),
            default_test_config(),
            resolver,
        );
        handler.bind_route(7, binding(project.to_str().unwrap(), target));
        handler.bind_route(8, binding(project.to_str().unwrap(), source));
        let source_messages = (1..=10)
            .map(|ordinal| {
                ck(
                    &format!("prior-{ordinal}"),
                    ordinal,
                    &format!("turn {ordinal}"),
                )
            })
            .collect::<Vec<_>>();
        let source_request =
            native_cache_request(source, source_messages, Vec::new(), "lineage-source-fp");
        let source_response = call_transform_request_on_channel(
            &handler,
            8,
            serde_json::to_value(source_request).unwrap(),
        )
        .await;
        assert_eq!(source_response["status"], "ok", "{source_response}");
        store
            .append_compartments(
                source,
                &[
                    stored_comp(1, 1, 3, "prior-3", "history one through three"),
                    stored_comp(2, 4, 6, "prior-6", "history four through six"),
                ],
            )
            .unwrap();
        let project_path = project.to_str().unwrap();
        let seeded_note_ids = store
            .seed_authority_rows(
                "context-db",
                project_path,
                "notes",
                &[AuthoritySeedRow {
                    source_row_id: 52,
                    snapshot: json!({
                        "type": "session",
                        "project_path": project_path,
                        "session_id": source,
                        "content": "compiled note inherited by the successor",
                        "status": "active",
                        "surface_condition": "when descent completes",
                        "compiled_provider": "retina-local-fs",
                        "compiled_config": "{\"kind\":\"path_exists\",\"path\":\"src/lib.rs\"}",
                        "compiled_at": 5200,
                        "compile_status": "compiled",
                        "status_version": 3,
                        "created_at": 5100,
                        "updated_at": 5200,
                    }),
                }],
            )
            .unwrap();
        let source_note = store
            .get_note_by_id(project_path, source, seeded_note_ids[0])
            .unwrap()
            .unwrap();
        assert_eq!(
            source_note.compiled_provider.as_deref(),
            Some("retina-local-fs")
        );
        assert_eq!(source_note.compiled_at, Some(5200));
        let source_epoch = store.load(source).unwrap().meta.revert_epoch;
        let summary = "This session is being continued from a previous conversation.\n\nSummary:\nDurable summary alpha\n\nFull transcript: /tmp/session.jsonl";
        let compaction_user = CkIngressMessage {
            mid: "lineage-summary".to_string(),
            ordinal: 1,
            ck: CkWireMessage::from_parts(
                "user",
                vec![
                    CkWireBlock::bare(CkKind::Text {
                        text: "<system-reminder>Today's date: 2026-08-10</system-reminder>"
                            .to_string(),
                    }),
                    CkWireBlock::bare(CkKind::Text {
                        text: summary.to_string(),
                    }),
                ],
                None,
                ProviderExtras::new(),
                HarnessMeta {
                    harness_id: Some("lineage-summary".to_string()),
                    ..Default::default()
                },
            ),
        };
        let initial_messages = vec![
            compaction_user,
            ck_with_role("lineage-tail", 2, "assistant", "continued answer"),
        ];
        let configure_lineage = |request: &mut TransformRequest, subagent: bool| {
            request.lineage_switched = true;
            request.is_subagent = subagent;
            request.descent_edge_id = 101;
            request.prior_conversation_key = source.to_string();
            request.prior_epoch = source_epoch;
            request.new_epoch = source_epoch.saturating_add(1);
            request.constituents = vec![(
                source.to_string(),
                target.to_string(),
                source_epoch.saturating_add(1),
            )];
            request.compaction_observed = true;
        };
        let mut subagent = native_cache_request(
            target,
            initial_messages.clone(),
            Vec::new(),
            "lineage-target-fp-1",
        );
        configure_lineage(&mut subagent, true);
        let passthrough =
            call_transform_request(&handler, serde_json::to_value(subagent).unwrap()).await;
        assert_eq!(passthrough["status"], "ok", "{passthrough}");

        let mut descent = native_cache_request(
            target,
            vec![ck_with_role(
                "lineage-tail",
                2,
                "assistant",
                "continued answer changed",
            )],
            Vec::new(),
            "lineage-target-fp-2",
        );
        configure_lineage(&mut descent, false);
        descent.tail_delta = Some(json!({
            "after": "lineage-target-fp-1",
            "replace_from": 1,
            "native_replace_from": 0,
        }));
        let descended =
            call_transform_request(&handler, serde_json::to_value(descent).unwrap()).await;
        assert_eq!(descended["status"], "ok", "{descended}");
        assert_eq!(descended["lineage_descent_disposition"], "descended");
        assert_eq!(descended["lineage_switch_consumed_id"], 101);
        assert_eq!(descended["timings"]["projection_reused_messages"], 0);
        assert_eq!(descended["timings"]["projection_projected_messages"], 2);
        assert!(store.load(target).unwrap().meta.descent_completed);

        let inherited_notes = store
            .search_notes_like(project_path, target, "compiled note inherited")
            .unwrap();
        assert_eq!(inherited_notes.len(), 1);
        let inherited = store
            .get_note_by_id(project_path, target, inherited_notes[0].id)
            .unwrap()
            .unwrap();
        assert_ne!(inherited.id, source_note.id);
        assert_eq!(
            inherited.compiled_provider.as_deref(),
            Some("retina-local-fs")
        );
        assert_eq!(
            inherited.compiled_config.as_deref(),
            Some("{\"kind\":\"path_exists\",\"path\":\"src/lib.rs\"}")
        );
        assert_eq!(inherited.compiled_at, Some(5200));
        assert_eq!(inherited.compile_status.as_deref(), Some("compiled"));
        let successor_facade = tool_text(
            call_facade_on_channel(&handler, 7, "ctx_note", json!({ "action": "read" })).await,
        );
        assert!(successor_facade.contains("compiled note inherited by the successor"));
    }

    #[tokio::test(flavor = "current_thread")]
    async fn handler_delta_normalization_matches_full_when_reserved_todo_starts_at_frontier() {
        let (cached_handler, cached_store, _cached_dir, _cached_project) =
            handler_with_store(Arc::new(ProducerState::default()), default_test_config());
        let (control_handler, control_store, _control_dir, _control_project) =
            handler_with_store(Arc::new(ProducerState::default()), default_test_config());
        let initial_messages = vec![
            ck("todo-prefix", 1, "prefix"),
            assistant_tool_call("call-ordinary", 2),
            tool_result("result-ordinary", 3, "ordinary"),
        ];
        for handler in [&cached_handler, &control_handler] {
            let request = native_cache_request(
                "ses",
                initial_messages.clone(),
                Vec::new(),
                "todo-normalize-fp-1",
            );
            let response =
                call_transform_request(handler, serde_json::to_value(request).unwrap()).await;
            assert_eq!(response["status"], "ok", "{response}");
        }

        let pair = injection::build_synthetic_todo_pair(
            r#"[{"content":"pin normalization","status":"in_progress","priority":"high"}]"#,
        )
        .unwrap();
        let mut call = pair.assistant_msg;
        call.meta.synthetic = false;
        call.meta.harness_id = Some("todo-reserved-call".to_string());
        let mut result = pair.tool_msg;
        result.meta.synthetic = false;
        result.meta.harness_id = Some("todo-reserved-result".to_string());
        let changed_messages = vec![
            ck("todo-prefix", 1, "prefix"),
            CkIngressMessage {
                mid: "todo-reserved-call".to_string(),
                ordinal: 2,
                ck: call,
            },
            CkIngressMessage {
                mid: "todo-reserved-result".to_string(),
                ordinal: 3,
                ck: result,
            },
        ];
        let mut delta = native_cache_request(
            "ses",
            changed_messages[1..].to_vec(),
            Vec::new(),
            "todo-normalize-fp-2",
        );
        delta.tail_delta = Some(json!({
            "after": "todo-normalize-fp-1",
            "replace_from": 1,
            "native_replace_from": 0,
        }));
        let cached =
            call_transform_request(&cached_handler, serde_json::to_value(delta).unwrap()).await;
        let full = call_transform_request(
            &control_handler,
            serde_json::to_value(native_cache_request(
                "ses",
                changed_messages,
                Vec::new(),
                "todo-normalize-fp-2",
            ))
            .unwrap(),
        )
        .await;
        assert_eq!(cached["status"], "ok", "{cached}");
        assert_eq!(cached["timings"]["projection_reused_messages"], 1);
        assert_eq!(cached["ck_messages"], full["ck_messages"]);
        let cached_epoch = cached_store.load("ses").unwrap().meta.revert_epoch;
        let full_epoch = control_store.load("ses").unwrap().meta.revert_epoch;
        let cached_projection = cached_handler
            .projections
            .lock()
            .unwrap()
            .snapshot("ses", cached_epoch)
            .expect("cached projection")
            .projection;
        let full_projection = control_handler
            .projections
            .lock()
            .unwrap()
            .snapshot("ses", full_epoch)
            .expect("full projection")
            .projection;
        assert_eq!(cached_projection, full_projection);
        assert!(cached_projection
            .blocks
            .iter()
            .skip(1)
            .all(|block| block.synthetic));
    }

    /// When a module call fails, the host serves its last-known-good replay followed by the raw
    /// OpenCode tail. An assistant that was newest only on that failed pass therefore reached the
    /// provider verbatim, signed reasoning included, but the module never saw it as newest and so
    /// never registered a keep for it. The next deferred passes, where that assistant is already
    /// demoted, must still replay the bytes the provider cached, until a priced pass.
    #[tokio::test(flavor = "current_thread")]
    async fn defer_after_failed_pass_holds_fallback_served_signed_reasoning_until_priced_pass() {
        let producer = Arc::new(ProducerState::default());
        let (handler, store, _dir, _project) = handler_with_store(producer, default_test_config());
        let mut native = vec![
            json!({"info":{"id":"user","role":"user"},"parts":[{"type":"text","text":"start"}]}),
            json!({"info":{"id":"previous","role":"assistant"},"parts":[{"type":"text","text":"earlier step"}]}),
        ];
        let make_request = |native: &Vec<Value>| {
            let decoded = codec::decode_opencode(native);
            let mut req = request(decoded.messages);
            req["serializer_profile"] = json!("opencode-aisdk");
            req["serve_native"] = json!(true);
            req["tool_present"] = json!(true);
            req["provider_id"] = json!("anthropic");
            req["model_key"] = json!("claude-fable-5-1");
            req["mid_turn"] = json!(false);
            req["native_messages"] = json!(native);
            req
        };
        let step = |index: usize| {
            json!({"info":{"id":format!("step-{index}"),"role":"assistant"},"parts":[
                {"type":"reasoning","text":format!("adaptive step {index}"),"metadata":{"anthropic":{"signature":format!("signature-{index}")}}},
                {"type":"tool","tool":"work","callID":format!("call-{index}"),"state":{"status":"completed","input":{"action":"show"},"output":format!("done {index}")}}
            ]})
        };
        let warm = call_transform_request(&handler, make_request(&native)).await;
        assert_eq!(warm["action"], "HARD");
        // The failed pass: the module is never consulted, and the host serves the previous
        // module output plus step-0 exactly as OpenCode stored it.
        native.push(step(0));
        let mut fallback_served = warm["native_messages"].as_array().unwrap().clone();
        fallback_served.push(step(0));
        let hash = |messages: &[Value]| -> String {
            format!(
                "{:x}",
                Sha256::digest(serde_json::to_vec(messages).unwrap())
            )
        };
        let mut previous = fallback_served;
        for index in 1..3 {
            native.push(step(index));
            let deferred = call_transform_request(&handler, make_request(&native)).await;
            assert_eq!(deferred["action"], "SOFT+", "{deferred}");
            let served = deferred["native_messages"].as_array().unwrap();
            assert!(served.len() > previous.len());
            assert_eq!(
                hash(&served[..previous.len()]),
                hash(&previous),
                "a defer after a failed pass must not rewrite the fallback-served prefix: {:?}",
                served
                    .iter()
                    .zip(&previous)
                    .enumerate()
                    .filter(|(_, (new, old))| new != old)
                    .collect::<Vec<_>>()
            );
            previous = served.clone();
        }
        assert!(store
            .load("ses")
            .unwrap()
            .core
            .frozen_units
            .iter()
            .any(|unit| unit.key == "strip:native_reasoning_keep:step-0"));
        let mut priced_request = make_request(&native);
        priced_request["render_config"] = json!("independent-priced-config-change");
        let priced = call_transform_request(&handler, priced_request).await;
        assert_eq!(priced["action"], "HARD");
        assert!(!store
            .load("ses")
            .unwrap()
            .core
            .frozen_units
            .iter()
            .any(|unit| unit.key == "strip:native_reasoning_keep:step-0"));
    }

    #[tokio::test(flavor = "current_thread")]
    async fn post_hard_defer_preserves_demoted_native_thinking_until_priced_pass() {
        let producer = Arc::new(ProducerState::default());
        let (handler, store, _dir, _project) = handler_with_store(producer, default_test_config());
        let mut native = vec![
            json!({"info":{"id":"user","role":"user"},"parts":[{"type":"text","text":"start"}]}),
            json!({"info":{"id":"previous","role":"assistant"},"parts":[{"type":"text","text":"earlier step"}]}),
        ];
        let make_request = |native: &Vec<Value>, model: &str| {
            let decoded = codec::decode_opencode(native);
            let mut req = request(decoded.messages);
            req["serializer_profile"] = json!("opencode-aisdk");
            req["serve_native"] = json!(true);
            req["tool_present"] = json!(true);
            req["provider_id"] = json!("anthropic");
            req["model_key"] = json!(model);
            req["mid_turn"] = json!(false);
            req["native_messages"] = json!(native);
            req
        };
        let warm = call_transform_request(&handler, make_request(&native, "claude-opus-5")).await;
        assert_eq!(warm["action"], "HARD");
        let thinking = json!({"type":"reasoning","text":"signed thinking", "metadata":{"anthropic":{"signature":"fixture-signature"}}});
        native.push(json!({"info":{"id":"thinking","role":"assistant"},"parts":[
            thinking.clone(), {"type":"text","text":"dispatching"},
            {"type":"tool","tool":"work","callID":"call-thinking","state":{"status":"completed","input":{"action":"run"},"output":"dispatched"}}
        ]}));
        native.push(json!({"info":{"id":"continue","role":"user"},"parts":[{"type":"text","text":"continue"}]}));
        let hard =
            call_transform_request(&handler, make_request(&native, "claude-fable-5-1")).await;
        assert_eq!(hard["action"], "HARD");
        let mut previous = hard["native_messages"].as_array().unwrap().clone();
        let hash = |messages: &[Value]| -> String {
            format!(
                "{:x}",
                Sha256::digest(serde_json::to_vec(messages).unwrap())
            )
        };
        for step in 0..2 {
            native.push(json!({"info":{"id":format!("step-{step}"),"role":"assistant"},"parts":[
                {"type":"reasoning","text":format!("adaptive step {step}"),"metadata":{"anthropic":{"signature":format!("signature-{step}")}}},
                {"type":"tool","tool":"work","callID":format!("call-{step}"),"state":{"status":"completed","input":{"action":"show"},"output":"done"}}
            ]}));
            let deferred =
                call_transform_request(&handler, make_request(&native, "claude-fable-5-1")).await;
            assert_eq!(deferred["action"], "SOFT+");
            let served = deferred["native_messages"].as_array().unwrap();
            assert!(served.len() > previous.len());
            assert_eq!(
                hash(&served[..previous.len()]),
                hash(&previous),
                "demotion must not rewrite the served prefix: {:?}",
                served
                    .iter()
                    .zip(&previous)
                    .enumerate()
                    .filter(|(_, (new, old))| new != old)
                    .collect::<Vec<_>>()
            );
            let target = served
                .iter()
                .find(|message| message["info"]["id"] == "thinking")
                .unwrap();
            assert_eq!(target["parts"][0], thinking);
            assert!(!store
                .load("ses")
                .unwrap()
                .core
                .frozen_units
                .iter()
                .any(|unit| unit.key == "strip:merged_reasoning:thinking"));
            previous = served.clone();
        }
        let mut priced_request = make_request(&native, "claude-fable-5-1");
        priced_request["render_config"] = json!("independent-priced-config-change");
        let priced = call_transform_request(&handler, priced_request).await;
        assert_eq!(priced["action"], "HARD");
        let target = priced["native_messages"]
            .as_array()
            .unwrap()
            .iter()
            .find(|message| message["info"]["id"] == "thinking")
            .unwrap();
        assert!(target["parts"]
            .as_array()
            .unwrap()
            .iter()
            .all(|part| part["type"] != "reasoning"));
        assert!(store
            .load("ses")
            .unwrap()
            .core
            .frozen_units
            .iter()
            .any(|unit| unit.key == "strip:merged_reasoning:thinking"));
    }

    #[tokio::test(flavor = "current_thread")]
    async fn native_attachment_reuses_transform_tag_baseline_and_preserves_bytes() {
        let producer = Arc::new(ProducerState::default());
        let (handler, store, _dir, _project) = handler_with_store(producer, default_test_config());
        let seeded_tags = (0..55)
            .map(|index| TagMintInput {
                block_id: if index == 0 {
                    "assistant-old#0".to_string()
                } else {
                    format!("history-{index}#0")
                },
                kind: "message".to_string(),
                token_count: 1,
                source_bytes: format!("source-{index}").into_bytes(),
            })
            .collect::<Vec<_>>();
        store.seed_tags_for_test("ses", &seeded_tags, 1).unwrap();

        let mut request = request(vec![
            ck_reasoning("assistant-old", 1, "signed historical thinking"),
            ck("user-new", 100, "new prompt"),
        ]);
        request["serializer_profile"] = json!("opencode-aisdk");
        request["serve_native"] = json!(true);
        request["tool_present"] = json!(true);
        request["provider_id"] = json!("anthropic");
        request["native_messages"] = json!([
            {
                "info": {
                    "id": "assistant-old",
                    "role": "assistant",
                    "providerID": "anthropic",
                    "modelID": "claude-opus-4-8"
                },
                "parts": [{
                    "type": "reasoning",
                    "text": "signed historical thinking",
                    "time": { "start": 1, "end": 2 },
                    "metadata": { "anthropic": { "signature": "signature-assistant-old" } }
                }]
            },
            {
                "info": {
                    "id": "user-new",
                    "role": "user",
                    "model": { "providerID": "anthropic", "modelID": "claude-opus-4-8" }
                },
                "parts": [{ "type": "text", "text": "new prompt" }]
            }
        ]);
        let parsed: TransformRequest = serde_json::from_value(request.clone()).unwrap();
        let actual = call_transform_request(&handler, request).await;
        assert_eq!(actual["status"], "ok");
        let actual_native = actual["native_messages"].as_array().unwrap().clone();
        assert_eq!(
            store.tag_number_query_count_for_test(),
            0,
            "serve_native must reuse transform tag rows instead of issuing a numbers-only scan"
        );
        let preserved_reasoning = actual_native
            .iter()
            .find(|message| message["info"]["id"] == json!("assistant-old"))
            .expect("tagged historical reasoning remains addressable");
        assert_eq!(
            preserved_reasoning["parts"][0],
            json!({
                "type": "reasoning",
                "text": "signed historical thinking",
                "time": { "start": 1, "end": 2 },
                "metadata": { "anthropic": { "signature": "signature-assistant-old" } }
            })
        );

        let mut old_tag_numbers = std::collections::BTreeMap::new();
        for tag in store.load_tags_for_session("ses").unwrap() {
            let message_id = tag
                .block_id
                .split_once('#')
                .map(|(message_id, _)| message_id)
                .unwrap_or(tag.block_id.as_str())
                .to_string();
            old_tag_numbers
                .entry(message_id)
                .and_modify(|number: &mut u64| *number = (*number).max(tag.tag_number as u64))
                .or_insert(tag.tag_number as u64);
        }
        let new_tag_numbers =
            message_tag_numbers(store.load_tag_numbers_for_session("ses").unwrap());
        assert_eq!(new_tag_numbers, old_tag_numbers);

        let loaded = store.load("ses").unwrap();
        let reasoning_clear_units = &loaded.core.frozen_units;
        let mut replay: transform::TransformResponse = serde_json::from_value(actual).unwrap();
        replay.native_messages = None;
        attach_native_messages_with_tags(
            &mut replay,
            &parsed,
            reasoning_clear_units,
            &old_tag_numbers,
            None,
            None,
            false,
        );
        assert_eq!(
            replay
                .native_messages
                .expect("native replay")
                .iter()
                .map(|message| message.as_ref().clone())
                .collect::<Vec<_>>(),
            actual_native
        );
    }

    #[tokio::test(flavor = "current_thread")]
    async fn historian_preflight_reuses_transform_tag_snapshot_and_invalidates_on_generation() {
        const MESSAGE_COUNT: usize = 2_048;
        let producer = Arc::new(ProducerState::default());
        let (handler, store, _dir, _project) = handler_with_store(producer, default_test_config());
        let messages = (1..=MESSAGE_COUNT)
            .map(|ordinal| {
                ck(
                    &format!("m{ordinal}"),
                    ordinal as u64,
                    &format!("source-{ordinal}"),
                )
            })
            .collect::<Vec<_>>();
        let tags = (1..=MESSAGE_COUNT)
            .map(|ordinal| TagMintInput {
                block_id: format!("m{ordinal}#0"),
                kind: "message".to_string(),
                token_count: 1,
                source_bytes: format!("source-{ordinal}").into_bytes(),
            })
            .collect::<Vec<_>>();
        store.seed_tags_for_test("ses", &tags, 1).unwrap();
        let request = request_with_usage(messages, 1_000, 200_000);

        store.reset_tag_payload_query_count_for_test();
        store.reset_state_load_query_count_for_test();
        let cold = call_transform_request(&handler, request.clone()).await;
        assert_eq!(cold["status"], "ok");
        let cold_messages = serde_json::to_vec(&cold["ck_messages"]).unwrap();
        assert_eq!(
            store.tag_payload_query_count_for_test(),
            1,
            "the cold transform is the only full tag payload read"
        );
        assert_eq!(
            store.state_load_query_count_for_test(),
            2,
            "handler entry and historian preflight each take one state snapshot"
        );

        for _ in 0..5 {
            store.reset_tag_payload_query_count_for_test();
            store.reset_state_load_query_count_for_test();
            let warm = call_transform_request(&handler, request.clone()).await;
            let warm_messages = serde_json::to_vec(&warm["ck_messages"]).unwrap();
            assert_eq!(
                Sha256::digest(&warm_messages),
                Sha256::digest(&cold_messages)
            );
            assert!(
                store.tag_payload_query_count_for_test() <= 1,
                "historian preflight must not add a second payload scan even if another parallel test evicts the process cache"
            );
            assert_eq!(store.state_load_query_count_for_test(), 2);
        }

        transform::load_cached_tags(&store, "ses").unwrap();
        store.reset_tag_payload_query_count_for_test();
        store
            .execute_tag_sql_for_test(
                "UPDATE mc_tags SET token_count = 777 \
                 WHERE session_id = 'ses' AND tag_number = 1;",
            )
            .unwrap();
        let refreshed_tags = transform::load_cached_tags(&store, "ses").unwrap();
        assert_eq!(
            store.tag_payload_query_count_for_test(),
            1,
            "a replacement generation must force exactly one new payload read"
        );
        assert_eq!(
            refreshed_tags
                .iter()
                .find(|tag| tag.tag_number == 1)
                .map(|tag| tag.token_count),
            Some(777)
        );

        store.reset_tag_payload_query_count_for_test();
        let invalidated = call_transform_request(&handler, request).await;
        let invalidated_messages = serde_json::to_vec(&invalidated["ck_messages"]).unwrap();
        assert_eq!(
            Sha256::digest(&invalidated_messages),
            Sha256::digest(&cold_messages),
            "cache invalidation may refresh accounting but cannot alter served message bytes"
        );
        assert!(store.tag_payload_query_count_for_test() <= 1);
        // The direct payload-read count is the invalidation oracle: ignoring generation/count/max
        // would leave it at zero and return the stale token count instead of 777.
    }

    #[test]
    #[ignore = "manual 2k-message hot-path timing fixture"]
    fn historian_tag_and_state_snapshot_hot_path_benchmark() {
        const MESSAGE_COUNT: usize = 2_048;
        const SAMPLES: usize = 7;
        let producer = Arc::new(ProducerState::default());
        let (_handler, store, _dir, _project) = handler_with_store(producer, default_test_config());
        let messages = (1..=MESSAGE_COUNT)
            .map(|ordinal| {
                ck(
                    &format!("m{ordinal}"),
                    ordinal as u64,
                    &format!("source-{ordinal}"),
                )
            })
            .collect::<Vec<_>>();
        let parsed = transform_request(messages, 1_000, 200_000);
        let projection = crate::ck_wire::project_messages(&parsed.messages).unwrap();
        let tags = (1..=MESSAGE_COUNT)
            .map(|ordinal| TagMintInput {
                block_id: format!("m{ordinal}#0"),
                kind: "message".to_string(),
                token_count: 1,
                source_bytes: format!("source-{ordinal}").into_bytes(),
            })
            .collect::<Vec<_>>();
        store.seed_tags_for_test("ses", &tags, 1).unwrap();
        let shared_tags = Arc::new(store.load_tags_for_session("ses").unwrap());
        let legacy_cache = Mutex::new(BoundaryTokenCache::new(BOUNDARY_TOKEN_CACHE_BUDGET_BYTES));
        let shared_cache = Mutex::new(BoundaryTokenCache::new(BOUNDARY_TOKEN_CACHE_BUDGET_BYTES));
        for cache in [&legacy_cache, &shared_cache] {
            cache
                .lock()
                .unwrap()
                .prime_from_persisted_tags("ses", shared_tags.as_slice());
            let warmed = boundary_messages(&parsed, &projection, cache);
            cache
                .lock()
                .unwrap()
                .replace("ses", warmed.token_cache_snapshot);
        }

        for _ in 0..SAMPLES {
            let started_at = Instant::now();
            let legacy_tags = store.load_tags_for_session("ses").unwrap();
            legacy_cache
                .lock()
                .unwrap()
                .prime_from_persisted_tags("ses", &legacy_tags);
            let legacy = boundary_messages(&parsed, &projection, &legacy_cache);
            legacy_cache
                .lock()
                .unwrap()
                .replace("ses", legacy.token_cache_snapshot);
            std::hint::black_box(legacy.messages.len());
            eprintln!(
                "mc-pass-timing session=r12-before trigger_boundary_build={:.3}",
                started_at.elapsed().as_secs_f64() * 1_000.0
            );

            let started_at = Instant::now();
            shared_cache
                .lock()
                .unwrap()
                .prime_from_persisted_tags("ses", shared_tags.as_slice());
            let shared = boundary_messages(&parsed, &projection, &shared_cache);
            shared_cache
                .lock()
                .unwrap()
                .replace("ses", shared.token_cache_snapshot);
            std::hint::black_box(shared.messages.len());
            eprintln!(
                "mc-pass-timing session=r12-after trigger_boundary_build={:.3}",
                started_at.elapsed().as_secs_f64() * 1_000.0
            );
        }

        for _ in 0..SAMPLES {
            let started_at = Instant::now();
            std::hint::black_box(store.load("ses").unwrap());
            std::hint::black_box(store.load("ses").unwrap());
            eprintln!(
                "mc-pass-timing session=r07-before handler_state_snapshot={:.3}",
                started_at.elapsed().as_secs_f64() * 1_000.0
            );

            let started_at = Instant::now();
            let snapshot = store.load("ses").unwrap();
            std::hint::black_box((&snapshot, &snapshot));
            eprintln!(
                "mc-pass-timing session=r07-after handler_state_snapshot={:.3}",
                started_at.elapsed().as_secs_f64() * 1_000.0
            );
        }
    }

    #[tokio::test(flavor = "current_thread")]
    async fn live_shaped_opencode_reasoning_clear_attaches_on_the_same_pass() {
        let producer = Arc::new(ProducerState::default());
        let (handler, store, _dir, _project) = handler_with_store(producer, default_test_config());
        let mut request = request(vec![
            ck_reasoning("assistant-old", 1, "signed historical thinking"),
            ck("user-new", 100, "new prompt"),
        ]);
        request["serializer_profile"] = json!("opencode-aisdk");
        request["serve_native"] = json!(true);
        // Empty sentinels require the exact canonical provider identity. Native metadata
        // alone must not broaden that provider gate.
        request["provider_id"] = json!("anthropic");
        request["native_messages"] = json!([
            {
                "info": {
                    "id": "assistant-old",
                    "role": "assistant",
                    "providerID": "anthropic",
                    "modelID": "claude-opus-4-8"
                },
                "parts": [{
                    "type": "reasoning",
                    "text": "signed historical thinking",
                    "time": { "start": 1, "end": 2 },
                    "metadata": { "anthropic": { "signature": "signature-assistant-old" } }
                }]
            },
            {
                "info": {
                    "id": "user-new",
                    "role": "user",
                    "model": { "providerID": "anthropic", "modelID": "claude-opus-4-8" }
                },
                "parts": [{ "type": "text", "text": "new prompt" }]
            }
        ]);

        let parsed: TransformRequest = serde_json::from_value(request.clone()).unwrap();
        assert_eq!(
            SerializerProfile::parse(&parsed.serializer_profile),
            Some(SerializerProfile::OpencodeAiSdk)
        );
        assert_eq!(parsed.provider_id.as_deref(), Some("anthropic"));
        assert_eq!(parsed.clear_reasoning_age, 50);
        assert!(transform::request_accepts_empty_content(&parsed));

        let mut contradictory = parsed.clone();
        contradictory.provider_id = None;
        contradictory.model_key = Some("anthropic/claude-opus".to_string());
        assert!(!transform::request_accepts_empty_content(&contradictory));

        let response = call_transform_request(&handler, request).await;
        assert_eq!(response["status"], "ok");
        assert_eq!(
            store
                .load("ses")
                .unwrap()
                .meta
                .reasoning_cleared_through_ordinal,
            0,
            "untagged reasoning has unknown age and must remain uncleared"
        );
        let old = response["native_messages"]
            .as_array()
            .unwrap()
            .iter()
            .find(|message| message["info"]["id"] == json!("assistant-old"))
            .expect("served assistant must retain its harness id");
        assert_eq!(
            old["parts"][0]["text"],
            json!("signed historical thinking"),
            "untagged reasoning has unknown age and remains byte-preserved"
        );
    }

