    #[tokio::test(flavor = "current_thread")]
    async fn facade_ctx_reduce_ack_validates_unknown_queued_and_protected_tags_without_committing()
    {
        let resolver = FakeSessionResolver::with(&[("ses", FakeResolve::Hit("ses".to_string()))]);
        let (handler, store, _dir, _project) = handler_with_store_and_resolver(
            Arc::new(ProducerState::default()),
            default_test_config(),
            resolver,
        );
        let tag_inputs = (1..=21)
            .map(|number| TagMintInput {
                block_id: format!("m{number}#0"),
                kind: "tool_result".to_string(),
                token_count: 800,
                source_bytes: format!("output {number}").into_bytes(),
            })
            .collect::<Vec<_>>();
        store.seed_tags_for_test("ses", &tag_inputs, 1_000).unwrap();

        let mixed_ack = tool_text(
            call_facade(
                &handler,
                "ctx_reduce",
                json!({ "drop": "1, 21, 99, 100", "command_id": "mixed-delivery" }),
            )
            .await,
        );
        assert!(mixed_ack.contains("drop §1§"));
        assert!(mixed_ack.contains("Held: §21§ is inside the protected working set; it applies once newer work displaces it."));
        assert!(mixed_ack.contains("tags 99, 100 not found"));
        assert!(store.load_pending_agent_drops("ses").unwrap().is_empty());

        // The response observer delivers the same mixed request later. It queues only
        // known tags, leaving acknowledgement validation side-effect free.
        let delivered = handler.handle_agent_drops_value(
            7,
            json!({
                "method": "agent_drops.append",
                "session_id": "ses",
                "drop": "1, 21, 99, 100",
                "command_id": "mixed-delivery",
            }),
        );
        assert_eq!(tool_body(delivered), json!({ "ok": true, "queued": 2 }));
        let pending_after_delivery = store.load_pending_agent_drops("ses").unwrap();
        let retry = handler.handle_agent_drops_value(
            7,
            json!({
                "method": "agent_drops.append",
                "session_id": "ses",
                "drop": "1, 21, 99, 100",
                "command_id": "mixed-delivery",
            }),
        );
        assert_eq!(
            tool_body(retry),
            json!({ "ok": true, "queued": 0, "duplicate": true })
        );
        assert_eq!(
            store.load_pending_agent_drops("ses").unwrap(),
            pending_after_delivery
        );

        let queued_ack =
            tool_text(call_facade(&handler, "ctx_reduce", json!({ "drop": "1, 2, 99" })).await);
        assert!(queued_ack.contains("Held: §2§ is inside the protected working set; it applies once newer work displaces it."), "{queued_ack}");
        assert!(queued_ack.contains("tags 1 already queued"));
        assert!(queued_ack.contains("tags 99 not found"));

        let refused = tool_body(call_facade(&handler, "ctx_reduce", json!({ "drop": "99" })).await);
        assert_eq!(refused["isError"], json!(true));
        assert!(refused["content"][0]["text"]
            .as_str()
            .unwrap()
            .contains("Refused: no valid tags to queue. tags 99 not found"));
        assert_eq!(store.load_pending_agent_drops("ses").unwrap().len(), 2);

        let invalid =
            tool_body(call_facade(&handler, "ctx_reduce", json!({ "drop": "3-1" })).await);
        assert_eq!(invalid["isError"], json!(true));
        assert!(invalid["content"][0]["text"]
            .as_str()
            .unwrap()
            .contains("Invalid range"));
    }

    #[test]
    fn ctx_manifest_schemas_accept_unknown_args_without_advertising_reduced_fields() {
        let manifest = manifest("magic-context");
        let ProviderRole::ToolProvider { tools, .. } = &manifest.provides[0] else {
            panic!("tool provider manifest entry");
        };
        let by_name = tools
            .iter()
            .map(|tool| (tool.name.as_str(), tool))
            .collect::<HashMap<_, _>>();
        let expected_fields = [
            ("ctx_reduce", vec!["drop"]),
            (
                "ctx_memory",
                vec![
                    "action",
                    "category",
                    "content",
                    "id",
                    "ids",
                    "target_id",
                    "source_ids",
                    "reason",
                    "memory_project",
                ],
            ),
            ("ctx_search", vec!["query", "limit", "from", "to"]),
            ("ctx_expand", vec!["start", "end", "verbose", "message"]),
            (
                "ctx_note",
                vec![
                    "action",
                    "content",
                    "note_ids",
                    "limit",
                    "offset",
                    "filter",
                    "surface_condition",
                    "memory_project",
                ],
            ),
        ];

        // ctx_reduce is the one AUTHORIZER-PINNED schema: Thalamus exact-matches
        // the canonical closed shape and fails closed on any deviation, silently
        // disabling the tagging surface. Its imitated-args tolerance lives in the
        // execution unwrap, not the advertised schema. Every other ctx_ tool keeps
        // the open accept-unknown-args posture.
        assert_eq!(
            by_name["ctx_reduce"].schema,
            json!({
                "type": "object",
                "properties": {
                    "drop": {
                        "type": "string",
                        "description": "Tag IDs to drop: \"3-5\", \"1,2,9\", \"1-5,8,12-15\"."
                    }
                },
                "required": ["drop"],
                "additionalProperties": false
            }),
            "ctx_reduce advertised schema must stay byte-canonical (authorizer contract)"
        );

        assert_eq!(
            by_name["ctx_expand"].schema["properties"]["verbose"]["type"],
            json!("boolean"),
            "ctx_expand must advertise verbose range previews"
        );

        for (name, expected) in expected_fields {
            let tool = by_name
                .get(name)
                .unwrap_or_else(|| panic!("missing {name} manifest entry"));
            if name != "ctx_reduce" {
                assert_ne!(
                    tool.schema.get("additionalProperties"),
                    Some(&json!(false)),
                    "{name} must preserve compatibility arguments"
                );
            }
            let properties = tool.schema["properties"]
                .as_object()
                .unwrap_or_else(|| panic!("{name} schema properties"));
            let mut actual = properties.keys().map(String::as_str).collect::<Vec<_>>();
            actual.sort_unstable();
            let mut expected = expected;
            expected.sort_unstable();
            assert_eq!(actual, expected, "{name} advertised fields changed");
            assert!(!properties.contains_key("reduced"));
            assert!(!properties.contains_key("summary"));
        }
    }

