        delta["native_messages"] = json!([]);
        delta["tail_delta"] = json!({
            "after": "fp-m1",
            "replace_from": 1,
            "native_replace_from": 0,
        });
        let response = call_transform_request(&handler, delta).await;
        assert_eq!(response["status"], "ok");
