    #[tokio::test(flavor = "current_thread")]
    async fn defer_keeps_frozen_prefix_divergence_unacknowledged_across_restart_passes() {
        let producer = Arc::new(ProducerState::default());
        let (handler, store, _dir, project) = handler_with_store(producer, default_test_config());
        let request_body = request(vec![ck("m1", 1, "hello")]);
        let initial = call_transform_request(&handler, request_body.clone()).await;
        assert_eq!(initial["status"], "ok", "{initial}");

        let mut loaded = store.load("ses").unwrap();
        let served_fingerprint_before_restart = loaded.meta.served_output_fingerprint.clone();
        let m1 = loaded
            .core
            .frozen_units
            .iter_mut()
            .find(|unit| unit.key == "m1")
            .expect("initial render stores m1");
        m1.frozen_payload.push_str("\nrestart-only drift");
        store
            .commit("ses", loaded.row_version, &loaded.core, &loaded.meta)
            .unwrap();

        let restarted = McHandler::with_producer_factory_config_resolver(
            Arc::new(TestProducerFactory {
                state: Arc::new(ProducerState::default()),
            }),
            default_test_config(),
            Arc::new(MissingSessionResolver),
        );
        restarted.store.set(Arc::clone(&store)).ok().unwrap();
        restarted.bind_route(7, binding(project.to_str().unwrap(), "ses"));

        let first_after_restart = call_transform_request(&restarted, request_body.clone()).await;
        assert_eq!(
            store.load("ses").unwrap().meta.served_output_fingerprint,
            served_fingerprint_before_restart,
            "the first divergent SOFT+ restart pass must retain the byte-identical served fingerprint"
        );
        let second_after_restart = call_transform_request(&restarted, request_body).await;

        for response in [&first_after_restart, &second_after_restart] {
            assert_eq!(response["decision"], "SOFT+", "{response}");
            assert!(response["materialize_reason"].is_null(), "{response}");
            assert_eq!(
                response["first_divergence"]["block_id_old"], "mc_m1#0",
                "{response}"
            );
            assert_eq!(
                response["first_divergence"]["kind"], "content_changed",
                "{response}"
            );
        }
        assert_eq!(
            store.load("ses").unwrap().meta.served_output_fingerprint,
            served_fingerprint_before_restart,
            "both divergent SOFT+ restart passes must retain the byte-identical served fingerprint"
        );
    }

    #[tokio::test(flavor = "current_thread")]
    async fn status_distinguishes_current_and_historical_divergence() {
        let producer = Arc::new(ProducerState::default());
        let (handler, _store, _dir, _project) = handler_with_store(producer, default_test_config());

        let _ = call_transform_request(&handler, request(vec![ck("m1", 1, "before")])).await;
        let diverging = call_transform_request(&handler, request(vec![ck("m1", 1, "after")])).await;
        assert!(diverging["first_divergence"].is_object());

        let current_status = match handler.handle_status_value(&json!({
            "kind": "status",
            "session_id": "ses",
        })) {
            HandlerOutcome::Response(bytes) => serde_json::from_slice::<Value>(&bytes).unwrap(),
            other => panic!("expected status response, got {other:?}"),
        };
        assert!(current_status["pass_trace"]["first_divergence"].is_string());
        assert!(current_status["pass_trace"]["last_divergence"].is_string());

        let stable = call_transform_request(&handler, request(vec![ck("m1", 1, "after")])).await;
        assert!(stable.get("first_divergence").is_none());
        let stable_status = match handler.handle_status_value(&json!({
            "kind": "status",
            "session_id": "ses",
        })) {
            HandlerOutcome::Response(bytes) => serde_json::from_slice::<Value>(&bytes).unwrap(),
            other => panic!("expected status response, got {other:?}"),
        };
        assert!(stable_status["pass_trace"]["first_divergence"].is_null());
        let historical: Value = serde_json::from_str(
            stable_status["pass_trace"]["last_divergence"]
                .as_str()
                .unwrap(),
        )
        .unwrap();
        assert!(historical["pass_id"].is_number());
        assert!(historical["timestamp_ms"].is_number());
        assert_eq!(historical["divergence"], diverging["first_divergence"]);

        let appended = request(vec![ck("m1", 1, "after"), ck("m2", 2, "before")]);
        let append_only = call_transform_request(&handler, appended.clone()).await;
        assert!(append_only.get("first_divergence").is_none());
        let second_diverging = call_transform_request(
            &handler,
            request(vec![ck("m1", 1, "after"), ck("m2", 2, "after")]),
        )
        .await;
        assert!(second_diverging["first_divergence"].is_object());
        let second_status = match handler.handle_status_value(&json!({
            "kind": "status",
            "session_id": "ses",
        })) {
            HandlerOutcome::Response(bytes) => serde_json::from_slice::<Value>(&bytes).unwrap(),
            other => panic!("expected status response, got {other:?}"),
        };
        let second_historical: Value = serde_json::from_str(
            second_status["pass_trace"]["last_divergence"]
                .as_str()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(
            second_historical["divergence"],
            second_diverging["first_divergence"]
        );
        assert_ne!(
            historical["divergence"]["block_id_old"],
            second_historical["divergence"]["block_id_old"],
            "different divergent blocks must remain distinguishable in the durable trace"
        );
        let stable_again = call_transform_request(
            &handler,
            request(vec![ck("m1", 1, "after"), ck("m2", 2, "after")]),
        )
        .await;
        assert!(stable_again.get("first_divergence").is_none());

        let session_status = tool_body(handler.handle_session_status_value(
            7,
            &json!({ "method": "session.status", "v": 1, "session_id": "ses" }),
        ));
        assert!(session_status["pass_trace"]["first_divergence"].is_null());
        assert!(session_status["pass_trace"]["last_divergence"].is_string());
        assert!(session_status["tail_hygiene"]["u"].is_number());
        assert!(session_status["tail_hygiene"]["reclaimable_tool_output_count"].is_number());
        assert!(session_status["tail_hygiene"]["t"].is_number());
        assert!(session_status["tail_hygiene"]["severity"].is_number());
        assert!(session_status["tail_hygiene"]["evaluable"].is_boolean());
        assert_eq!(session_status["epochs"]["state_sync_deltas"], json!(true));
        assert_eq!(
            session_status["fake_compaction"]["descent_pending"],
            json!({ "build_skew": 0, "no_responses": 0 })
        );
        assert!(session_status["fake_compaction"]["dispositions"]["descended"].is_number());
    }

