    fn wrapup_messages(count: u64, words_per_message: usize) -> Vec<CkIngressMessage> {
        (1..=count)
            .map(|ordinal| {
                ck_with_role(
                    &format!("m{ordinal}"),
                    ordinal,
                    if ordinal % 2 == 0 {
                        "assistant"
                    } else {
                        "user"
                    },
                    &format!("message {ordinal} {}", "word ".repeat(words_per_message)),
                )
            })
            .collect()
    }

