        assert_eq!(body["reason"], json!("snapshot_unavailable"));
        assert_eq!(
            body["summary"],
            "wrapup unavailable while a session transform is in progress"
        );
        assert_eq!(producer.starts.load(Ordering::SeqCst), 0);
