    fn state_sync_compartment(sequence: i64, content: &str) -> Value {
        json!({
            "sequence": sequence,
            "start_message": sequence,
            "end_message": sequence,
            "start_message_id": format!("m{sequence}#0"),
            "end_message_id": format!("m{sequence}#0"),
            "title": format!("c{sequence}"),
            "content": content,
            "p1": format!("{content}-p1"),
        })
    }

    fn paged_seed_batch(
        session: &str,
        seed_id: &str,
        generation: u64,
        expected_seq: u64,
        index: usize,
        total: usize,
        compartments: Vec<Value>,
    ) -> Value {
        let complete = index + 1 == total;
        let mut batch = json!({
            "kind": "state_sync",
            "session_id": session,
            "shadow_generation": generation,
            "expected_shadow_seq": expected_seq,
            "seed_id": seed_id,
            "seed_generation": generation,
            "seed_batch_index": index,
            "seed_batch_total": total,
            "seed_complete": complete,
            "compartments": compartments,
            "memories": [],
            "memory_mutations": [],
            "user_profile": [],
        });
        if complete {
            let object = batch.as_object_mut().unwrap();
            object.insert("seed_boundary_id".to_string(), Value::Null);
            object.insert("workspace".to_string(), Value::Null);
            object.insert("last_todo_state".to_string(), json!("[]"));
            object.insert("acked_watermarks".to_string(), json!({ "complete": true }));
        }
        batch
    }

    #[tokio::test]
    async fn state_sync_receipt_is_generation_fenced_and_staged_progress_is_resumable() {
        let (handler, store, _dir, _project) =
            handler_with_store(Arc::new(ProducerState::default()), default_test_config());
        let probe = json!({ "v": 1, "session_id": "ses", "state_sync_seed_id": "receipt-fixture" });
        let read = || {
            let outcome = handler.handle_session_status_value(7, &probe);
            let HandlerOutcome::Response(bytes) = outcome else {
                panic!("{outcome:?}")
            };
            serde_json::from_slice::<Value>(&bytes).unwrap()
        };
        let first = paged_seed_batch("ses", "receipt-fixture", 0, 0, 0, 2, vec![]);
        assert!(matches!(
            handler.dispatch_value(7, first).await,
            HandlerOutcome::Response(_)
        ));
        assert_eq!(read()["state_sync"]["next_expected_index"], 1);
        let last = paged_seed_batch("ses", "receipt-fixture", 0, 0, 1, 2, vec![]);
        assert!(matches!(
            handler.dispatch_value(7, last).await,
            HandlerOutcome::Response(_)
        ));
        handler.state_sync_seeds.lock().unwrap().sessions.clear();
        assert_eq!(read()["state_sync"]["completed"], true);
        let loaded = store.load("ses").unwrap();
        let mut meta = loaded.meta;
        meta.shadow_generation += 1;
        store
            .commit("ses", loaded.row_version, &loaded.core, &meta)
            .unwrap();
        assert!(read()["state_sync"].is_null());
    }

    #[tokio::test]
